"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[523],{7523:(e,t,o)=>{o.d(t,{mT:()=>s,ad:()=>l,an:()=>a,w7:()=>n,XC:()=>r});let i={id:7,final:!0,title:"灯台の町の最終試験",subtitle:"六つの視点の総合ケース",theme:"戦略の総合（六つの視点の使い分け）",icon:"\uD83C\uDF05",accent:"#ffd67c",blurb:"ここまでに手に入れた六つの視点を、ひとつのケースにすべて使います。第6章の戦略を実行して三か月後の「ひだまり亭」に、もう一度。外を診て、内を診て、立て直しの物語を組み立て、最後は、自分の言葉で語ります。",goals:["六つの視点を、一つのケースで順番に使い分ける","分析の結果を、「だから」でつながる一本の物語にまとめる","自分の言葉で、戦略ストーリーを3分で説明する"],minutes:28,termKeys:[],termPreview:[],status:"ready",scenes:[{kind:"story",id:"f-lighthouse",place:"ノースハーバー ─ 灯台の見える丘",time:"三か月後 午前6:30",lines:[{who:"narrator",text:"三か月後の朝。ノースハーバーの丘の上で、灯台が朝焼けを受けていた。{san}は、ナナ先生に呼ばれて、ひとりでここまで登ってきた。"},{who:"nana",mood:"smile",text:"おはよう、{san}。早い時間に、ありがとう。…この三か月、ひだまり亭は、六日目にまとめた戦略ストーリーのとおりに動いてきたわ。"},{who:"you",mood:"normal",text:"大将は、お元気ですか？ もう、まんぷく弁当は開店したんですよね。"},{who:"nana",text:"ええ、開店したわ。だから、今日が**最終試験**よ。"},{who:"you",mood:"surprise",text:"試験…ですか。何を、覚えてくればよかったんでしょう。"},{who:"nana",mood:"smile",text:"覚えることは、ないの。問題用紙もないわ。ひだまり亭の三か月を、{san}が診て、**立て直しの物語**を、自分で組み立てるのよ。"},{who:"you",mood:"worry",text:"私ひとりで、ですか？"},{who:"nana",mood:"proud",text:"ひとりじゃないわ。{san}の手には、もう六つの道具があるでしょう？ 物語、地図、立ち位置、戦場、武器、そして、束ねる目。"},{who:"nana",text:"今日の私は、答えを言わない。ただ、診る順番だけは、灯台に習って教えるわね。灯台は、まず遠くの海を見て、それから、足元の岩を確かめるの。"},{who:"nana",mood:"smile",text:"**まず外を診て、次に内を診て、それから、進む道を決める**。それだけ守れば、道具は、きっと応えてくれるわ。"},{who:"narrator",text:"水平線から昇った朝日が、灯台のレンズに反射して、丘の上まで細い光を伸ばした。ポケットの中のノートが、少しだけ重く感じられた。"}]},{kind:"story",id:"f-shop",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"午前11:30",lines:[{who:"narrator",text:"三か月ぶりのひだまり亭。暖簾は変わらず、店の前には、昼前から数人が並んでいた。ただ、{san}の記憶にある列より、少し短い気がした。"},{who:"taisho",mood:"smile",text:"おう、来てくれたか！ ちょうどいいところに。まんぷく弁当が開いて二か月、どうも調子が悪くてな。ものさしの数字を、見てもらえるか。"},{who:"you",mood:"think",text:"昼12時台の来店数が、下限を割っているんですね。"},{who:"taisho",mood:"worry",text:"ああ。でも、提供時間は守れてるし、常連さんも来てくれてる。何が起きてるのか、さっぱり分からねえんだ。"},{who:"taisho",mood:"think",text:"それに、パートさんが、常連さんの頼みで煮物を小鉢に詰めて持たせてやってるんだが…あれは、やってていいのかどうか。"},{who:"taisho",mood:"worry",text:"まんぷく弁当は、先週、「手づくり風の煮物弁当」を売り出しやがった。うちの煮物の真似じゃねえのか…？"},{who:"narrator",text:"店の隅の席では、いつのまにか来ていたナナ先生が、湯呑みを手に、何も言わずに頷いた。今日は、答えを言わない約束だ。"},{who:"you",mood:"think",text:"大将、数字と、現場で起きていることを、全部見せてください。順番に診ていきます。"},{who:"taisho",mood:"smile",text:"頼んだぞ。この店の物語、{san}の手で、立て直してくれ。"}]},{kind:"explain",id:"f-ladder",eyebrow:"六つの視点",title:"六つの道具を、診察の順に並べる",blocks:[{type:"p",text:"旅で手に入れた六つの視点は、バラバラの道具ではありません。戦略を診るときの、**六つの問い**です。ひとつずつ「はい」と答えていけるか、はしごにして並べてみましょう。"},{type:"ladder",title:"戦略を診る、六つの問い",steps:[{letter:"1",name:"物語の目（第1章）",question:"打ち手は、「だから」でつながっている？",no:"バラバラの点に戻る。壁のチラシと同じ状態",example:"絞る → 3分で出る → 行列、のように矢印に「だから」が入る"},{letter:"2",name:"地図の目（第2章）",question:"計画に縛られず、現場の芽も見ている？ ひとつの正解に飛びつかず、見渡せている？",no:"計画に固執するか、何でも拾う極端に振れる",example:"常連さんの一言から生まれた「持ち帰り」は、芽かもしれない"},{letter:"3",name:"立ち位置の目（第3章）",question:"誰に・何を・どうやるか、そして、何をやらないかが決まっている？",no:"業務効率の競争に巻き込まれ、位置がぼやける",example:"昼に急ぐ会社員に、15分で出来立て。値下げ競争はしない"},{letter:"4",name:"戦場の目（第4章）",question:"五つの力のうち、いま強いのはどこ？ 変わったのはどこ？",no:"戦う前から、負ける場所に立ってしまう",example:"新規参入だったまんぷく弁当は、開店して「既存の競争」になった"},{letter:"5",name:"武器の目（第5章）",question:"強みは、いまも「効く」武器？ 真似されにくい？",no:"買える武器や、ありふれたものに頼ってしまう",example:"煮物の腕・常連さんの記憶は、時間がかかり、真似されにくい"},{letter:"6",name:"束ねる目（第6章）",question:"分析を、ありたい姿から見直しまで、一本に束ねた？ ものさしは決めてある？",no:"分析は壁に貼られたまま、使われない",example:"外 → 内 → やること → やらないこと → 見直し、の一本の物語"}],goal:{label:"六つ、すべて「はい」",text:"外の変化にも負けず、回り続ける、一本の戦略ストーリー"}},{type:"chain",title:"灯台の順番で診る",nodes:[{label:"外を診る：五つの力は、どう変わった？（戦場の目）",emoji:"\uD83D\uDD2D"},{label:"内を診る：強みは、いまも効いている？（武器の目）",emoji:"\uD83D\uDDE1️",linkLabel:"次に"},{label:"決める：やること・やらないこと・現場の芽（立ち位置の目・地図の目）",emoji:"\uD83C\uDF72",linkLabel:"次に"},{label:"束ねる：一本の物語に書き直し、ものさしを置く（束ねる目・物語の目）",emoji:"\uD83D\uDCD6",tone:"goal",linkLabel:"次に"}],caption:"診る順番を守ると、「いま、どの道具を使うか」で迷いません。"},{type:"nana",mood:"smile",text:"全部を暗記する必要はないの。**迷ったら、外から**。外が分からないまま内を見ても、強みが「何に対して」強いのか、決められないもの。"}]},{kind:"explain",id:"f-case",eyebrow:"ケースファイル",title:"ひだまり亭の、三か月",blocks:[{type:"p",text:"ここに、ひだまり亭の三か月を並べます。**事実だけ**です。事実は、並べただけでは何も語りません。これを、六つの視点で読み解くのが、今日の試験です。"},{type:"compare",left:{label:"ものさしの結果",emoji:"\uD83D\uDCCF",items:["昼12時台の来店数：開店前を100として80（目印の下限は85）","注文から提供まで：平均14分（約束は15分）","常連さんの再来店：ほぼ変わらず","仕入先：二か所。源さんの値上げの影響は小さい"],note:"前に決めておいた、四つの目印です"},right:{label:"現場と、外の変化",emoji:"\uD83D\uDC40",items:["初めてのお客さんが、目に見えて減った","まんぷく弁当が、先週「手づくり風の煮物弁当」を発売した","近所の定食屋の一軒が、昼のランチを始めた","常連さんの頼みで、煮物を小鉢に詰めて持ち帰りに出している（その日のうちに売り切れる）"],note:"コンビニの惣菜・弁当は、三か月前と変わらず"},caption:"並べると、「変わったこと」と「変わっていないこと」が見えてきます。"},{type:"callout",tone:"why",title:"診察の心得",text:"診断は、**事実と照らして**行います。「そう言えそう」ではなく、「この事実が、そう言っている」と言えるかどうかが、診断の確かさです。そして、診たことと、やることが、「だから」でつながっているか。それを、このあとの実践で試します。"},{type:"nana",mood:"normal",text:"ここから先は、{san}の番よ。私は、答えを言わないわ。でも、{san}が「だから」を言えるかどうかは、ちゃんと見ているから。"}]},{kind:"choice",id:"f-practice",title:"ひだまり亭の立て直しを、一本の物語にしよう",intro:"試験の本番です。ケースファイルの事実を使って、ひだまり亭を診てください。診る順番は、外 → 内 → やること → 物語。前の一手と「だから」でつながるほど、矢印が光ります。",notes:["昼12時台の来店数は、開店前を100として80。目印の下限は85","提供は平均14分（約束は15分）。常連さんの再来店は、ほぼ変わらず","初めてのお客さんが、目に見えて減った","まんぷく弁当が先週「手づくり風の煮物弁当」を発売。近所の定食屋の一軒も、昼のランチを始めた","仕入先は二か所で、源さんの値上げの影響は小さい。コンビニの惣菜・弁当は、三か月前と同じ","常連さんの頼みで、煮物を小鉢に詰めて持ち帰りに出している。その日のうちに売り切れる"],nanaIntro:"今日の私は、答えを言わないわ。**外 → 内 → やること → 物語**の順に、事実と照らして選んでね。つながるほど、矢印が光るわよ。",steps:[{id:"outer",nodeLabel:"外",title:"ステップ1 ── 戦場の目：外で、何が変わった？",question:"まず、外を診ます。三か月で来店数が下がった、いちばんの原因は、五つの力のどこにあるでしょう？ 事実に照らして選んでください。",options:[{id:"rivals",emoji:"\uD83C\uDFEA",label:"競争が強まった。まんぷく弁当と、昼を始めた定食屋が、昼の初めてのお客さんを取り合うようになった",short:"競争が強まった",start:"good",reaction:"いい読みね。数字を見て。常連さんの再来店は変わらず、減ったのは「初めてのお客さん」。仕入れも、コンビニも、三か月前と同じよ。**変わったのは、昼の競争相手が増えたこと**ね。"},{id:"supplier",emoji:"\uD83D\uDCE6",label:"売り手の力。源さんの値上げで仕入れ値が上がり、無理が出ている",short:"仕入れ値が原因",start:"ok",reaction:"仕入れは、第4章で見た弱点よね。ただ、観察メモを見て。仕入先は二か所に分けてあって、値上げの影響は小さいわ。**事実と、読みが合っているか**を確かめたいところ。このまま進めてみましょう。"},{id:"convenience",emoji:"\uD83C\uDF59",label:"代替品の脅威。コンビニの惣菜・弁当に、昼の会社員を取られている",short:"コンビニが原因",start:"weak",reaction:"コンビニは強い代替品だけれど、それは**三か月前から同じ強さ**よ。この三か月で「変わったこと」を探してみて。このまま進めて、結果を見ましょう。"}]},{id:"inner",nodeLabel:"内",title:"ステップ2 ── 武器の目：強みは、いまも効いている？",question:"次に、内を診ます。ステップ1の読みを受けて、ひだまり亭の武器を、VRIOの目で確かめましょう。前の一手と「だから」でつながる見立ては、どれでしょう？",options:[{id:"inner-ok",emoji:"\uD83D\uDDE1️",label:"煮物の腕と常連さんの記憶は、いまも効いている（常連さんは離れていない）。ただ、武器が届いているのは「常連さん」まで。初めてのお客さんには、まだ届いていない",short:"武器は健在",detail:"武器は残っている。届け方の問題",requires:["rivals"],reaction:"つながったわ！ 競争が強まっても、常連さんが離れていないのは、真似されにくい武器が**いまも効いている証拠**。「手づくり風」は真似できても、出来立ての腕と、顔を覚えてもらえる関係までは、真似できないもの。課題は、武器が初めてのお客さんに届く**入口**が、少ないことね。",mismatchReaction:"この見立て自体は、筋が通っているわ。でも、ステップ1の読みと「だから」でつながらないの。外の変化を受けて、内の何を確かめているのか、説明できるかしら。"},{id:"inner-copied",emoji:"\uD83E\uDE9E",label:"煮物の腕が真似されて、強みを失った。仕入れの質で、もう一度差をつける必要がある",short:"腕が真似された",detail:"強みが消えた、という見立て",requires:["supplier"],reaction:"「仕入れが原因」という読みとは、筋が通っているわ。ただ、**常連さんが離れていない**という事実と、合っているかしら？ 「手づくり風」は、出来立ての腕そのものではないわ。",mismatchReaction:"「腕が真似された」という見立ては、前の一手とも、事実とも噛み合わないわ。常連さんは離れていないのだから、武器は残っているはずよ。"},{id:"inner-equip",emoji:"\uD83D\uDD27",label:"設備が古いことが弱み。最新のオーブンと設備で、速さと見た目で差をつける",short:"設備で勝負",detail:"買える武器で差をつける",requires:["convenience"],reaction:"「コンビニに負けない速さ」という読みとは、つながっているわね。ただ、第5章を思い出して。**買える武器は、相手も買える**のよ。",mismatchReaction:"設備の話は、前の読みとつながらないわ。しかも、買える武器は、真似されやすいのよ。"}]},{id:"act",nodeLabel:"動き方",title:"ステップ3 ── 立ち位置と、現場の芽：何をやる？ 何をやらない？",question:"診断を受けて、動き方を決めます。ひだまり亭の位置（昼に急ぐ会社員に、15分で、出来立て）と「やらないこと」を踏まえて、現場に生まれた持ち帰りの芽も、どう扱うか選んでください。",options:[{id:"act-focus",emoji:"\uD83C\uDF72",label:"位置とやらないことは守る。そのうえで、煮物の持ち帰りを、小鉢サイズ・昼休みに受け取れる予約制で小さく試し、初めてのお客さんへの入口にする",short:"持ち帰りを試す",detail:"ありたい姿とつながる芽だけ、小さく拾う",requires:["inner-ok"],reaction:"つながったわ！ 武器が「常連さんまで」届いている、という診断から、**入口を足す**のが筋ね。しかも、持ち帰りの芽を、「出来立て・15分」というありたい姿を壊さない範囲に絞って、小さく試している。第2章の「拾う・捨てる」と、第3章の「やらない」が、ここで両立したわ。",mismatchReaction:"この動き方は、いい線をいっているの。でも、前の診断と「だから」でつながっていないわ。どの診断から、この手が出てきたのか、説明できるかしら。"},{id:"act-price",emoji:"\uD83C\uDFF7️",label:"まんぷく弁当に合わせて、値下げと品数の拡大で対抗する。持ち帰りも、弁当メニューとして大量に売る",short:"値下げで対抗",detail:"相手の土俵で戦う",requires:["inner-copied"],reaction:"「腕が真似された」という診断からは、筋が通るわ。ただ、これは第3章の**「やらない」と決めたことを、自分で破る**動きよ。まんぷく弁当の土俵に、上がってしまうわ。",mismatchReaction:"値下げと、弁当の大量販売は、診断と噛み合わないうえ、これまで決めた「やらない」を破ってしまうわ。"},{id:"act-night",emoji:"\uD83C\uDF19",label:"昼の競争から離れて、夜営業と週末に軸足を移す。持ち帰りの芽は、計画にないので止める",short:"夜に軸足を移す",detail:"位置を動かし、芽も止める",requires:["inner-equip"],reaction:"「設備で差をつける」とは、つながるわ。ただ、夜と週末は、人通りが少ないの。**位置を、強みから遠いところへ動かしてしまう**ことにならないかしら。現場の芽も、計画にないというだけで、止めてしまっているわね。",mismatchReaction:"位置を変えるという大きな決断を、前の診断から導けていないわ。逃げ道に飛び込むのは、戦略とは呼べないの。"}]},{id:"story",nodeLabel:"物語",title:"ステップ4 ── 束ねる目：新しい物語と、ものさしは？",question:"最後に、診断とやることを、一本の物語に束ね直し、見直しの仕組みを決めます。ここまでの流れと「だから」でつながる仕上げは、どれでしょう？",options:[{id:"story-new",emoji:"\uD83D\uDCD6",label:"外の変化（競争の増加）→ 内の確認（武器は健在）→ 位置を守り、持ち帰りを足す、をひとつの物語に書き直す。ものさしに「初めてのお客さんの数」を足し、毎月、外 → 内 → 打ち手の順に見直す",short:"物語を書き直す",detail:"ものさしも、外の変化に合わせて足す",requires:["act-focus"],reaction:"来たわね！ 外 → 内 → やること → ものさし。矢印の全部に「だから」が入った、**一本の物語**よ。しかも、新しいものさし（初めてのお客さん）が、今回の「ずれ」の正体と、ちゃんと対応しているわ。",mismatchReaction:"物語を書き直すのは、いい判断。でも、ここまでの診断ややることと「だから」でつながっていないわ。書き直した物語を、三分で説明できるかしら。"},{id:"story-lower",emoji:"\uD83D\uDCC9",label:"価格競争になったので、ものさしの下限を引き下げ、「利益が出ていれば順調」と見ることにする",short:"下限を下げる",detail:"基準を、あとから甘くする",requires:["act-price"],reaction:"「値下げで対抗」という動きとは、つながるわ。ただ、ものさしの基準を**あとから甘くする**のは、見直しの意味をなくしてしまうの（第6章）。",mismatchReaction:"基準を下げても、診断とも、やることとも、つながらないわ。ずれが何から生まれたのか、見えなくなるだけよ。"},{id:"story-redo",emoji:"\uD83E\uDDF1",label:"ありたい姿から、全部作り直す。ひだまり亭は夜の店として、物語を最初から書く",short:"全部作り直す",detail:"これまでの積み上げを、手放す",requires:["act-night"],reaction:"「夜に軸足を移す」とは、つながるけれど、**積み上げた強みも、全部手放してしまう**わ。見直しは、変わった所から順に直すものよ（第6章）。",mismatchReaction:"全部を作り直すのは、いちばん大きな決断なのに、前の流れから導けていないわ。変わった所から直すほうが、早くて確実よ。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"外と内を診て、一本の物語に書き直した",quality:1,when:{firstPick:["rivals"],matches:[3]},narration:"半年後。ひだまり亭の昼の来店数は、開店前の水準を取り戻しました。小鉢の持ち帰りは、昼休みに予約して受け取る会社員に広まり、初めてのお客さんが、また増えています。毎月の点検では、外 → 内 → 打ち手の順に、数字と現場を見ていきます。大将は言いました。「前は『なんとなく不安』だったのが、いまは、何を見ればいいか分かるな。ずれたら、直せばいい」。",nana:"合格よ。**外を診て、内を診て、やることを決め、物語に束ねる**。六つの視点を、順番に使えたわね。第1章のバラバラなチラシが、いまは、外の変化にも負けない一本の物語になったわ。さあ、旅の最後に、{san}の言葉で、この物語を語ってみましょう。"},{id:"linked-supplier",emoji:"\uD83D\uDCE6",title:"筋は通ったけれど、最初の読みが外れていた",quality:.5,when:{firstPick:["supplier"],matches:[3]},narration:"値下げと品数の拡大で、まんぷく弁当に対抗しました。仕入れ値の上昇に、品数の増加が重なり、厨房は混乱。常連さんのお目当てだった煮物の味にも、ばらつきが出ました。「安くて、品数の多い店」になったとき、大将には、自分の店がどんな店なのか、分からなくなっていました。",nana:"矢印は、全部「だから」でつながっていたわ。でも、**最初の読みが、事実と合っていなかった**の。常連さんが離れていないのに、仕入れのせいにしてしまったわね。外の診断を外すと、その後の筋が通っても、届かないのよ。"},{id:"linked-convenience",emoji:"\uD83C\uDF19",title:"筋は通ったけれど、強みから遠ざかった",quality:.4,when:{firstPick:["convenience"],matches:[3]},narration:"夜営業を始め、設備も新しくしました。ところが、夜の客足は伸びず、設備の差も、すぐに追いつかれました。昼の常連さんは、大将が昼に集中しなくなったと感じ、少しずつ足が遠のきました。物語は一からやり直しになりましたが、積み上げた強みの多くは、元に戻せませんでした。",nana:"全部の矢印はつながっていたけれど、出発点の「コンビニが原因」は、三か月前から変わらない事実だったわ。**変わったことを診ずに、変わっていないものに手を打った**のね。そして最後は、武器ごと手放してしまった。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、診断と手がずれた",quality:.4,when:{matches:[2,1]},narration:"最初のうちは、診断にも手応えがありました。でも、途中で選んだ動き方が、診断と噛み合わなくなり、現場では、何を目指しているのか、分からなくなってきました。",nana:"どこかで、「だから」が切れてしまったわね。**外 → 内 → やること → 物語は、四つで一組**。診断が正しくても、やることが別の方向を向くと、全体が弱くなるの。もう一度、前の一手とのつながりを確かめてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"診断も、動き方も、バラバラだった",quality:.1,narration:"診たことも、やったことも、見直し方も、それぞれ別の方向を向いていました。三か月後、ひだまり亭の壁には、また新しいチラシが並んでいました。",nana:"最初の壁と、同じ場所に戻ってきてしまったわね。でも、これが、第1章の「バラバラ」の正体よ。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"explain",id:"f-speech",eyebrow:"3分で語る",title:"戦略ストーリーを、自分の言葉で",blocks:[{type:"p",text:"試験は、ここまで。最後は、自分の言葉で語る練習です。戦略は、頭の中にあるだけでは動きません。大将にも、パートさんにも、通じて初めて、現場が動き出します。"},{type:"list",style:"number",title:"3分で語る、五つの文（ひだまり亭の例）",items:["ありたい姿は、昼に急ぐ会社員が、15分でほっとできる「いつもの店」です。","外を見ると、昼の会社員は多く、近所の定食屋は昼が手薄でした。ただ、まんぷく弁当と、昼を始めた定食屋が、初めてのお客さんを取り合っています。","内には、煮物の腕と常連さんの記憶という、真似されにくい武器があります。弱みは、大将ひとり頼りと、初めてのお客さんへの入口が少ないことです。","だから、品数を絞り、15分で出来立てを出すことは守ります。値下げと夜営業は、やりません。そのうえで、小鉢の持ち帰りを、昼休みに受け取れる予約制で試し、初めてのお客さんへの入口にします。","昼12時台の来店数、提供時間、常連さんの再来店、初めてのお客さんの数を、毎月見ます。ずれたら、外 → 内 → 打ち手の順に直します。"]},{type:"callout",tone:"point",title:"声に出してみよう",text:"読むだけでなく、**自分の言葉に置き換えて、声に出して**みてください。ひだまり亭を、あなたの職場や、いま考えている商売に置き換えても構いません。3分で話せたら、その戦略は、頭の中で一本につながっています。"},{type:"callout",tone:"why",title:"うまく話せないときは",text:"つまずいた文が、つながりの弱い場所です。「だから」が言えないところを、六つの視点で見直します。外の話が弱ければ戦場の目、やることが弱ければ立ち位置の目、全体がまとまらなければ、束ねる目です。"},{type:"nana",mood:"proud",text:"六日間かけて集めた視点を、三分に束ねる。それが、戦略を**持つ**ということよ。"}]},{kind:"quiz",id:"f-quiz",title:"最終クイズ ── 六つの視点",intro:"旅の総仕上げです。六つの視点を、1問ずつ確かめましょう。「なぜ？」の解説まで読むのが、いちばんの復習よ。",questions:[{id:"q1",scenario:"大将が、新メニューを三つ足したいと言います。「なぜ？」と聞くと、「いま流行っているから」と返ってきました。",question:"第1章の見方で、この打ち手に足りないものは何でしょう？（物語の目）",options:[{text:"味の良さ",feedback:"味は大切だけれど、問題はそこではないわ。「なぜ、それをやるのか」が、物語の中にないことよ。"},{text:"前の一手と、「だから」でつながる筋（[[inga-ronri|因果論理]]）",feedback:"その通り！ 打ち手を点で見ると、どれも良さそうに見える。線で見て、「だから」が言えるかが、第1章の問いよ。"},{text:"新メニューの数",feedback:"数の問題ではないの。足すほど、壁のチラシが増えるだけよ。"}],answer:1,explanation:"[[strategy-story|戦略ストーリー]]は、打ち手が「だから」でつながった一本の筋。「流行っているから」は、ありたい姿からの「だから」ではありません。つながらない打ち手は、どんなに良さそうでも、物語の外に置きます。"},{id:"q2",scenario:"常連さんの一言から、計画になかった煮物の持ち帰りを試したところ、その日のうちに売り切れました。",question:"第2章の見方では、これをどう扱うのがよいでしょう？（地図の目）",options:[{text:"計画的戦略なので、そのまま全面展開する",feedback:"計画になかったのだから、計画的戦略ではないわ。また、芽の段階で全面展開は、急ぎすぎよ。"},{text:"計画にないので、すぐに止める",feedback:"現場にしかない発見を、捨ててしまうことになるわ。変化が速いときほど、芽は貴重よ。"},{text:"[[emergent|創発的戦略]]の芽。ありたい姿とつながるか確かめて、小さく試し、拾うかどうか決める",feedback:"その通り！ 拾う・捨てるの基準を持つのが大事。ありたい姿とつながる芽だけを、小さく試して育てるの。"},{text:"ただの偶然なので、戦略とは関係がない",feedback:"偶然に見えても、繰り返されるなら、現場が教えてくれた戦略の芽かもしれないわ。"}],answer:2,explanation:"[[emergent|創発的戦略]]は、やっているうちに形になる戦略。何でも拾うと、壁のチラシに戻ってしまうので、**ありたい姿とつながるか**で選びます。計画（[[deliberate|計画的戦略]]）と現場の芽は、どちらかではなく、両方を見渡して使います。"},{id:"q3",scenario:"まんぷく弁当が、値下げ攻勢をかけてきました。",question:"第3章の見方で、ひだまり亭が最も大切にすべきことは？（立ち位置の目）",options:[{text:"「やらない」と決めた値下げ競争を守り、位置（昼の会社員・15分・出来立て）で戦う",feedback:"その通り！ 位置とは、やらないことを含めて決まるもの。相手の土俵に上がらないのも、戦略よ。"},{text:"同じ値段まで下げて、お客さんを引き止める",feedback:"[[operational-effectiveness|業務効率]]の競争に巻き込まれてしまうわ。規模の大きい相手の得意な土俵よ。"},{text:"品数を増やして、選ぶ楽しさで対抗する",feedback:"品数を増やすと、仕込みと提供が遅くなり、「15分」の約束が崩れるわ。[[trade-off|トレードオフ]]よ。"}],answer:0,explanation:"[[positioning|ポジション]]は、誰に・何を・どうやるか、そして**何をやらないか**で決まります。やらないことを守るから、活動が噛み合い、[[activity-system|活動システム]]として真似されにくくなります。"},{id:"q4",scenario:"三か月前、まんぷく弁当の開店は「新規参入の脅威」として見ていました。そのまんぷく弁当が、いま、実際に開店しています。",question:"[[five-forces|五つの力]]で整理し直すと、どう言えるでしょう？（戦場の目）",options:[{text:"何も変わらない",feedback:"開店前の「脅威」が、開店後は、実際の競争に変わっているわ。力関係は、読み直す必要があるの。"},{text:"売り手の力が強くなった",feedback:"観察メモでは、仕入先は二か所に分けてあって、値上げの影響は小さいわ。事実と合っていないわね。"},{text:"代替品の脅威がなくなった",feedback:"コンビニの惣菜・弁当は、三か月前と同じ強さで残っているわ。"},{text:"「新規参入の脅威」だったものが、「既存の競争」に変わった。力関係を読み直す必要がある",feedback:"その通り！ 戦場は、一度読んで終わりではないの。開店という変化のあとに、もう一度読み直すのよ。"}],answer:3,explanation:"五つの力は、**状況が変わったら読み直す**ものです。新規参入だった相手が、既存の競争相手になれば、力関係が変わります。外の変化を診るのが、見直しの最初の一歩です。"},{id:"q5",scenario:"まんぷく弁当が「手づくり風の煮物弁当」を発売しました。大将は、「うちの煮物は、もう武器じゃなくなったのか」と心配しています。",question:"[[vrio|VRIO]]の目で、いちばん確かめたい問いは何でしょう？（武器の目）",options:[{text:"その武器に、価値はあるか",feedback:"価値は、すでに確かめられているわ。今回の不安は、真似されたかどうかにあるの。"},{text:"「風」は真似できても、腕・出来立て・常連さんの記憶まで、真似されにくいか",feedback:"その通り！ [[inimitability|真似されにくさ]]を、具体的に確かめる問いよ。形を真似ることと、積み重ねを真似ることは、別なの。"},{text:"設備が、新しいかどうか",feedback:"設備は、買える武器。差がつくのは、買えないほうの資源よ。"}],answer:1,explanation:"「真似された」と感じたら、**何を真似されたのか**を分けて考えます。見た目や形は真似できても、時間をかけて育った腕や、顔を覚えてもらえる関係は、簡単には真似できません。それが[[resources|資源]]の強さです。"},{id:"q6",scenario:"ひだまり亭は、三か月の実行のあと、数字を見て、立て直しを考えています。",question:"[[strategy-process|戦略策定プロセス]]の六段階で言うと、いまは、どう動いていることになるでしょう？（束ねる目）",options:[{text:"実行を止めて、分析だけを続けている",feedback:"分析ばかりで動けない「動けない型」ね。分析は、選ぶための材料よ。"},{text:"最初の「ありたい姿」だけを、やり直している",feedback:"ありたい姿を描き直すこともあるけれど、今回は、分析から入るのが先よ。"},{text:"「見直す」から「分析する」へ戻り、もう一周している",feedback:"その通り！ 六段階は一方通行ではなく、ぐるぐる回すもの。見直しが、次の一周の入口になるのよ。"}],answer:2,explanation:"戦略づくりは、**ありたい姿 → 分析 → 選択肢 → 選ぶ → 実行 → 見直し**を、行きつ戻りつ回すこと。見直しで外の変化に気づいたら、分析へ戻り、物語を書き直して、また一周します。"}]},{kind:"summary",id:"f-summary",title:"旅のふりかえり ── 六つの視点",points:[{title:"第1章　つながりで見る目",text:"打ち手を「点」でなく「線」で見る。[[strategy-story|戦略ストーリー]]は、「だから」でつながった一本の筋です。"},{title:"第2章　全体を見渡す目",text:"ひとつの正解に飛びつかない。計画（[[deliberate]]）と、現場の芽（[[emergent]]）の両方を見渡します。"},{title:"第3章　やらないことを選ぶ目",text:"選ぶとは、捨てること。[[positioning|ポジション]]は、やらないことを含めて決まり、[[trade-off]]を受け入れた活動が噛み合います。"},{title:"第4章　力関係を見抜く目",text:"戦う前に、戦場を読む。[[five-forces|五つの力]]は、状況が変わるたびに読み直します。"},{title:"第5章　強みを見極める目",text:"「あるもの」と「効くもの」を分ける。[[vrio]]の問いで、真似されにくい武器を見つけます。"},{title:"第6章　物語に束ねる目",text:"分析を、筋のある一本にする。[[strategy-process]]を回し、ものさしで見直します。"}],why:{title:"なぜ、これが大事なのか",text:"戦略は、ひとつの道具では完成しません。外を診る道具、内を診る道具、選ぶ道具、束ねる道具。**道具の名前よりも、使う順番と、つなぎ方**が、現場で効きます。そして、「いま、どの視点で見ているか」を言えることが、迷ったときの足場になります。この六つの視点は、経営だけでなく、自分の仕事や、キャリアの選び方にも、そのまま使えます。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま、{san}。六日間と、最終試験。よく、ここまで来たわね。"},{who:"you",mood:"smile",text:"最初は、壁のチラシがバラバラで、何から手をつければいいか分かりませんでした。いまは、外を診て、内を診て、「だから」でつなぐ順番が、体に入っている気がします。"},{who:"nana",mood:"smile",text:"それが、いちばんの収穫よ。灯台は、嵐を止めることはできないけれど、進む道を照らしてくれる。{san}の六つの視点も、同じ。"}]}],clear:{perspective:{icon:"\uD83C\uDF05",name:"戦略を語る目",tagline:"診て、決めて、束ねて、語る",description:"物語、地図、立ち位置、戦場、武器、束ねる目。六つの視点を順番に使い、一本の戦略ストーリーとして語れるようになりました。誰かの戦略を聞いたら、「外と内は診た？ やらないことは決まった？ 見直しは？」と、そっと問いかけてみてください。",checks:["外（戦場）と内（武器）の両方を診た？","やることと、やらないことは、物語でつながっている？","三分で、「だから」でつなげて語れる？"]},nana:[{who:"nana",mood:"proud",text:"おめでとう、{san}。最終試験、合格よ。そして、最後の視点「戦略を語る目」を手に入れたわね。"},{who:"you",mood:"smile",text:"ありがとうございます、ナナ先生。これで、旅はおしまいなんですね。"},{who:"nana",mood:"smile",text:"いいえ、ここからが本番。{san}自身の仕事や、商売、これからの選択に、六つの視点を使ってみて。灯台の灯は、{san}の中にも、もう灯っているわ。"}],teaser:"旅はここまで。ここからは、自分の仕事や商売で、六つの視点を使ってみてください。ノートには、獲得した視点と、出会った用語が残っています。"}},a=[{id:1,title:"物語の力",subtitle:"ストーリーとしての競争戦略",theme:"ストーリーとしての競争戦略",icon:"\uD83D\uDCD6",accent:"#ffc247",blurb:"入社初日。最初の依頼主は、お客さんが減り続ける商店街の定食屋。行列のできるお店と、何でもやっているのに空席のお店。その差を生んでいる「見えない筋」を、日常のたとえ話だけで解き明かします。",goals:["戦略が「やることリスト」ではなく「つながった物語」だと、自分の言葉で説明できる","打ち手の「つながり」が、なぜ真似されにくさ（長く続く強さ）を生むのかが言える","「競争優位」「戦略ストーリー」「因果論理」の3つの言葉を、日常の例えで説明できる"],minutes:25,termKeys:["kyoso-yui","strategy-story","inga-ronri"],termPreview:["競争優位","戦略ストーリー","因果論理"],status:"ready",scenes:[{kind:"story",id:"s1-office",place:"ノースハーバー ─ ノースライト戦略研究所",time:"入社初日 午前9:00",lines:[{who:"narrator",text:"港を見下ろす高台に、白い壁の小さな建物がある。ここが、経営の悩みを抱えた人たちが訪ねてくる『ノースライト戦略研究所』。"},{who:"narrator",text:"今日から、あなたはここの新米コンサルタント。胸の名札は、まだ新品のままだ。"},{who:"nana",mood:"smile",text:"ようこそ、{san}。主任コンサルタントのナナです。みんなには『ナナ先生』って呼ばれてるわ。"},{who:"you",mood:"worry",text:"よ、よろしくお願いします！ …ただ、戦略とか経営とか、正直まだ全然わかっていなくて。"},{who:"nana",mood:"smile",text:"大丈夫。最初から「わかってる人」なんていないもの。むしろ、わからないところから始めるのが、いちばん強いのよ。"},{who:"nana",text:"さっそく一つ聞かせて。『戦略』と聞いて、何を思い浮かべる？"},{who:"you",mood:"think",text:"うーん…「頭のいい人が考える、難しい計画」…でしょうか？"},{who:"nana",mood:"smile",text:"いい答え。半分は当たりで、半分は「もったいない」。この旅では、そのイメージを、もっと身近で、もっと使えるものに変えていくわ。"},{who:"nana",text:"安心して。**最初のうちは、難しい言葉を一つも使わない**。毎日の暮らしの例え話だけで、核心まで連れていくから。"},{who:"you",mood:"smile",text:"ほっとしました…！ それなら、ついていけそうです。"},{who:"nana",mood:"think",text:"ただし、約束が一つ。「なんとなく」で読み流さないこと。**『なぜ？』を口ぐせにして**。それが、コンサルタントのいちばんの武器だから。"},{who:"nana",mood:"proud",text:"さあ、最初のお客さんのところへ行きましょう。商店街の定食屋さんよ。"}]},{kind:"story",id:"s1-hidamari",place:"商店街〈ひだまり通り〉 ─ 定食屋『ひだまり亭』",time:"午前11:00",lines:[{who:"narrator",text:"坂を下りて十分。商店街の角に、年季の入った暖簾が揺れている。最初の依頼主、定食屋『ひだまり亭』だ。"},{who:"narrator",text:"もう開店の時間だというのに、店内にお客さんの姿はない。"},{who:"taisho",mood:"worry",text:"ナナ先生、来てくれてありがとう…。ここ半年、お客さんが減る一方でね。"},{who:"nana",mood:"smile",text:"大将、お久しぶり。まずは、お店の様子を見せてもらうわね。"},{who:"taisho",text:"周りの店がやってることは、うちも全部やってみたんだ。まあ、壁を見てくれ。"},{who:"narrator",text:"壁には、色あせたチラシと貼り紙がびっしり。『全品50円引き』『メニューが60品に！』『ポイントカード始めました』『お弁当、はじめました』『ランチ限定コースあります』『SNSもやってます』"},{who:"you",mood:"surprise",text:"すごい…！ やれることは、ほとんど全部やっていますね！"},{who:"taisho",mood:"worry",text:"だろう？ それなのに、売上は下がる一方でさ。仕込みも増えて、毎日クタクタなんだ。"},{who:"nana",mood:"think",text:"…なるほどね。{san}、この壁を見て、何か引っかかる？"},{who:"you",mood:"think",text:"どれも、悪い施策じゃなさそうなのに…なんだか、**「バラバラ」**な感じがします。"},{who:"nana",mood:"proud",text:"…！ いい勘してる。その「バラバラ」という感覚が、今日いちばん大事なヒントよ。"},{who:"nana",mood:"smile",text:"大将、今日は一日お店を見させてもらうわね。{san}、まずはお昼を食べに行くわよ。"},{who:"you",mood:"surprise",text:"えっ、ここで食べないんですか？"},{who:"nana",text:"その答えは、「行列のできるお店」を見てからのほうが早いの。ついてきて。"}]},{kind:"story",id:"s1-sakura",place:"駅前の路地 ─ さくら食堂",time:"正午",lines:[{who:"narrator",text:"正午。駅前の細い路地に、昼休みのスーツ姿の列が伸びていた。『さくら食堂』。ひだまり亭から歩いて七分の店だ。"},{who:"you",mood:"surprise",text:"すごい行列…！ でも、看板のメニューが、一つしかないですね？"},{who:"nana",mood:"smile",text:"『本日の定食 八百円』。これだけ。席はカウンターが十席。夜は営業していないの。"},{who:"narrator",text:"列は、思ったよりも速く進んでいく。席につくと、注文から三分ほどで湯気の立つ定食が目の前に置かれた。"},{who:"narrator",text:"食べ終えた会社員が、十五分ほどで席を立つ。「ごちそうさま」の声と入れ替わりに、次の人が座る。"},{who:"you",mood:"think",text:"選べないのに、どうしてこんなに人気なんでしょう。普通は「選べる方が親切」ですよね？"},{who:"nana",mood:"smile",text:"いい疑問ね。ちなみに、料理の腕だけなら、ひだまり亭の大将のほうが上だと私は思っているわ。"},{who:"you",mood:"surprise",text:"えっ！ それなのに、こちらは行列で、ひだまり亭は空席…？"},{who:"nana",mood:"proud",text:"そこが今日の謎。**「おいしい」だけでは、お店は決まらない**。食べながら、その理由を一緒に解いていきましょう。"}]},{kind:"explain",id:"s1-trip",eyebrow:"核心① ／ 考え方のちがい",title:"「やることリスト」と「物語」はちがう",blocks:[{type:"nana",mood:"smile",text:"さくら食堂が行列になった理由は、実はメニューの数でも、味でもないの。まず、旅行の話から始めましょう。"},{type:"p",text:"週末の旅行を計画するところを想像してください。ガイドブックには、行きたくなる場所がいくつも載っています。さて、あなたならどう計画しますか？"},{type:"compare",left:{label:"やることリスト型の旅",emoji:"\uD83D\uDDD2️",items:["有名な観光地を、とにかく全部入れる","朝から晩まで、移動と行列でぎっしり","「行った」という事実だけが残る","終わると、疲れだけが残りがち"],note:"並べただけ"},right:{label:"物語型の旅",emoji:"\uD83D\uDCD6",items:["「古い町並みで、ゆっくり過ごす」と先に決める","宿・食事・移動を、その目的に合わせて選ぶ","一つひとつの選択に「理由」がある","終わると「いい旅だった」という一本の記憶が残る"],note:"つながっている"}},{type:"callout",tone:"point",title:"同じ予算・同じ日数でも",text:"何をやるかを**並べただけ**の旅と、なぜそれをやるかが**つながった**旅では、満足度がまるで違います。"},{type:"p",text:"お店の経営も、まったく同じです。「値下げする」「メニューを増やす」「SNSを始める」。どれも、一つだけ見れば「良さそうな一手」。でも、それぞれが**何のためにあって、どうつながっているのか**が見えないと、ただの「やることリスト」になってしまいます。"},{type:"nana",mood:"think",text:"「いい打ち手を集めれば、いい戦略になる」…つい、そう思っちゃうのよね。でも実は、逆なの。"},{type:"callout",tone:"why",title:"なぜ「つながり」が大事なの？",text:"お店が使える時間・お金・人手には、限りがあります。つながっていない一手は、その限りある力を、ほかの一手と引っ張り合いながら使ってしまう。反対に、**つながった一手は、前の一手の力を借りて、次の一手を軽くしてくれる**。同じ力でも結果に大きな差がつくのは、そのためです。"}]},{kind:"explain",id:"s1-sakura-chain",eyebrow:"核心② ／ 行列の秘密",title:"さくら食堂には、一本の筋が通っている",blocks:[{type:"p",text:"さくら食堂がやっていることを、一つずつ分けて眺めてみましょう。『昼だけ営業』『日替わり1種類』『カウンターのみ』『注文から3分』『八百円』。バラバラに見ると、ただの「制限だらけの店」に見えます。"},{type:"nana",mood:"smile",text:"でもね、これを矢印でつないでみると、景色がガラッと変わるの。"},{type:"chain",title:"さくら食堂の「だから」の連なり",nodes:[{emoji:"\uD83C\uDFAF",label:"お客さんを「昼休みに急ぐ会社員」に絞る"},{emoji:"\uD83C\uDF71",label:"メニューは日替わり1種類だけにする"},{emoji:"\uD83E\uDD6C",label:"仕込みが少なく、食材のムダも減る"},{emoji:"⏱️",label:"注文から3分で出せる"},{emoji:"\uD83D\uDEAA",label:"昼休みの1時間以内に食べ終えて戻れる"},{emoji:"\uD83D\uDD25",label:"会社員が毎日のように通い、行列ができる"},{emoji:"\uD83D\uDCB0",label:"回転が上がり、八百円でもしっかり利益が残る",tone:"goal"}],caption:"矢印のどこにも「たまたま」が入っていません。"},{type:"callout",tone:"point",title:"見分けるコツ：矢印に「だから」を書けるか",text:"**矢印の間に「だから」が自然に入れば、それは物語。入らなければ、ただの並び。** さくら食堂は、最初の一手から最後の結果まで、ぜんぶ「だから」でつながっています。"},{type:"callout",tone:"warn",title:"「日替わり1種類」だけを見ると…",text:"この一手だけを切り取ると、むしろ「選ぶ楽しみがない、不親切なお店」に見えます。でも物語全体の中では、**「3分で出す」を支える、いちばん大事な一手**。部品の価値は、それだけでは決まりません。全体の中でどんな役割を果たすかで決まります。"},{type:"nana",mood:"proud",text:"「いい打ち手」かどうかは、単体では決まらない。**つながりの中で決まる**。これが、今日の最初の大きな発見よ。"}]},{kind:"explain",id:"s1-wall",eyebrow:"核心③ ／ もう一度、あの壁を",title:"ひだまり亭の「バラバラ」の正体",blocks:[{type:"p",text:"では、午前中に見たひだまり亭の壁に戻りましょう。{san}が感じた「バラバラ」の正体を、さくら食堂と同じ見方で確かめます。"},{type:"clash",title:"ぶつかり合う打ち手",items:[{a:"全品50円引き",b:"メニューを60品に",result:"利益が薄いのに、仕込みの手間とムダだけが増える。値下げで稼ぐはずの売上が、増えた手間に消えていく。"},{a:"お弁当をはじめた",b:"店内の接客",result:"厨房も人手も限られている。弁当づくりに手を取られ、店内のお客さんを待たせてしまう。"},{a:"ランチ限定コース",b:"ポイントカード",result:"コースは「ゆっくり贅沢に」、ポイントは「気軽に何度も」。誰に来てほしいのかが、まるでバラバラ。"}]},{type:"p",text:"一つひとつは、よその店で効果が出た「良い打ち手」かもしれません。でも、ひだまり亭の中では、**お互いに足を引っ張り合っている**のです。"},{type:"callout",tone:"why",title:"なぜ「全部やる」が危ないの？",text:"打ち手を増やすほど、限られた時間・お金・人手が薄く散らばります。しかも、増えた分だけ「ぶつかる組み合わせ」も増えていく。**打ち手が増えるほど強くなるわけではありません**。むしろ筋が見えなくなって、現場も迷いやすくなります。"},{type:"nana",mood:"think",text:"大将は怠けていたわけじゃない。むしろ、頑張りすぎていたの。ただ、**「つながり」という物差し**が無かっただけ。"}]},{kind:"explain",id:"s1-imitate",eyebrow:"核心④ ／ 真似されにくさ",title:"なぜ、つながりは真似されにくいのか",blocks:[{type:"p",text:"ここで、少し意地悪な質問です。もし、さくら食堂の隣に新しい店ができて、**「日替わり1種類」だけをそっくり真似**したら、同じように行列ができるでしょうか？"},{type:"nana",mood:"smile",text:"答えは、たぶんNO。理由を、料理のレシピで考えてみましょう。"},{type:"compare",left:{label:"真似できるもの",emoji:"\uD83E\uDDFE",items:["使っている食材の種類","メニューの見た目や名前","「日替わり1種類」という“やり方”","看板や値段"],note:"材料リスト（部品）"},right:{label:"真似しにくいもの",emoji:"\uD83D\uDD25",items:["なぜその順番で、その火加減なのか","「誰に」から「3分で出す」までの理由のつながり","仕込み・席・時間帯・価格が噛み合った全体","「やらない」と決めたことの積み重ね"],note:"手順と火加減（つながり）"}},{type:"p",text:"材料リスト（部品）は、見ればわかります。でも、**手順と火加減（つながり）は、外からは見えません**。だから、部品だけ真似しても、同じ味にはならないのです。"},{type:"callout",tone:"example",title:"もう一つの例：文化祭",text:"クラスの出し物を「お化け屋敷」に決めたとします。装飾は暗く、衣装は不気味に、順路は迷路のように、音は怖く…と、**すべてが「怖がらせる」に向けてそろう**から、いい出し物になります。ここにカフェも射的も足したら、準備は間に合わず、雰囲気もぼやけてしまいますよね。"},{type:"callout",tone:"point",title:"一見、非合理に見える一手",text:"さくら食堂の「選べない定食」は、ほかの店から見ると「不親切」で「もったいない」一手です。**だから、真似されにくい**。ライバルが「それはやらないよ」と思うことを、つながりの中で堂々とやっている。ここに強さの秘密があります。"},{type:"list",style:"number",title:"つながりが効く3つの理由",items:["**真似しにくい**：部品ではなく「全体」を真似しなければならない","**ブレにくい**：迷ったとき「これは物語に合うか？」で判断できる","**現場が動きやすい**：「なぜ」が共有されるので、一人ひとりが自分で判断できる"]}]},{kind:"explain",id:"s1-why",eyebrow:"核心⑤ ／ いちばん大事な「なぜ」",title:"そもそも、なぜ「違い」が必要なのか",blocks:[{type:"p",text:"最後に、いちばん根っこの「なぜ？」に踏み込みましょう。そもそも、どうして戦略は「物語」でなければならないのでしょうか。"},{type:"p",text:"もし、近所の定食屋がみんな「同じメニュー・同じ値段・同じ接客」だったら、お客さんは何を基準に店を選ぶでしょう？ **残るのは「どっちが安いか」だけ**です。"},{type:"chain",title:"「同じ」が行き着く先",nodes:[{emoji:"\uD83D\uDD01",label:"みんなが同じことをする"},{emoji:"⚖️",label:"お客さんには違いが見えない"},{emoji:"\uD83C\uDFF7️",label:"選ぶ基準が「値段」だけになる"},{emoji:"\uD83D\uDCC9",label:"値下げ合戦になり、どの店も利益が残らない",tone:"bad"}]},{type:"callout",tone:"why",title:"だから、「違い」と「つながり」",text:"お客さんに選ばれ続けるには、ほかにはない**「違い」**が必要です。でも、違いを一つだけ作っても、すぐ真似されてしまいます。そこで、違いを**「つながり」**で支えて、全体として真似されにくくする。この二つがそろって初めて、長く続く強さになります。"},{type:"formula",parts:[{label:"違い",sub:"選ばれる理由"},{label:"つながり",sub:"真似されにくさ"},{label:"続く強さ",sub:"長く選ばれる"}],ops:["\xd7","＝"],caption:"どちらか一方では、長続きしません。"},{type:"callout",tone:"point",title:"「やらないこと」も物語の一部",text:"さくら食堂は「夜をやらない」「メニューを増やさない」「個室をつくらない」と決めています。**何をやらないかは、何をやるかと同じくらい、物語の輪郭をつくります**。この考え方は、第3章でもっと深く掘り下げます。"},{type:"nana",mood:"smile",text:"ここまでで、「戦略はつながった物語である」という核心は、もう掴めたはず。次は、ここまで日常の言葉で話してきたことに、**名前**をつけていきましょう。"}]},{kind:"terms",id:"s1-terms",title:"ここまでの話に、名前をつけよう",intro:[{who:"nana",mood:"smile",text:"ここまで、難しい言葉は使わずに来たわよね。でも実は、今日の発見には、経営の世界でちゃんと名前がついているの。"},{who:"nana",text:"名前がつくと、頭の中で扱いやすくなるし、誰かに説明するときにも便利。{san}、3つだけ持ち帰ってね。"},{who:"you",mood:"smile",text:"はい！ お願いします。"}],terms:["kyoso-yui","strategy-story","inga-ronri"]},{kind:"choice",id:"s1-practice",title:"ひだまり亭の物語を、組み立てよう",intro:"午後三時。ひだまり亭に戻った二人に、大将が言いました。「うちの店の“物語”を、一緒に作ってくれないか」。ここからは{san}の番です。",notes:["平日の昼12時台、店の前を歩く会社員はとても多い。ただし「並んでいたら諦める」人が大半。","昼休みはおよそ1時間。店までの往復で15分ほどかかる。","大将の煮物と焼き魚は、近所で評判。腕は確か。","席は12席。厨房は、大将とパートさん1名だけ。","夜と週末は、商店街の人通りが少ない。"],nanaIntro:"正解を当てるクイズじゃないわ。**選んだ一手が、前の一手と「だから」でつながるか**を見てね。つながるほど、矢印が光るわよ。",steps:[{id:"who",nodeLabel:"誰に",title:"ステップ1 ── 誰に、どんな価値を届ける？",question:"物語の出発点を決めましょう。観察メモを見ながら、どんなお客さんに、何を届けるお店にしますか？",options:[{id:"office",emoji:"\uD83E\uDDD1‍\uD83D\uDCBC",label:"昼休みに急ぐ会社員に、15分で「ほっとする一食」を",short:"昼の会社員に 15分で一食",start:"good",reaction:"いい出発点ね。「昼・会社員・15分」という3点セットが、観察メモの事実（人通り・昼休みの短さ・大将の腕）とぴったり重なっているわ。ただし、これはまだ出発点。ここから「だから」でつなげていけるかが勝負よ。"},{id:"everyone",emoji:"\uD83D\uDC68‍\uD83D\uDC69‍\uD83D\uDC67‍\uD83D\uDC66",label:"ご近所の誰にでも。年齢も時間帯も問わず、幅広く",short:"誰にでも幅広く",start:"weak",reaction:"「みんなに」は、聞こえはいいけれど、**結局「誰にも刺さらない」**になりがち。大将の壁のチラシは、まさにこの出発点から生まれたのよ。…でも、このまま物語を組んで、結果を見てみましょう。"},{id:"family",emoji:"\uD83C\uDF7D️",label:"週末に来る家族連れに、ちょっと贅沢なごちそうを",short:"週末の家族連れに贅沢を",start:"ok",reaction:"狙いを一本に絞ったのは、えらいわ。ただ、観察メモを見て。商店街の週末は人通りが少ないわね。**狙いが一本でも、「土台の事実」とずれていないか**は確かめたいところ。このまま進めてみましょう。"}]},{id:"inside",nodeLabel:"中身",title:"ステップ2 ── お店の「中身」をどうする？",question:"メニューと仕込みの方針です。ステップ1の狙いと、「だから」でつながる選択はどれでしょう？",options:[{id:"single",emoji:"\uD83C\uDF71",label:"日替わり1〜2種類に絞る（得意の煮物・焼き魚で勝負）",short:"日替わり1〜2種類",requires:["office"],reaction:"つながったわ！ 「15分で満足」という約束を、「品数を絞る」が支えている。仕込みが減ってムダも減り、提供も速くなる。**絞ることが、そのままお客さんへのサービス**になるのよ。",mismatchReaction:"この一手そのものは、悪くないの。でも、ステップ1の狙いと「だから」でつながらないわ。「なぜ絞るの？」と聞かれて、答えに困るでしょう？ **打ち手は良くても、つなぐ相手がいない**状態ね。"},{id:"many",emoji:"\uD83D\uDCDC",label:"メニューを60品に増やして、何でも選べるようにする",short:"メニュー60品",requires:["everyone"],reaction:"「みんなに」に応える形としては、筋が通っているわ。ただし、仕込みの手間とムダは一気に増える。この先の「運び方」で、そのツケが回ってくるかもしれないわね。",mismatchReaction:"選べる楽しさはあるけれど、選ぶのに時間がかかり、仕込みも増えて提供が遅くなる。ステップ1の狙いとは、むしろ**逆向きに働いてしまう**わ。"},{id:"course",emoji:"\uD83C\uDF77",label:"季節の食材を使った、コース料理に一本化する",short:"季節のコース料理",requires:["family"],reaction:"「ちょっと贅沢な時間」という狙いと、つながったわ。食材や手間にお金をかけても、「ごちそう」として納得してもらえる。",mismatchReaction:"いい打ち手だけれど、狙いとは噛み合わないわ。昼に急ぐ人には長すぎるし、「みんな向け」にするには入り口が高すぎる。"}]},{id:"deliver",nodeLabel:"運び方",title:"ステップ3 ── お店の「運び方」をどうする？",question:"提供の仕組みと価格です。ここまでの2つの選択と、「だから」でつながる運び方を選んでください。",options:[{id:"fast",emoji:"⏱️",label:"注文から3分で出す仕組みを整え、価格は据え置きで回転で稼ぐ",short:"3分で提供・価格は据え置き",requires:["office","single"],reaction:"来たわね！ 「15分で満足」という約束を、「絞ったメニュー」が支え、さらに「3分で出す仕組み」が実現させる。矢印の全部に「だから」が入ったわ。",mismatchReaction:"「3分で出す」という約束だけが先走ってしまったわね。狙いか中身が、それを支えていない。厨房が追いつかず、結局お客さんを待たせてしまうわ。"},{id:"slow",emoji:"\uD83D\uDECB️",label:"席を整えてゆったり過ごせる店にし、価格は高めに設定する",short:"ゆったり席・高めの価格",requires:["family","course"],reaction:"「ゆっくり贅沢」という狙いに、コースと席づくりがきれいに乗ったわね。価格が高くても、納得してもらえる筋が通っているわ。",mismatchReaction:"ゆったりした席や高めの価格は、「ゆっくり過ごしたい人」を狙っていて初めて意味が出るの。いまの狙いと中身では、席が空くだけで回らなくなってしまうわ。"},{id:"discount",emoji:"\uD83C\uDFF7️",label:"値下げと出前を強化して、とにかく多くの人に届ける",short:"値下げと出前で広く届ける",requires:["everyone","many"],reaction:"「みんなに安く」という筋としては通っているわ。ただし…この物語、「ほかの店と何が違うの？」と聞かれたら、答えられるかしら。",mismatchReaction:"値下げは、「たくさん売れる仕組み」とセットでないと、利益だけが削れていくわ。いまの狙いと中身では、その仕組みがないのよ。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"一本の物語ができあがった",quality:1,when:{firstPick:["office"],matches:[2]},narration:"三か月後。ひだまり亭の前に、昼の十二時前から会社員の列ができるようになりました。「あそこは早いし、ほっとする味だ」と評判が広がり、大将は笑います。「やることは減ったのに、前より楽で、儲かってるよ」。",nana:"完璧。誰に、何を、どうやって。矢印の全部に「だから」が入っているわ。さくら食堂と狙いは近いけれど、ひだまり亭には「大将の煮物と焼き魚」という、自分だけの**『違いの種』**がある。そこをどう磨くかは、第5章でもっと深く掘り下げるわよ。"},{id:"linked-off",emoji:"\uD83E\uDDE9",title:"つながってはいる。でも…",quality:.66,when:{matches:[2]},narration:"物語としては筋が通り、現場も落ち着きました。ただ、お客さんの数は思ったほど伸びません。",nana:"矢印は「だから」でつながっているわ。ここは立派。でもね、**出発点が外れていると、きれいにつながっても届かない**の。観察メモの事実とずれていないか、「ほかの店と何が違うのか」。つながりの前の「土台」と「違い」も、物語の大事な一部よ。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、筋が途切れた",quality:.4,when:{matches:[1]},narration:"最初のうちは手応えがありましたが、途中から打ち手が噛み合わなくなり、現場がバタつき始めました。",nana:"前半は筋が通っていたのに、途中で矢印が切れてしまったわね。**どれだけ良い一手を重ねても、一か所つながりが切れると、そこから全体が弱くなる**の。「この一手は、前の一手と『だから』でつながる？」と、もう一度確かめてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"壁のチラシと同じになった",quality:.1,narration:"打ち手はそろったのに、お互いが噛み合わず、仕込みも接客も追いつきません。気づけば、壁にまた新しいチラシが一枚増えていました。",nana:"これが、最初に見た「バラバラ」の正体よ。**一つひとつは悪くないのに、どれも前の一手とつながっていない**。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"quiz",id:"s1-quiz",title:"確認クイズ",intro:"ここまでの理解を確かめましょう。まちがえても大丈夫。解説こそが、いちばんの学びよ。",questions:[{id:"q1",question:"次のうち、「戦略がしっかりしているお店」にいちばん近いのはどれでしょう？",options:[{text:"流行りの施策を、できるだけたくさん取り入れているお店",feedback:"たくさんやること自体は悪くないけれど、数が多いほど強い、とは限らないわ。ひだまり亭の壁を思い出して。打ち手同士がぶつかると、かえって弱くなってしまうの。"},{text:"打ち手が「だから」でつながり、全体で一つの狙いに向かっているお店",feedback:"その通り！ 戦略の強さは、打ち手の数ではなく「つながり」に宿る。さくら食堂が、まさにそれだったわね。"},{text:"ライバルより、いつも値段が安いお店",feedback:"値段は、数ある打ち手の一つにすぎないわ。安さだけで勝負すると、みんなが同じことをして、値下げ合戦になりがち。それは「違い」にならないのよ。"},{text:"経営者がいつも忙しく動き回っているお店",feedback:"忙しさと戦略は別物よ。頑張るほど「やることリスト」が増えて、忙しいのに成果が出ない…という状態もあるの。ひだまり亭の大将が、そうだったわね。"}],answer:1,explanation:"戦略とは、やることを並べたリストではなく、「だから」でつながった物語（[[strategy-story]]）です。数や値段、忙しさではなく、**打ち手同士のつながり**が強さをつくります。"},{id:"q2",scenario:"さくら食堂は、メニューを日替わり1種類だけにしています。",question:"この「日替わり1種類」は、物語の中でどんな役割を果たしているでしょう？",options:[{text:"メニューを考えるのが面倒で、手を抜いているだけ",feedback:"むしろ逆よ。「絞る」ことで仕込みを軽くし、3分提供を実現するための、とても戦略的な一手なの。"},{text:"お客さんの数を、わざと減らすため",feedback:"お客さんを減らすのが目的ではないわ。むしろ、昼休みの時間内に食べ終えられるから、より多くの人が通えるようになっているのよ。"},{text:"「3分で出す」→「昼休み内に戻れる」という約束を支える、つながりの一部",feedback:"正解！ 日替わり1種類は、それ単体の良し悪しではなく、全体の筋の中の「大事な一手」として意味を持っているの。"},{text:"近所のほかのお店を、そのまま真似している",feedback:"ほかの店の真似なら、むしろ「違い」にならないわ。この一手は、さくら食堂の物語の中から必然的に出てくるものなの。"}],answer:2,explanation:"打ち手は、単体で「良い・悪い」が決まるのではなく、**全体の物語の中での役割**で決まります。矢印の間に「だから」を入れられるか（[[inga-ronri]]）が、確かめ方です。"},{id:"q3",scenario:"隣のお店が、さくら食堂の「日替わり1種類」だけを、そっくり真似しました。",question:"そのお店が、さくら食堂ほどうまくいかない可能性が高いのは、なぜでしょう？",options:[{text:"部品だけ真似しても、それを支えるほかの打ち手とのつながりがないから",feedback:"正解！ やり方（部品）は見れば真似できる。でも「誰に、なぜ、その順番で」というつながりは、外から見えにくいの。"},{text:"「日替わり1種類」は、そもそも悪い打ち手だから",feedback:"悪い打ち手なのではなくて、「何を支える一手なのか」が大事なの。さくら食堂では、とても良く働いているわ。"},{text:"お客さんは、同じお店には二度行かないものだから",feedback:"そんなことはないわ。むしろ、さくら食堂は「毎日のように通うお客さん」で成り立っているのよ。"},{text:"運が悪かっただけで、理由はないから",feedback:"うまくいくかどうかを「運」で片づけたら、そこで学びが止まってしまうわ。「なぜ？」を探すのが、コンサルタントの仕事よ。"}],answer:0,explanation:"つながりは外から見えにくく、真似しにくい。だから、部品だけコピーしても同じ結果にはなりません。これが、戦略ストーリーが[[kyoso-yui]]を**長く**支えてくれる理由です。"}]},{kind:"summary",id:"s1-summary",title:"今日の学びを、一枚に",points:[{title:"戦略は、リストではなく物語",text:"「やること」を並べただけでは戦略になりません。打ち手が「だから」でつながって、初めて一本の筋書き（[[strategy-story]]）になります。"},{title:"良し悪しは、つながりの中で決まる",text:"日替わり1種類のように、単体では不親切に見える一手も、全体の中で大事な役割を果たします。打ち手は「部品」ではなく「つながりの一部」として見ましょう。"},{title:"全部やると、足を引っ張り合う",text:"打ち手を増やすほど、時間・お金・人手が散らばり、ぶつかる組み合わせも増えます。ひだまり亭の壁が、その典型でした。"},{title:"つながりは、真似されにくい",text:"部品（やり方）は見て真似できても、つながり（なぜその順番か）は外から見えにくい。だから、[[kyoso-yui]]を長く支えてくれます。"},{title:"迷ったら、「だから」を書く",text:"新しい一手を考えるときは、前の一手と「だから」でつながるか（[[inga-ronri]]）、そして「やらないことは何か」を確かめる。これが日常で使える最初の問いです。"}],why:{title:"なぜ、これが大事なのか",text:"経営は、毎日が判断の連続です。物語（筋）があれば判断の物差しができ、現場も自分で動けます。物語がなければ、判断は「流行」や「目先の不安」に引っ張られます。**戦略のいちばんの価値は、迷ったときに戻れる「筋」を持てること**です。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま。難しい言葉をほとんど使わずに、核心まで来られたわね。"},{who:"you",mood:"smile",text:"はい。最初は「戦略」って遠い言葉でしたけど、お店の話にしたら、すごく身近に感じました。"},{who:"nana",mood:"smile",text:"それが、いちばんの収穫。身近な例で掴んだ感覚は、これから出てくる専門用語の「土台」になるわ。"}]}],clear:{perspective:{icon:"\uD83D\uDD17",name:"つながりで見る目",tagline:"打ち手を「点」でなく「線」で見る",description:"ひとつの施策を見たとき、その良し悪しだけでなく、全体の筋の中での役割まで見られるようになりました。お店・会社・ニュースを見るとき、「だから」の矢印を探してみてください。",checks:["これは何のための一手？（「だから」で説明できる？）","前の一手と、矢印でつながっている？","この一手で、「やらなくなること」は何？"]},nana:[{who:"nana",mood:"smile",text:"おめでとう、{san}。最初の視点「つながりで見る目」を手に入れたわね。街のお店を見るたびに、「だから」の矢印を探してみて。"},{who:"you",mood:"smile",text:"はい！ 商店街の見え方が、もう変わりました。"},{who:"nana",mood:"proud",text:"いいわね。次の章では、戦略の考え方には「いくつもの流派がある」ことを知る旅に出るわよ。"}],teaser:"次の章：戦略の地図 ─ 世の中には、戦略についての「考え方の流派」がいくつもあります。地図を手に入れて、自分の立ち位置を知る旅へ。"}},{id:2,title:"戦略の地図",subtitle:"戦略サファリ的全体像",theme:"戦略の流派を見渡す（戦略サファリ）",icon:"\uD83D\uDDFA️",accent:"#3cc9b6",blurb:"「戦略」と一口に言っても、考え方はひとつではありません。計画を重んじる流派、現場から生まれる流派、市場での位置どりを重んじる流派…。六人の盲人と象の話から出発して、それぞれの特徴を一枚の地図にし、いま自分が立っている場所を知ります。",goals:["戦略の考え方に複数の「流派」があることを、象のたとえで説明できる","「計画的戦略」と「創発的戦略」の違いと、両方が必要な理由が言える","環境・情報・現場の知恵の3つの問いで、場面に合う見方を選べる"],minutes:28,termKeys:["strategy-safari","deliberate","emergent","positioning-school"],termPreview:["戦略サファリ","計画的戦略","創発的戦略","ポジショニング派"],status:"ready",scenes:[{kind:"story",id:"s2-maproom",place:"ノースライト戦略研究所 ─ 地図の部屋",time:"二日目 午前9:00",lines:[{who:"narrator",text:"翌朝。研究所の奥には、普段は鍵のかかっている「地図の部屋」がある。今日は、ナナ先生がその鍵を開けてくれた。"},{who:"narrator",text:"壁一面に、古い海図のような大きな地図。ところどころが、まだ白いままだ。"},{who:"nana",mood:"smile",text:"おはよう、{san}。昨日は「戦略は、つながった物語」というところまで来たわね。"},{who:"you",mood:"smile",text:"はい！ ひだまり亭の壁の「バラバラ」が、今なら説明できます。"},{who:"nana",text:"いいわ。じゃあ今日は、少し意地悪な質問から。「戦略のつくり方」って、世の中に何通り書いてあると思う？"},{who:"you",mood:"think",text:"えっと…「これが正解」というやり方が、一つあるんじゃないんですか？"},{who:"nana",mood:"smile",text:"実はね、研究者たちが何十年も議論してきて、考え方は**いくつもの流派**に分かれているの。しかも、どれにも一理あるのよ。"},{who:"you",mood:"surprise",text:"えっ、正解が一つじゃないんですか？ それだと、どれを信じたらいいのか…。"},{who:"nana",mood:"think",text:"そこで、昔話をひとつ。「六人の盲人と象」って知ってる？"},{who:"you",text:"名前だけは…。象を触って、それぞれ違うことを言う話ですよね？"},{who:"nana",text:"そう。足を触った人は「木の幹だ」、鼻を触った人は「蛇だ」、耳を触った人は「うちわだ」。みんな**嘘はついていない**のに、誰も象の全体は言えていないの。"},{who:"you",mood:"think",text:"…戦略の流派も、同じってことですか？"},{who:"nana",mood:"proud",text:"鋭いわね。ある研究者たちは、戦略の考え方を巡る旅を『[[strategy-safari|戦略サファリ]]』と名づけて、広い草原を回るように、流派を一つずつ観察していったの。"},{who:"nana",mood:"smile",text:"今日は、その旅の**地図**を手に入れるわよ。全部を覚える必要はないわ。「いま自分がどの辺りを歩いているか」が分かれば、十分なの。"}]},{kind:"explain",id:"s2-elephant",eyebrow:"核心① ／ 象を触る六人",title:"正解は一つじゃない。みんな「象の一部」を見ている",blocks:[{type:"p",text:"昔話の「六人の盲人と象」を、もう一度見てみましょう。六人とも、**嘘はついていません**。ただ、触った場所が違うだけです。"},{type:"list",style:"bullet",title:"触った場所と、その人の結論",items:["**足**を触った人：「これは、太い木の幹だ」","**鼻**を触った人：「これは、長い蛇だ」","**耳**を触った人：「これは、大きなうちわだ」","**牙**を触った人：「これは、固い槍だ」"]},{type:"callout",tone:"point",title:"全員が正しくて、全員が足りない",text:"部分としては、どの結論も正しい。でも、**象の全体を言い当てた人は、一人もいません**。"},{type:"p",text:"経営の「戦略」の考え方でも、まったく同じことが起きています。ある人は「しっかり計画を立てることが戦略だ」と言い、別の人は「市場での立ち位置が戦略だ」と言い、また別の人は「現場で試して学ぶことが戦略だ」と言う。"},{type:"nana",mood:"smile",text:"研究者たちが何十年も議論して、戦略の考え方は、いくつもの「流派」に分かれたの。その流派を、広い草原を回るように観察して回った旅が、『[[strategy-safari|戦略サファリ]]』よ。"},{type:"callout",tone:"why",title:"なぜ「地図」が要るの？",text:"流派を知らないと、同じ「戦略」という言葉で話していても、**別の象の部分を指して**議論がすれ違います。会議が噛み合わない原因の多くは、能力の差ではなく、「見ている部分が違う」こと。地図があれば、「いま、誰がどこを触っているか」が分かります。"}]},{kind:"explain",id:"s2-map",eyebrow:"核心② ／ 地図を広げる",title:"三つの地方に分けて、全体を見渡す",blocks:[{type:"p",text:"流派は全部で10あります。でも、10個をいっぺんに覚える必要はありません。まずは「三つの地方」に分けて、**どんな視点の違いなのか**を掴みましょう。"},{type:"map",title:"戦略サファリの地図",regions:[{name:"設計の森",emoji:"\uD83C\uDF32",tagline:"戦略は、こう作るべき（頭で組み立てる）",tone:"sea",schools:[{name:"デザイン派",gist:"状況をよく見て、一本の構想（ストーリー）を練る"},{name:"プランニング派",gist:"手順を決めて、計画に落とし込む",tag:"この章"},{name:"ポジショニング派",gist:"分析して、いちばん有利な立ち位置を選ぶ",tag:"第3章で深掘り"}]},{name:"現場の草原",emoji:"\uD83C\uDF3E",tagline:"戦略は、実際にはこう生まれる（現実を観察する）",tone:"lantern",schools:[{name:"アントレプレナー派",gist:"リーダーの直感とビジョンが道をつくる"},{name:"コグニティブ派",gist:"人の頭の中の見方や思い込みが、戦略を左右する"},{name:"ラーニング派",gist:"やってみて、学びながら、形になっていく",tag:"この章"},{name:"パワー派",gist:"社内外の力関係や交渉で、戦略が決まる"},{name:"カルチャー派",gist:"組織の文化や価値観が、戦略の土台になる"},{name:"環境派",gist:"環境の変化に、組織がどう反応するかで決まる"}]},{name:"統合の山",emoji:"⛰️",tagline:"状況によって、これらを組み合わせる",tone:"sky",schools:[{name:"コンフィギュレーション派",gist:"会社の状態や時期に応じて、見方を使い分け、変革する"}]}]},{type:"callout",tone:"point",title:"森は「すべき」、草原は「なっている」",text:"設計の森は「どう作るべきか」を教え、現場の草原は「実際にはどう生まれているか」を教えてくれます。**どちらかが正しいのではなく、見ている面が違う**のです。"},{type:"nana",mood:"smile",text:"森にも、草原にも、山にも、それぞれの良さがあるわ。この章では、森と草原の境目にある大事な対立、「**計画か、創発か**」を、ひだまり亭を舞台に掘り下げましょう。"}]},{kind:"story",id:"s2-hidamari",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"午前11:30",lines:[{who:"narrator",text:"地図の部屋を出て、ひだまり亭へ。昨日の「物語づくり」から、まだ一晩しか経っていない。"},{who:"taisho",mood:"smile",text:"ナナ先生、{san}、いらっしゃい！ 聞いてくれ、昨日はちょっと不思議なことがあってな。"},{who:"nana",text:"あら、何かあったの？"},{who:"taisho",text:"昨日の昼、常連さんが「煮物だけ、持ち帰りで少し分けてくれないか」って言うんだ。ダメ元で小鉢に詰めて出したら、夕方までに全部売れちまった。"},{who:"you",mood:"surprise",text:"持ち帰りですか？ 昨日の物語には、入っていなかったのに！"},{who:"taisho",mood:"think",text:"そうなんだ。計画してたわけじゃない。ただ、もう「明日もお願い」って言われててな…さて、これはやったほうがいいのかね。"},{who:"nana",mood:"smile",text:"…大将。それ、**とてもいい悩み**よ。"},{who:"you",mood:"think",text:"いい悩み、ですか？ 計画外のことが起きて、困っているようにも見えますけど…。"},{who:"nana",mood:"proud",text:"計画の外から生まれた手がかりは、戦略の世界では、とても大事に扱われるの。ただし、「拾うか、捨てるか」には判断のものさしが要るわ。"},{who:"nana",mood:"smile",text:"ちょうどいいわ。さっき手に入れた地図を使って、一緒に考えましょう。"},{who:"narrator",text:"ノートを開いた{san}の手元に、昨日までなかった問いが、一つ増えていた。"}]},{kind:"explain",id:"s2-deliberate",eyebrow:"核心③ ／ 計画か、創発か",title:"レシピ通りか、冷蔵庫の中身か",blocks:[{type:"p",text:"夕食づくりを想像してください。あなたなら、どう作りますか？ 実は、料理には大きく二つの進め方があります。"},{type:"compare",left:{label:"レシピ通りに作る",emoji:"\uD83D\uDCD6",items:["先に献立と買い物リストを決める","手順どおりに進めれば、失敗しにくい","予定外の食材が出ても、基本は使わない","誰が作っても、同じ味にしやすい"],note:"あらかじめ決める"},right:{label:"冷蔵庫を見て作る",emoji:"\uD83E\uDDCA",items:["あるものを見て、その場で献立を決める","作りながら味見して、直していく","予定外の食材が、新しい一品を生む","うまくいった形が、次の定番になる"],note:"やりながら生まれる"}},{type:"p",text:"経営の戦略にも、この二つの生まれ方があります。専門的には、前者を[[deliberate]]、後者を[[emergent]]と呼びます。"},{type:"callout",tone:"why",title:"かみ砕くと、こういうこと",text:"**計画的戦略**は、「先に決めた筋書きどおりに進める」生まれ方。**創発的戦略**は、「やっているうちに、繰り返される行動やお客さんの反応から、自然と形になっていく」生まれ方です。"},{type:"formula",parts:[{label:"計画のうち",sub:"実行できたもの"},{label:"現場で",sub:"生まれたもの"},{label:"実際に進んだ戦略",sub:"実現した戦略"}],ops:["＋","＝"],caption:"実際の会社の戦略は、たいていこの両方の合成です。"},{type:"callout",tone:"point",title:"どちらが正しい？ ではなく、どう組み合わせる？",text:"計画だけだと、環境が変わったときに動けません。創発だけだと、バラバラな試行の寄せ集めになりがちです。**よい戦略は、この二つのバランス**でできています。"},{type:"nana",mood:"think",text:"「予定どおりにいかなかった」は、失敗とは限らないの。計画の外から生まれた手がかりが、いちばん強い戦略の芽になることもあるのよ。"}]},{kind:"explain",id:"s2-pick",eyebrow:"核心④ ／ ひだまり亭の「偶然」",title:"「拾うか、捨てるか」は、物語で決める",blocks:[{type:"p",text:"大将の「煮物の持ち帰り」を、いまの言葉で整理しましょう。昨日の計画（物語）には、なかった。でも、お客さんの声という現場から生まれた手がかり。つまり、**創発的戦略の「芽」**です。"},{type:"nana",mood:"think",text:"ただ、芽が出たからといって、何でも育てればいいわけじゃない。育てる芽と摘む芽を分けるのが、第1章で作った「物語」の出番よ。"},{type:"chain",title:"拾う場合：物語とつながる",nodes:[{emoji:"\uD83C\uDF72",label:"煮物の持ち帰りが、その日に完売した（現場の発見）"},{emoji:"\uD83D\uDEB6",label:"店で食べる時間がない会社員でも、買って戻れる"},{emoji:"\uD83C\uDFAF",label:"狙いの「昼に急ぐ会社員」を、さらに取りこぼさない"},{emoji:"\uD83D\uDCC8",label:"昼の売上の取りこぼしが減る",tone:"goal"}],caption:"矢印に「だから」が入る。物語の筋に、ぴたりと収まります。"},{type:"chain",title:"捨てる場合：物語とつながらない",nodes:[{emoji:"\uD83C\uDF19",label:"夜の営業も始めてみる（別の誰かの提案）"},{emoji:"\uD83E\uDDD1‍\uD83D\uDCBC",label:"狙いの「昼の会社員」から、離れてしまう",broken:!0},{emoji:"\uD83C\uDF00",label:"仕込みも人手も足りなくなり、昼の質まで落ちる",tone:"bad"}],caption:"矢印に「だから」が入らない。筋から外れた芽は、摘みます。"},{type:"callout",tone:"why",title:"なぜ、創発に「物語」が要るの？",text:"創発は現場の気づきを拾える反面、放っておくと、何でも足してしまって、第1章の壁のような「バラバラ」に戻ります。第1章の[[strategy-story]]は、創発を縛る鎖ではなく、**拾う・捨てるを決める物差し**として働きます。"},{type:"nana",mood:"proud",text:"計画と創発は、対立するものじゃないの。**創発が芽を出し、物語がそれを選び、計画がそれを広げる**。この循環が、強い戦略の姿よ。"}]},{kind:"explain",id:"s2-positioning",eyebrow:"核心⑤ ／ もう一つの大きな流派",title:"位置取りで考える「ポジショニング派」",blocks:[{type:"p",text:"地図の「設計の森」にいる流派のうち、いちばん有名なのが[[positioning-school]]です。まず、商店街の空き店舗を借りる場面で、たとえてみましょう。"},{type:"p",text:"「どこに店を出すか」「どんなお客さんを相手にするか」。駅前の人通りや、周りの競合の数を調べて、**いちばん有利な位置**を選んで店を構える。これが、位置取りで考える見方です。"},{type:"compare",left:{label:"ポジショニング派の見方",emoji:"\uD83D\uDCCD",items:["外の環境（市場・競合）を分析する","いちばん有利な「立ち位置」を選ぶ","分析してから動く","向いている場面：環境が比較的安定している"],note:"分析してから動く"},right:{label:"ラーニング派の見方",emoji:"\uD83C\uDF31",items:["やってみて、お客さんの反応から学ぶ","動きながら、形をつくっていく","計画は、途中で変わるもの","向いている場面：先が読みにくく、変化が速い"],note:"動きながら学ぶ"}},{type:"callout",tone:"example",title:"ひだまり亭なら",text:"ポジショニング派は、「昼の会社員」という位置を、人通りや競合を調べて選びます。ラーニング派は、「煮物の持ち帰り」のような反応から、新しい位置を見つけます。**第1章の物語の出発点（誰に）は、実はこの二つの見方の合わせ技**でした。"},{type:"callout",tone:"why",title:"第3章への橋：なぜ「位置取り」が大事なの？",text:"位置取りの考え方は、「誰を相手に戦うか」と同時に、**「何をやらないか」**を決めます。第1章の「やらないことも物語の一部」は、実はここにつながっています。くわしくは、第3章で掘り下げます。"},{type:"nana",mood:"smile",text:"位置取りの分析は、強力な武器。でも、環境が急に変わったら？ 分析した位置が、一夜で古くなることもあるわ。次は、使い分けのコツよ。"}]},{kind:"explain",id:"s2-use",eyebrow:"核心⑥ ／ 地図の使い方",title:"場面に合わせて、流派の「めがね」を選ぶ",blocks:[{type:"p",text:"地図を持っていても、使えなければ意味がありません。使い方は、とてもシンプルです。**場面を見て、合うめがねをかけ替える**。それだけです。"},{type:"list",style:"number",title:"かけ替えるときの3つの問い",items:["**環境は、安定している？** 安定していれば、計画や位置取りの分析が効きやすい。変化が速ければ、試して学ぶ見方が効きやすい。","**情報は、足りている？** 十分なら、分析して決められる。足りないなら、小さく動いて、情報を集める。","**現場の知恵は、使える？** 現場に詳しい人がいるなら、創発を拾う価値が大きい。"]},{type:"callout",tone:"warn",title:"「一つのめがね」で、全部を見ない",text:"「うちは計画がすべて」「うちは現場がすべて」と決め打ちすると、**象の足だけを触っている状態**に逆戻りします。めがねは、場面で替えるものです。"},{type:"callout",tone:"why",title:"なぜ、使い分けが本質なの？",text:"戦略に唯一の正解がないのは、会社も環境も、常に変わるからです。だから本質は、特定の流派を信じることではなく、**「いま、どの見方が必要か」を自分で選べる力**。これが、この章で手に入れる「全体を見渡す目」です。"},{type:"nana",mood:"proud",text:"さあ、ここまでの言葉を整理して、実際に地図を使ってみましょう。ひだまり亭が、また一つ、相談を持ってきているわ。"}]},{kind:"terms",id:"s2-terms",title:"地図に、名前をつけよう",intro:[{who:"nana",mood:"smile",text:"今日の旅で、名前のついた言葉がいくつか出てきたわよね。その中から、大事な4つを、カードで確かめましょう。"},{who:"you",mood:"worry",text:"覚えられるか、ちょっと不安です…。"},{who:"nana",mood:"smile",text:"大丈夫。どれも、さっきのたとえ話——象、レシピ、空き店舗——に、ちゃんと戻れるから。"}],terms:["strategy-safari","deliberate","emergent","positioning-school"]},{kind:"choice",id:"s2-practice",title:"地図を使って、ひだまり亭の進め方を決めよう",intro:"午後三時。大将が、新しい相談を持ってきました。「来春、駅前に大手の弁当チェーンが出るらしい。うちは、これからどう進めたらいい？ …{san}、さっきの地図を使って、考えてみてくれないか」。",notes:["商店街の組合から「来春、駅前に大手の弁当チェーンが出店予定」との連絡。時期や規模は未定。","先月から、近くの会社がテレワーク中心になり、昼に歩く人が1割ほど減った。","昨日、煮物の持ち帰りを試しに出したところ、その日のうちに完売した。","チェーンの価格やメニューなど、具体的な情報は、まだほとんど分からない。"],nanaIntro:"今回も、正解を当てるクイズじゃないわ。**「状況の読み」→「進め方」→「束ね方」**が、「だから」でつながるかを見てね。最初の「読み」は、観察メモの事実と合っているかも大事よ。",steps:[{id:"read",nodeLabel:"状況の読み",title:"ステップ1 ── いまの状況を、どう読む？",question:"地図を広げる前に、まず環境をどう見るかを決めます。観察メモを見ながら、どう読みますか？",options:[{id:"volatile",emoji:"\uD83C\uDF2A️",label:"変化が速く、先が読みにくい（チェーンの進出、客足の変化、突然の持ち帰り人気）",short:"変化が速く、先が読めない",start:"good",reaction:"いい読みね。観察メモの事実は、どれも「環境が動いている」ことを示しているわ。ここから、動きに合う進め方を選びましょう。"},{id:"stable",emoji:"\uD83C\uDFDE️",label:"これまで通り、安定している。大きな変化はない",short:"安定している",start:"weak",reaction:"観察メモを見直してみて。チェーンの噂、昼の人通りが1割減、持ち帰りの突然の人気…。**事実は「変わりつつある」と言っているわ**。ただ、このまま進めたら何が起きるか、見てみましょう。"},{id:"unknown",emoji:"\uD83D\uDD0D",label:"競合の情報が足りなくて、まだ何とも言えない",short:"情報が足りない",start:"ok",reaction:"慎重なのは悪くないわ。たしかに競合の詳細は分かっていない。ただ、**「分からない」で止まる**のは危険でもあるの。このまま進めて、地図の使い方を見てみましょう。"}]},{id:"way",nodeLabel:"進め方",title:"ステップ2 ── どんな進め方をとる？",question:"状況の読みに合う、戦略の進め方を選んでください。地図のどのめがねをかけますか？",options:[{id:"try",emoji:"\uD83C\uDF31",label:"小さく試して、お客さんの反応を見ながら直していく（ラーニング派の見方）",short:"小さく試して学ぶ",requires:["volatile"],reaction:"つながったわ！ 先が読みにくいときは、大きな計画より、**小さく試して学ぶ**ほうが強い。煮物の持ち帰りは、まさにその一歩目よね。",mismatchReaction:"進め方としては悪くないけれど、状況の読みと「だから」でつながらないわ。「なぜ、いま試すの？」と聞かれたとき、読みから説明できるかしら。"},{id:"plan",emoji:"\uD83D\uDCD8",label:"三か年計画を細かく作り、その通りに進める（プランニング派の見方）",short:"三か年計画を作る",requires:["stable"],reaction:"「安定している」という読みと、きれいにつながったわ。環境が変わらないなら、細かい計画で効率よく進めるのも、立派な進め方。",mismatchReaction:"計画づくりそのものは大事。でも、読みと噛み合っていないわ。「変化が速い」「情報が足りない」のに、三年先まで固めて大丈夫かしら。"},{id:"analyze",emoji:"\uD83D\uDCCD",label:"市場と競合を徹底的に分析し、いちばん有利な立ち位置を一つ決める（ポジショニング派の見方）",short:"分析して位置を決める",requires:["unknown"],reaction:"「情報が足りない」という読みに、つながったわ。分からないなら、まず調べて、位置取りを決める。筋が通っているわ。",mismatchReaction:"分析は強力な武器。でも、いまの読みと「だから」でつながらないわ。なぜ、いま分析なのか。読みから説明できる？"}]},{id:"bind",nodeLabel:"束ね方",title:"ステップ3 ── 出てきた結果を、どう束ねる？",question:"進め方を決めたら、最後は出てきた結果の扱い方です。第1章の「物語」も思い出してね。",options:[{id:"story",emoji:"\uD83E\uDDF5",label:"結果のうち、物語（誰に・どうやって）に合うものだけ拾い、合わないものは捨てる",short:"物語に合うものだけ拾う",requires:["volatile","try"],reaction:"来たわね！ 試して学ぶ進め方に、**物語という物差し**が加わった。拾う芽と摘む芽が選べて、バラバラにならないわ。第1章と第2章が、ここでつながったのよ。",mismatchReaction:"物語で拾い選ぶのは、素晴らしい束ね方。でも、これまでの選択と噛み合っていないわ。この束ね方は、「試して、結果が出てくる」進め方でこそ活きるのに。"},{id:"fixed",emoji:"\uD83D\uDCCC",label:"決めた計画を守ることを最優先にして、現場からの変更は受け付けない",short:"計画を守り抜く",requires:["stable","plan"],reaction:"「安定」「計画」と、つながったわ。環境が変わらないなら、計画を守り抜くことで、効率が出るもの。",mismatchReaction:"計画を守ること自体は大事。でも、いまの読みと進め方では、現場から出てくる変化を受け止められないわ。"},{id:"report",emoji:"\uD83D\uDCCA",label:"分析資料を完成させて、位置取りを確定し、全員に発表する",short:"位置取りを確定・発表",requires:["unknown","analyze"],reaction:"「情報不足」→「分析」→「位置取りの確定」。筋が通っているわ。",mismatchReaction:"分析をまとめて発表するのは、分析したうえでの話。前の選択と、つながっていないわね。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"試して拾う、強い物語ができた",quality:1,when:{firstPick:["volatile"],matches:[2]},narration:"チェーンが出店した春。ひだまり亭は、昼の定食という自分たちの筋を守りながら、お客さんの声から生まれた小さな工夫を、一つずつ拾っていきました。客足は少し落ちましたが、常連さんは離れず、大将は言います。「慌てずに済んだのは、何を拾って何を捨てるかが、はっきりしてたからだな」。",nana:"いい地図の使い方ね。**環境の読み → 創発を拾う → 物語で束ねる**。第1章の「つながり」が、第2章の「地図」とつながったわ。ここで使ったのはラーニング派のめがね。でも、位置取りを分析するポジショニング派のめがねが、必要になる場面もある。それは、次の第3章でゆっくり磨きましょう。"},{id:"linked-off",emoji:"\uD83E\uDDE9",title:"筋は通ったけれど、読みが外れていた",quality:.66,when:{matches:[2]},narration:"計画も分析も、きれいにまとまりました。ただ、チェーンが予定より早く出店してきたとき、動きが後手に回り、お客さんの一部が流れてしまいました。",nana:"進め方は「だから」でつながっていたわ。でも、**最初の読みが状況とずれていると、きれいに進めるほど、ずれが大きくなる**の。めがねを選ぶ前に、環境を正しく読むこと。これが、地図の使い方のいちばんの入り口よ。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、めがねが合わなくなった",quality:.4,when:{matches:[1]},narration:"最初は順調でしたが、進めるうちに、やり方と状況が噛み合わなくなり、現場が混乱し始めました。",nana:"途中で、「いまの状況に、そのめがねは合っている？」が抜けてしまったわね。**めがねは、場面でかけ替えるもの**。前の選択と、もう一度つなげて考えてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"象の足だけを触っていた",quality:.1,narration:"状況の読みも、進め方も、束ね方も、それぞれ別の方向を向いていました。気づけば、どの方針で動いているのか、誰にも分からなくなっていました。",nana:"これが「象の足だけを触っている」状態。一つひとつは悪くなくても、全体の筋が見えなくなっているの。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"quiz",id:"s2-quiz",title:"確認クイズ",intro:"地図の使い方を確かめましょう。正解が一つとは限らない世界だからこそ、「なぜ？」の解説が、いちばんの学びよ。",questions:[{id:"q1",scenario:"「六人の盲人と象」では、足を触った人は「木の幹」、鼻を触った人は「蛇」と言いました。",question:"この話が、[[strategy-safari]]で伝えたいことに、いちばん近いのはどれでしょう？",options:[{text:"いちばん正しい流派を一つ選べば、間違いない",feedback:"象の話は、むしろ逆。六人とも一部は正しかったのに、誰も全体は言えなかった。「一つに決めれば安心」という見方が、危ないのよ。"},{text:"どの流派も部分的に正しく、状況に応じて使い分け、組み合わせる",feedback:"その通り！ 流派は、それぞれ象の一部を見ている。だから「いま、どの見方が必要か」を選べることが大事なの。"},{text:"古い流派は役に立たないので、新しいものだけ学べばいい",feedback:"流派の新旧は、あまり関係ないわ。古い流派でも、安定した環境ではよく効く。「合う・合わない」は、場面で決まるの。"},{text:"流派の名前をすべて覚えることが、いちばん大事",feedback:"名前を覚えること自体は、目的じゃないわ。地図は「いま自分はどこを歩いているか」が分かるための道具。使えなければ、意味がないの。"}],answer:1,explanation:"戦略の考え方には複数の流派があり、それぞれが「象の一部」を見ています。大切なのは、流派を覚えることではなく、**場面に合う見方を選べること**です。"},{id:"q2",scenario:"大将が、常連さんの一言から、計画になかった「煮物の持ち帰り」を試したところ、その日に完売しました。",question:"この出来事は、地図の言葉で言うと、何にあたるでしょう？",options:[{text:"計画した戦略が、失敗した例",feedback:"計画していなかったので、「計画的戦略」の失敗ではないわ。むしろ、計画の外で起きた新しい手がかりよ。"},{text:"ただの偶然で、戦略とは関係がない",feedback:"「ただの偶然」で終わらせるのは、もったいないわ。繰り返し起きれば、それが戦略になっていくの。見過ごさないことが大事よ。"},{text:"現場から生まれた、[[emergent]]の「芽」",feedback:"正解！ 計画になかったけれど、お客さんの声という現場から生まれた手がかり。拾うかどうかを物語で決めれば、本物の戦略に育つわ。"},{text:"ポジショニング派の分析で決まった立ち位置",feedback:"分析して選んだわけではないから、ポジショニング派の見方とは違うわ。反応から学んでいるので、ラーニング派の見方に近いの。"}],answer:2,explanation:"計画になかった手がかりが現場から生まれ、繰り返されて形になっていくのが[[emergent]]です。放っておくとバラバラになるので、第1章の[[strategy-story]]で「拾う・捨てる」を決めます。"},{id:"q3",question:"現場の発見を、どんどん取り入れ続けると、いちばん起こりやすい問題は何でしょう？",options:[{text:"打ち手が増え続けて、全体の筋がバラバラになる",feedback:"正解！ 第1章のひだまり亭の壁と同じ状態ね。だから、創発には「何を拾い、何を捨てるか」を決める物語が必要なの。"},{text:"計画が完璧になって、変更が一切いらなくなる",feedback:"むしろ逆よ。現場の発見を取り入れるほど、計画は変わり続ける。完璧な計画が固まる、ということは起きにくいわ。"},{text:"競争相手がいなくなる",feedback:"現場の発見を取り入れても、競争相手は変わらず存在するわ。競争相手の動きを無視できるわけでもないの。"},{text:"分析がいらなくなる",feedback:"分析は、状況によってはとても有効よ。創発だけを信じて分析を捨てるのは、象の足だけを触るようなもの。"}],answer:0,explanation:"創発は強い反面、放っておくと「何でもやる」状態になり、[[inga-ronri]]（「だから」の筋）が見えなくなります。**創発と物語は、セットで使う**のが基本です。"}]},{kind:"summary",id:"s2-summary",title:"今日の学びを、一枚に",points:[{title:"戦略の考え方は、一つじゃない",text:"六人の盲人と象のように、どの流派も「象の一部」を見ています。その全体を一枚にしたのが[[strategy-safari]]です。"},{title:"三つの地方で、全体を見渡す",text:"「設計の森」は戦略はこう作るべき、「現場の草原」は実際にはこう生まれる、「統合の山」は状況で組み合わせる。見ている面が違うだけで、どれも必要です。"},{title:"戦略は、計画と創発の合成",text:"実際に進む戦略は、[[deliberate]]のうち実行できたものと、[[emergent]]として現場で生まれたものの合成です。"},{title:"拾うか捨てるかは、物語で決める",text:"創発は放っておくとバラバラになります。第1章の[[strategy-story]]が、「拾う・捨てる」を決める物差しになります。"},{title:"めがねは、場面でかけ替える",text:"環境は安定？ 情報は足りている？ 現場の知恵は使える？ この3つの問いで、いまのめがねを選びます。位置取りで考える[[positioning-school]]は、第3章で深掘りします。"}],why:{title:"なぜ、これが大事なのか",text:"戦略に唯一の正解がないのは、会社も環境も変わり続けるからです。流派を一つ信じ込むと、環境が変わったときに動けなくなります。**「いま、どの見方が必要か」を選べる力こそが、変化の中で戦略を持ち続ける力**になります。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま。今日は、戦略の「地図」を手に入れたわね。"},{who:"you",mood:"smile",text:"はい。「正解が一つじゃない」と聞いて最初は不安でしたけど、地図があると、いまどこにいるのか分かって、むしろ安心しました。"},{who:"nana",mood:"smile",text:"それが、地図の本当の使い道。そして、第1章で手に入れた「物語」が、ここでもちゃんと役に立ったでしょう？ 学びは、積み重なっていくのよ。"}]}],clear:{perspective:{icon:"\uD83E\uDDED",name:"全体を見渡す目",tagline:"ひとつの正解に飛びつかない",description:"目の前の戦略論や意見が、全体の地図のどこにあるのかを位置づけられるようになりました。議論がすれ違っているときは、「いま、誰がどの部分を触っているか」を見てみてください。",checks:["この考え方は、どの流派の発想？","別の流派のめがねなら、どう見える？","いまの場面に合うのは、どのめがね？"]},nana:[{who:"nana",mood:"smile",text:"おめでとう、{san}。第2の視点「全体を見渡す目」を手に入れたわね。意見がすれ違う会議に出たら、ぜひ地図を思い出してみて。"},{who:"you",mood:"smile",text:"はい！ 誰かが「象の別の場所」を触っているだけかもしれませんね。"},{who:"nana",mood:"proud",text:"その通り。次の章では、森の中でもいちばん有名な流派、「位置取り」の考え方に、じっくり向き合うわよ。"}],teaser:"次の章：ポジションを取る ─ 「何をやらないか」を決める強さを、ポジショニング派の考え方から学びます。第1章の「やらないことも物語の一部」が、ここで深く結びつきます。"}},{id:3,title:"ポジションを取る",subtitle:"ポーターのポジショニング",theme:"ポジショニングとトレードオフ",icon:"\uD83D\uDCCD",accent:"#ff8c7c",blurb:"戦略とは、「何をやるか」と同じくらい「何をやらないか」を決めること。第1章の「物語」に戻って、他社と違う立ち位置を取る意味と、そこに宿る真似されにくさを掘り下げます。",goals:["「業務の効率化」と「戦略」の違いを説明できる","トレードオフ（やらないこと）が競争優位を守る理由が言える","活動のつながり（フィット）で、真似されにくさをつくれる"],minutes:28,termKeys:["operational-effectiveness","positioning","trade-off","activity-system"],termPreview:["業務効率","ポジショニング","トレードオフ","活動システム"],status:"ready",scenes:[{kind:"story",id:"s3-notice",place:"商店街〈ひだまり通り〉 ─ 組合の掲示板",time:"三日目 午前9:30",lines:[{who:"narrator",text:"三日目の朝。ひだまり通りの入口の掲示板に、新しい貼り紙が出ていた。「駅前に〈まんぷく弁当〉オープン ── 来月第一月曜より」。"},{who:"narrator",text:"貼り紙の前で、大将が腕を組んでいる。いつもの白い前掛けが、今日は心なしか、小さく見えた。"},{who:"taisho",mood:"worry",text:"ナナ先生、{san}…聞いてくれ。日付まで決まっちまった。うちは来月から、あの大手と同じ昼の客を取り合うことになる。"},{who:"you",mood:"worry",text:"二日目に聞いた噂が、本当になったんですね…。"},{who:"taisho",text:"値段の勝負じゃ、とても勝てねえ。だったら、うちも弁当を始めるか？ 唐揚げに、カレーに、日替わりに…品数を増やして、値下げもして、とにかく張り合うしかないだろう。"},{who:"nana",mood:"think",text:"大将、その前に一つだけ聞かせて。「まんぷく弁当」の強みって、何だと思う？"},{who:"taisho",text:"そりゃあ、安くて、早くて、品数が多い。大量に仕入れて、同じ手順で作るから、うちの半分の値段で出せるんだ。"},{who:"nana",mood:"smile",text:"じゃあ、{san}にも聞くわね。ひだまり亭が、その「安くて、早くて、多い」で、チェーンに勝てると思う？"},{who:"you",mood:"think",text:"…正直、難しいと思います。仕入れの量も、人手も、店の数も、向こうのほうがずっと大きいですよね。"},{who:"nana",mood:"proud",text:"そう。相手の得意な勝負に、同じやり方で挑むと、どれだけ頑張っても「ちょっと下手なまんぷく弁当」にしかなれないの。"},{who:"taisho",mood:"surprise",text:"ちょっと下手な…まんぷく弁当。ぐうの音も出ねえな。じゃあ、どうすりゃいいんだ。"},{who:"nana",mood:"smile",text:"勝ち方は、「同じ道を速く走る」だけじゃないわ。今日の旅のテーマは、**「違う場所に立つ」**こと。研究所に戻って、ゆっくり考えましょう。"},{who:"narrator",text:"貼り紙の端が、春の風にひらひらと揺れた。{san}は、ノートの新しいページに、大きく一行書いた。「同じ土俵で戦わない、という勝ち方」。"}]},{kind:"explain",id:"s3-effectiveness",eyebrow:"核心① ／ 速く走るだけでは足りない",title:"「業務効率」と「戦略」は、別のもの",blocks:[{type:"p",text:"市民マラソンを思い浮かべてください。同じコースを、同じスタートラインから走るとき、勝つ方法は一つしかありません。**誰よりも速く走ること**です。"},{type:"p",text:"仕事の世界でも、これと同じ競争があります。同じ種類の仕事を、ライバルより速く・安く・うまくこなす力。これを[[operational-effectiveness|業務効率]]と呼びます。"},{type:"compare",left:{label:"業務効率",emoji:"\uD83C\uDFC3",items:["同じことを、ライバルよりうまくやる","速く・安く・無駄なく","「どれだけ上手か」の競争","例：仕込みの手順を見直して、時間を半分にする"],note:"同じ道を、速く走る"},right:{label:"戦略",emoji:"\uD83E\uDDED",items:["ライバルと違うことを、または違うやり方でやる","何を選び、何を選ばないか","「どこに立つか」の競争","例：昼休みの会社員に、出来立ての手作りで応える"],note:"違う道（違うレース）を選ぶ"},caption:"どちらが偉い、ではありません。目的が違うだけです。"},{type:"callout",tone:"why",title:"効率だけの競争は、なぜ苦しくなるの？",text:"効率のよいやり方は、**ライバルも学んで真似をします**。研修を受け、機械を入れ、手順を見直す。そうして全員が同じ方向に走ると、差は縮まり、結局は値段で競うしかなくなります。"},{type:"chain",title:"みんなが効率を競うと、どうなる？",nodes:[{label:"ある店が、効率化に成功する",emoji:"⚙️"},{label:"ライバルも、同じ方法を取り入れる",emoji:"\uD83D\uDC40"},{label:"どの店も、似たようなサービスになる",emoji:"\uD83E\uDE9E"},{label:"違いが値段だけになる",emoji:"\uD83C\uDFF7️"},{label:"値下げ合戦で、利益が削られる",emoji:"\uD83D\uDCC9",tone:"bad"}],caption:"効率を磨いた分だけ、お客さんにとっては「どこも同じ」になっていきます。"},{type:"callout",tone:"point",title:"効率は、悪者ではない",text:"誤解しないでください。効率が悪い店は、そもそも土俵に立てません。**効率は「必要だけれど、それだけでは足りない」**もの。足りない部分を埋めるのが、次に学ぶ「ポジション」です。"},{type:"nana",mood:"smile",text:"大将の「値下げして、品数を増やして張り合う」は、まさに効率の競争ね。得意な相手の土俵で、同じ種目に出ようとしているのよ。"}]},{kind:"explain",id:"s3-position",eyebrow:"核心② ／ 立ち位置の決め方",title:"ポジションは「誰に・何を・どうやって」で決まる",blocks:[{type:"p",text:"では、「違う場所に立つ」とは、具体的にどういうことでしょうか。その立ち位置を[[positioning|ポジショニング]]と言います。第2章で出会った「ポジショニング派」の中心にある考え方です。"},{type:"p",text:"ポジションは、気分で決めるものではなく、**三つの切り口**の組み合わせで決まります。経営学者のマイケル・ポーターは、論文『戦略とは何か』の中で、次の三つを挙げました。"},{type:"list",style:"number",title:"ポジションを決める三つの切り口",items:["**何を**（品ぞろえ）── どの商品・サービスに絞るか。例：煮物と焼き魚の昼定食だけ","**誰に**（お客さんのニーズ）── どんな人の、どんな困りごとに応えるか。例：昼休みの短い時間でも、ほっとする一食を食べたい会社員","**どうやって**（届け方）── どんな形でお客さんに届けるか。例：店の席で、出来立てを一人ずつ"]},{type:"compare",left:{label:"まんぷく弁当",emoji:"\uD83C\uDF71",items:["何を：幅広い品ぞろえ（唐揚げ・カレー・日替わり…）","誰に：できるだけ多くの人（急ぐ人も、安さ重視の人も）","どうやって：大量生産、受け取って、すぐ持ち帰る"],note:"広く・速く・安く"},right:{label:"ひだまり亭",emoji:"\uD83C\uDFEE",items:["何を：煮物と焼き魚を主役にした、絞った定食","誰に：昼休みに、ほっとする一食を食べたい会社員","どうやって：席に座って、出来立てを15分で、一人ずつ"],note:"絞って・手作りで・出来立て"},caption:"同じ「昼ごはん」でも、立っている場所がはっきり違います。"},{type:"callout",tone:"example",title:"第1章の「誰に」とのつながり",text:"第1章で、ひだまり亭は「昼に急ぐ会社員」に向けて物語を作りました。第2章の最後に出てきた通り、それは位置取りの考え方の入口でした。今回は、その「誰に」に「何を」と「どうやって」を重ねて、**立ち位置をはっきりさせていきます**。"},{type:"callout",tone:"warn",title:"「みんなに好かれたい」は、ポジションではない",text:"誰にでも合う店は、誰にとっても「いちばん」ではありません。全員を狙うと、**特徴のない店**になります。ポジションとは、「この人たちのための店です」と、はっきり言い切ることです。"},{type:"nana",mood:"think",text:"ここで大事なのは、ポジションは「何を選ぶか」と同時に「何を選ばないか」でできているということ。選ばないことには、ちゃんと理由があるの。次の場面で、その理由を見ていくわ。"}]},{kind:"story",id:"s3-hidamari",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"午後2:00",lines:[{who:"narrator",text:"研究所で一通り考えたあと、二人はひだまり亭に寄った。ちょうど昼のピークを終えた、少し静かな時間だ。"},{who:"taisho",mood:"think",text:"実はな、ナナ先生。昨日の夕方に、ちょっとだけ「試して」みたんだ。唐揚げ弁当とカレーを、今日の昼のメニューに足してみた。"},{who:"you",mood:"surprise",text:"えっ、もう始めていたんですか？ 結果は、どうでしたか？"},{who:"taisho",mood:"worry",text:"それがなあ…。唐揚げの下ごしらえとカレーの煮込みで、今朝の仕込みが回らなくなった。煮物にかける時間が、削られちまったんだ。"},{who:"narrator",text:"カウンターの端で、常連の会社員さんが、食べ終わったお椀をそっと置いた。"},{who:"narrator",text:"「大将、今日の煮物…なんだか、いつもと違うね。悪くはないけど、前のほうが、ほっとしたな」。"},{who:"taisho",mood:"worry",text:"…こういうことだ。言われて、初めて気づいた。"},{who:"you",mood:"think",text:"品数を増やしたのに、いちばんの看板が、少し弱くなってしまったんですね。"},{who:"nana",mood:"smile",text:"それが、戦略の世界でいう「**トレードオフ**」の顔よ。あれも、これも、と足していくと、いちばん大事なものが、いつの間にか削られていくの。"},{who:"taisho",text:"じゃあ、俺がやるべきは、足すことじゃなくて…。"},{who:"nana",mood:"proud",text:"そう、「**何をやらないか**」を決めること。さあ、ここからは、その考え方をきちんと整理していきましょう。"}]},{kind:"explain",id:"s3-tradeoff",eyebrow:"核心③ ／ 何をやらないか",title:"トレードオフ ── あれもこれもは、できない",blocks:[{type:"p",text:"ひだまり亭で起きたことを、もう一度ふり返ります。品数を増やしたら、看板の煮物が弱くなった。これは、大将の段取りが悪かったからではありません。**どの店にも起きる、構造的な関係**です。"},{type:"p",text:"あちらを取れば、こちらを諦めなければならない。この関係を[[trade-off|トレードオフ]]と呼びます。両立できないからこそ、「選ぶ（＝捨てる）」ことが必要になります。"},{type:"clash",title:"ひだまり亭に潜んでいた、両立しないもの",items:[{a:"出来立ての手作り",b:"注文してすぐ出す",result:"すぐ出すなら作り置きが要る。作り置きにすると、出来立ての良さが消える。どちらも満点にはできない。"},{a:"煮物に時間をかける",b:"品数を増やす",result:"朝の仕込みの時間は決まっている。品数が増えた分、煮物にかけられる時間が減っていく。"},{a:"店の席で出来立てを出す",b:"持ち帰り弁当の大量販売",result:"席で出来立てを出す店と、持ち帰りで数をさばく店では、必要な人手も、厨房の動き方も、お客さんの期待も違う。"}]},{type:"callout",tone:"point",title:"「やらないこと」は、強みを守る壁になる",text:"ポジションとは、**何かを選び、何かを捨てた結果**です。ひだまり亭が「弁当は、やらない」と決めれば、その分の時間と手を、煮物に全部かけられる。捨てることが、強みを守ることになります。"},{type:"callout",tone:"why",title:"なぜ、トレードオフが真似されにくさになるの？",text:"ライバルが「ひだまり亭の良さも、うちに足そう」と考えたとします。でも、足せば、元の良さ（安さ・早さ）が崩れてしまう。**真似するには、自分の強みを一部、手放さなければならない**。多くの会社は、そこで踏み切れません。"},{type:"p",text:"ポーターは、ある格安航空会社を例に挙げました。機内食も、座席指定も、乗り継ぎ便のサービスも、あえて「やらない」。その分、短い距離の路線に絞り、飛行機を降りてから次に飛ぶまでの時間を、徹底的に短くしました。**やらないことが多いほど、やることの切れ味が増す**、という例です。"},{type:"callout",tone:"example",title:"第1章を思い出して",text:"第1章の結びで、ナナ先生は言いました。「やらないことも、物語の一部」。それは、いま学んだトレードオフのことです。**戦略ストーリーの中には、「やること」と同じ重みで、「やらないこと」が書かれているのです**。"},{type:"nana",mood:"proud",text:"我慢している、のではなくて、**選んでいる**のよ。「やらない」と決めるたび、お客さんには、この店が誰のためにあるのか、はっきり伝わるの。"}]},{kind:"explain",id:"s3-fit",eyebrow:"核心④ ／ つながりが強さになる",title:"活動が輪になると、真似されにくくなる",blocks:[{type:"p",text:"ポジションを選んで、やらないことを決めたら、次は「実際の活動」を組み立てます。仕入れ、仕込み、調理、接客、売り方…。お店や会社の一つひとつの活動が、互いに支え合ってつながった全体を、[[activity-system|活動システム]]と呼びます。"},{type:"chain",title:"ひだまり亭の活動システム（輪になっている）",nodes:[{label:"朝市で、その日の魚と野菜を選ぶ",emoji:"\uD83D\uDC1F"},{label:"その日のうちに、手で仕込む",emoji:"\uD83D\uDD2A",linkLabel:"だから"},{label:"出来立てを、一人ずつ出す",emoji:"\uD83C\uDF72",linkLabel:"だから"},{label:"常連さんが、毎日通う",emoji:"\uD83E\uDDD1‍\uD83D\uDCBC",linkLabel:"だから"},{label:"来る人数が読めて、仕入れに無駄が出ない",emoji:"\uD83D\uDCCB",tone:"goal",linkLabel:"だから"}],caption:"最後の「仕入れが読める」は、最初の「朝市で選ぶ」を支えます。活動が輪になって、互いを強め合っています。"},{type:"callout",tone:"point",title:"一つの活動は真似できても、つながりは真似しにくい",text:"ライバルが「朝市で仕入れる」だけを真似するのは簡単です。でも、「仕込み」も「出来立て」も「常連づくり」も、全部まとめて真似するのは、とても大変。**真似されにくさは、強い活動ではなく、活動の「つながり」から生まれます**。"},{type:"formula",parts:[{label:"1つ目の活動",sub:"真似できる確率 8割"},{label:"2つ目の活動",sub:"8割"},{label:"3つ目の活動",sub:"8割"},{label:"4つ目の活動",sub:"8割"},{label:"全部を同時に",sub:"真似できる確率 約4割"}],ops:["\xd7","\xd7","\xd7","＝"],caption:"考え方の目安です。1つずつなら8割の確率で真似できても、4つがつながっていると、全部を同時に真似できる確率は 0.8\xd70.8\xd70.8\xd70.8≒0.41。つながりが増えるほど、真似は難しくなります。"},{type:"callout",tone:"why",title:"輪にするときの、三つのコツ",text:"これを、活動の「フィット（はまり具合）」と呼びます。\n\n**①ぴったり合っているか**：活動が、選んだポジションと噛み合っている。\n**②互いを強め合うか**：一つの活動が、別の活動の効果を高める。\n**③ムダなく組み合わさるか**：同じ手間が、複数の活動の役に立つ。"},{type:"nana",mood:"smile",text:"第1章の戦略ストーリーを覚えている？ 「だから」でつながった一本の筋。あれは、活動システムを、物語の言葉で言い直したものなのよ。"}]},{kind:"explain",id:"s3-wheels",eyebrow:"核心⑤ ／ 効率と戦略は、両輪",title:"方向を決めてから、速く走る",blocks:[{type:"p",text:"ここまで読むと、「効率化は意味がないのか」と思うかもしれません。答えは逆です。**戦略は、走る方向。効率は、走る速さ。** どちらが欠けても、遠くへは行けません。"},{type:"compare",left:{label:"方向がない、速さだけ",emoji:"\uD83C\uDF00",items:["みんなと同じ方向へ、全力で走る","ライバルも同じ道を走っている","速くなっても、差がつかない"],note:"走るほど、疲れていく"},right:{label:"方向があって、さらに速い",emoji:"\uD83D\uDE80",items:["選んだポジションに向かって走る","ライバルが入ってこない道を行く","速くなるほど、差が広がる"],note:"走るほど、遠くへ行ける"}},{type:"chain",title:"順番が大事",nodes:[{label:"ポジションを決める（誰に・何を・どうやって）",emoji:"\uD83D\uDCCD"},{label:"やらないことを決める（トレードオフ）",emoji:"✂️",linkLabel:"そのうえで"},{label:"活動をつなぐ（活動システム）",emoji:"\uD83D\uDD17",linkLabel:"そのうえで"},{label:"その中で、効率を磨く",emoji:"⚙️",tone:"goal",linkLabel:"そのうえで"}],caption:"効率は、最後に効かせます。順番を逆にすると、間違った方向へ、より速く進むことになります。"},{type:"callout",tone:"example",title:"ひだまり亭なら",text:"仕込みの段取りを見直して、朝の作業を20分短くする。これは効率化です。でも、その20分を**煮物にじっくりかけるために使う**なら、効率化がポジションを強めたことになります。同じ20分でも、何に使うかで意味が変わります。"},{type:"callout",tone:"warn",title:"効率化が、ポジションを壊すこともある",text:"「もっと早く出せるように、作り置きにしよう」。これも効率化です。でも、出来立てが売りの店では、**ポジションそのものを崩す**ことになります。効率化を考えるときは、「それは、選んだ立ち位置を強めるか、弱めるか」を必ず確かめます。"},{type:"nana",mood:"smile",text:"効率を磨くことは、大事。でも、それは「方向が決まったあと」の仕事なの。順番を間違えないようにね。"}]},{kind:"explain",id:"s3-link",eyebrow:"核心⑥ ／ 旅のつながり",title:"第1章・第2章と、ここでつながる",blocks:[{type:"p",text:"三日間の旅で出会った考え方は、実は一本の線でつながっています。ここで、いったん整理しておきましょう。"},{type:"chain",title:"ここまでの旅の、つながり",nodes:[{label:"第1章：戦略は「だから」でつながった物語（[[strategy-story|戦略ストーリー]]）",emoji:"\uD83D\uDCD6"},{label:"第2章：戦略の考え方には複数の流派がある。位置取りは、その一つ（[[positioning-school|ポジショニング派]]）",emoji:"\uD83D\uDDFA️",linkLabel:"その中の一つを"},{label:"第3章：位置を選び、やらないことを決め、活動をつなぐ（[[activity-system|活動システム]]）",emoji:"\uD83D\uDCCD",tone:"goal",linkLabel:"深掘りすると"}]},{type:"callout",tone:"point",title:"戦略ストーリーを、活動の言葉で言い直すと",text:"第1章の「だから」でつながった物語は、活動が互いを支え合う輪（活動システム）と、同じものです。違うのは、**物語は「なぜ、その順番か」を語り、活動システムは「どの活動が、どの活動を支えているか」を見せる**ところ。二つのめがねで、同じ戦略を見ているのです。"},{type:"list",style:"check",title:"日常で使える、ポジションの点検リスト",items:["誰に・何を・どうやって届ける店（会社）か、一言で言えるか","そのために、何を「やらない」と決めているか","一つひとつの活動は、選んだポジションを支えているか","活動どうしは、互いを強め合っているか（バラバラではないか）","ライバルがここまで真似するには、何を手放さなければならないか"]},{type:"callout",tone:"why",title:"ポジションは、一度決めたら永遠？",text:"いいえ。お客さんの好みも、ライバルの動きも、時間とともに変わります。ポジションは**定期的に点検するもの**です。そして点検の前に、「そもそも、この戦場は、どんな力関係でできているのか」を知っておく必要があります。"},{type:"nana",mood:"smile",text:"その「戦場の力関係」を読むのが、第4章の旅よ。まずは今日、ひだまり亭の戦い方を、実際に決めてみましょう。"}]},{kind:"terms",id:"s3-terms",title:"立ち位置に、名前をつけよう",intro:[{who:"nana",mood:"smile",text:"今日の旅で、名前のついた言葉が出てきたわね。大事な4つを、カードで確かめましょう。"},{who:"you",mood:"think",text:"「業務効率」と「トレードオフ」は、ひだまり亭の出来事で思い出せそうです。"},{who:"nana",mood:"proud",text:"その調子。「ポジショニング」と「活動システム」も、さっきの輪の図に戻れば、ちゃんと思い出せるわ。第1章の「戦略ストーリー」と、つなげて覚えてみてね。"}],terms:["operational-effectiveness","positioning","trade-off","activity-system"]},{kind:"choice",id:"s3-practice",title:"弁当チェーンに、ひだまり亭はどう立ち向かう？",intro:"午後四時。大将が、まんぷく弁当のチラシを手に戻ってきました。「来月から、あの店が始まる。うちは、どんな位置に立って、何をやらずに、どう店を回せばいい？ …{san}、さっき学んだことを使って、一緒に決めてくれないか」。",notes:["来月、駅前に弁当チェーン「まんぷく弁当」が開店。唐揚げ・カレー・日替わりなど品数が多く、価格はひだまり亭の約半分。注文から数分で持ち帰れる。","ひだまり亭の常連さんの多くは、「大将の煮物と、焼き魚が目当て」と話している。持ち帰り弁当は「冷めると、味が落ちる」という声もある。","昨日、唐揚げとカレーを足してみたところ、仕込みが回らず、看板の煮物の味が落ちた。","朝市の魚屋とは長い付き合いで、毎朝、その日のいちばんいい魚を回してもらえる。","昼の12時台は、席がほぼ埋まる。お客さんは、昼休みが短く、15分ほどで食べて戻りたい会社員が中心。"],nanaIntro:"今回も、正解を当てるクイズじゃないわ。**「位置」→「やらないこと」→「活動のつながり」**が、「だから」でつながるかを見てね。最初の「位置」は、観察メモの事実と合っているかも大事よ。",steps:[{id:"pos",nodeLabel:"位置",title:"ステップ1 ── どの場所に立つ？",question:"チェーンが来ます。ひだまり亭は、どの立ち位置を取りますか？ 観察メモを見ながら選んでください。",options:[{id:"copy",emoji:"\uD83C\uDF71",label:"チェーンと同じ土俵で戦う。弁当も始めて、値段と品数で張り合う",short:"チェーンと同じ土俵で戦う",start:"weak",reaction:"選んだ道の先を、一緒に見てみましょう。ただ、観察メモのとおり、仕入れの量も人手も向こうが上。**相手の得意な種目で戦う**ことになるわ。"},{id:"niche",emoji:"\uD83C\uDFEE",label:"昼休みの会社員に、出来立ての手作り定食を15分で。煮物と焼き魚に絞る",short:"出来立ての手作り定食に絞る",start:"good",reaction:"いい位置取りね。観察メモの事実——常連さんの目当て、朝市の魚、昼の席の埋まり方——と、ぴったり重なっているわ。ここから、「何をやらないか」を決めていきましょう。"},{id:"every",emoji:"\uD83C\uDF10",label:"昼も夜も、定食も弁当も。どんなお客さんも取りにいく",short:"全部のお客さんを取りにいく",start:"ok",reaction:"守りを固めたい気持ちは分かるわ。でも、**全員を狙う**と、誰にとっても「いちばん」ではなくなってしまうの。このまま、先を見てみましょう。"}]},{id:"drop",nodeLabel:"やらない",title:"ステップ2 ── 何を「やらない」と決める？",question:"位置を決めたら、その位置を守るために、何をやらないかを決めます。",options:[{id:"keepall",emoji:"\uD83D\uDCDA",label:"何もやめない。いまあるメニューも、新しい要望も、全部受ける",short:"何もやめない",requires:["every"],reaction:"「全部を取りにいく」という位置と、きれいにつながったわ。やめなければ、全部が続けられる…はず、よね。",mismatchReaction:"「やめない」のは、選ばない選択よ。位置を決めたのに何も捨てないと、位置は少しも絞られていかないわ。"},{id:"nodrop",emoji:"✂️",label:"弁当・唐揚げ・カレー、値下げ競争は、やらない。メニューは、煮物と焼き魚の定食に絞る",short:"弁当と値下げは、やらない",requires:["niche"],reaction:"つながったわ！ 「出来立ての手作り定食」という位置を守るために、**何を捨てるか**がはっきりしたわね。やらないと決めた分、煮物に全力をかけられるわ。",mismatchReaction:"「やらない」と決めること自体は大事。でも、前の位置と噛み合っていないわ。この「やらないこと」は、どんな位置を守るためのものかしら？"},{id:"cutcraft",emoji:"\uD83E\uDDCA",label:"手間のかかる手作りは減らし、作り置きと冷凍で、量と価格を合わせる",short:"手作りを減らし、量と価格で戦う",requires:["copy"],reaction:"「同じ土俵で戦う」という位置とは、つながったわ。チェーンに合わせるなら、手作りを減らして、量と価格に寄せる。筋は通っているわね。",mismatchReaction:"手作りを減らす選択は、いまの位置とつながっていないわ。「なぜ、そこを捨てるの？」と聞かれたら、説明できるかしら。"}]},{id:"link",nodeLabel:"活動のつながり",title:"ステップ3 ── 活動を、どうつなげる？",question:"最後は、仕入れ・仕込み・接客などの活動を、どう組み立てるかです。さっきの「輪」と、第1章の「だから」を思い出してね。",options:[{id:"cost",emoji:"⚙️",label:"注文から提供までの時間と原価を、徹底的に削る。効率化を最優先にする",short:"時間と原価を削る",requires:["copy","cutcraft"],reaction:"ここまでつながったわね。「同じ土俵」→「手作りを減らす」→「効率を徹底的に」。筋は通っているわ。ただ、この土俵がいちばん得意なのは誰か、結末で見てみましょう。",mismatchReaction:"効率化は大事。でも、これまでの選択と「だから」でつながっていないわ。何のための効率化なのか、説明できるかしら。"},{id:"addmore",emoji:"➕",label:"お客さんの要望に合わせて、メニューも営業時間も、増やし続ける",short:"要望に応えて増やし続ける",requires:["every","keepall"],reaction:"ここまで、一貫しているわね。でも、増やし続けた先に何が起きるか…結末で確かめましょう。",mismatchReaction:"増やし続けるやり方は、前の選択とつながらないわ。位置も、やらないことも、「増やす」方向じゃないでしょう？"},{id:"loop",emoji:"\uD83D\uDD17",label:"朝市の仕入れ → その日の手仕込み → 出来立てを一人ずつ → 常連さんの顔を覚えた接客、を輪にする",short:"仕入れから接客まで、輪にする",requires:["niche","nodrop"],reaction:"来たわね！ 活動が互いを支え合う**輪**になった。一つひとつは真似できても、輪ごと真似するのは難しいわ。第1章の「だから」が、第3章の「活動システム」とつながったのよ。",mismatchReaction:"活動をつなぐのは、素晴らしいこと。でも、前の位置とやらないことに噛み合っていないと、輪が閉じないわ。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"絞って、輪にして、守り抜いた",quality:1,when:{firstPick:["niche"],matches:[2]},narration:"まんぷく弁当が開店した月。ひだまり亭の昼は、少しだけお客さんが減りました。でも、一か月、二か月と経つうちに、「冷めた弁当より、あそこの出来立てがいい」という常連さんが戻ってきました。大将は言います。「値段で勝とうとしてたら、いまごろ疲れ切ってたな。やらないって決めたら、煮物が前より旨くなったんだ」。",nana:"いい戦略ね。**位置を選ぶ → やらないことを決める → 活動を輪にする**。第1章の「物語」と、今日の「活動システム」が、ぴったり重なったわ。効率化は、この輪の中で磨けばいい。ただ、この位置が、いつまで有効かは分からないわよ。戦場そのものが変わるかもしれない。それを読むのが、次の第4章よ。"},{id:"linked-copy",emoji:"\uD83C\uDFC3",title:"筋は通ったけれど、相手の得意な土俵だった",quality:.5,when:{firstPick:["copy"],matches:[2]},narration:"価格と速さで張り合うために、ひだまり亭は手作りを減らし、効率を磨きました。半年後、売上は何とか保てましたが、チェーンには価格でも速さでも追いつけません。「普通の弁当屋に近づいた」と、足が遠のいた常連さんもいました。",nana:"進め方は、「だから」でつながっていたわ。でも、**相手の得意な土俵で効率を磨いても、差は縮まらない**の。強い相手と同じ種目で戦うと、勝つのも、勝ち続けるのも、とても難しいのよ。違う位置を選ぶという道も、もう一度、考えてみて。"},{id:"linked-every",emoji:"\uD83E\uDDFA",title:"全部やったら、何の店か分からなくなった",quality:.4,when:{firstPick:["every"],matches:[2]},narration:"メニューも営業時間も増やし続けた結果、仕込みは追いつかず、看板の煮物は薄味になりました。「前のほうがよかった」という声が出始め、気づけば、ひだまり亭は、何の店なのか誰にも説明できなくなっていました。",nana:"一貫してはいたけれど、**やらないことを、一つも決めなかった**のが、最大の落とし穴よ。全員に好かれようとして、結局、誰の「いちばん」でもなくなってしまうの。トレードオフから逃げないで。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、位置とやり方が合わなくなった",quality:.4,when:{matches:[1]},narration:"最初の方針は悪くなかったのですが、途中で選んだ「やらないこと」や「活動」が、位置と噛み合わなくなりました。現場は混乱し、お客さんにも、店の違いがうまく伝わりません。",nana:"途中で、「それは、選んだ位置を守る動き？」が抜けてしまったわね。**位置・やらないこと・活動は、三つで一組**。もう一度、つなげて考えてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"点だけで、輪にならなかった",quality:.1,narration:"位置も、やらないことも、活動も、それぞれ別の方向を向いていました。気づけば、ひだまり亭が誰のための店なのか、お客さんにも、大将自身にも、分からなくなっていました。",nana:"一つひとつは悪くなくても、つながっていないと、強さも、真似されにくさも生まれないの。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"quiz",id:"s3-quiz",title:"確認クイズ",intro:"立ち位置の考え方を確かめましょう。「なぜ？」の解説まで読むのが、いちばんの復習よ。",questions:[{id:"q1",scenario:"ある定食屋が、仕込みの段取りを見直して、提供までの時間を半分にしました。ところが、ライバルの店も、すぐに同じ方法を取り入れました。",question:"この状況を、[[operational-effectiveness|業務効率]]と戦略の違いから説明すると、どれが近いでしょう？",options:[{text:"提供時間が半分になったのだから、これは、強い戦略である",feedback:"速くなったのは事実だけれど、ライバルがすぐ真似できるなら、差は残らないわ。「真似されにくいか」が、戦略かどうかの分かれ目よ。"},{text:"これは業務効率の改善で、大事だが、ライバルが真似すれば差が消えるので、それだけでは戦略にならない",feedback:"その通り！ 効率は必要な土台だけれど、真似されやすい。だから、効率だけでは差がつかないの。"},{text:"ライバルが真似したので、効率化は無意味だった",feedback:"無意味ではないわ。効率が悪ければ、そもそも土俵に立てない。**必要だけれど、それだけでは足りない**、というのが正しい見方よ。"},{text:"効率化は戦略の反対なので、やらないほうがよい",feedback:"反対ではないわ。「方向（戦略）」と「速さ（効率）」は、両輪。順番として、方向が先で、効率はそのあとよ。"}],answer:1,explanation:"業務効率は「同じ道を、より速く走る」力で、どの会社にも必要です。ただし、ライバルが真似しやすく、みんなが同じ方向に走るほど差は縮まります。**違う位置に立つ（戦略）ことが、効率の価値を活かす土台**になります。"},{id:"q2",scenario:"大将が「弁当も、唐揚げも始めよう」と言い出したとき、ナナ先生は「やらないと決めることが、強みを守る」と答えました。",question:"[[trade-off|トレードオフ]]が、真似されにくさを生むのはなぜでしょう？",options:[{text:"やらないことを増やすと、必ず値段が安くなるから",feedback:"安さが目的ではないわ。トレードオフは、「何かを選ぶと、何かを諦める」関係のこと。値段とは別の話よ。"},{text:"やらないことを秘密にしておけば、ライバルに気づかれないから",feedback:"隠すことが目的ではないの。むしろ「何をやらないか」は、お客さんにとって、店の個性としてはっきり伝わるものよ。"},{text:"真似するには、自分の強みの一部を手放す必要があり、多くの会社がそこで踏み切れないから",feedback:"正解！ 弁当チェーンがひだまり亭の良さを真似しようとすれば、安さや速さという自分の強みが崩れてしまう。だから、簡単には真似できないの。"},{text:"トレードオフは、大きな会社だけが使える仕組みだから",feedback:"規模は関係ないわ。むしろ、小さなお店ほど、「何をやらないか」を決めたときの効果は大きいの。"}],answer:2,explanation:"ライバルが同じ良さを足そうとすると、元の強みが崩れてしまいます。**真似するには、何かを手放さなければならない**ので、トレードオフが、真似されにくさの壁になります。第1章の「やらないことも物語の一部」は、このことでした。"},{id:"q3",scenario:"ライバルのカフェが、ひだまり亭の「朝市で仕入れる」という活動だけを真似しました。ところが、お客さんは、思ったほど増えませんでした。",question:"[[activity-system|活動システム]]の考え方から、いちばん近い理由はどれでしょう？",options:[{text:"仕込み・出来立ての提供・常連づくりなど、つながった活動全体を真似していないから",feedback:"その通り！ 一つの活動は真似できても、輪になった活動全体は、なかなか真似できない。つながりが、強さの源なの。"},{text:"朝市の仕入れだけが、特別に高い技術だから",feedback:"仕入れそのものは、誰でも真似しやすい活動よ。特別な技術があるわけではなく、**つながりの中で意味を持つ**のがポイント。"},{text:"ライバルが、お客さんに宣伝していなかったから",feedback:"宣伝の有無は、今回の論点ではないわ。活動が、互いに支え合っていたかどうかを見てみて。"},{text:"活動は、一つだけなら、どれも効果がないから",feedback:"「まったく効果がない」は言いすぎよ。ただ、他の活動とつながっていないと、効果が小さい、というのが正しいわ。"}],answer:0,explanation:"仕入れ・仕込み・提供・常連づくりが互いを支える**輪（活動システム）**になって、はじめて、真似されにくさが生まれます。第1章の「だから」でつながる戦略ストーリーを、活動の言葉で言い直した姿です。"}]},{kind:"summary",id:"s3-summary",title:"今日の学びを、一枚に",points:[{title:"効率と戦略は、別のもの",text:"[[operational-effectiveness]]は「同じ道を、速く走る」こと。必要な土台だけれど、真似されやすく、みんなが磨くほど差が縮まります。"},{title:"ポジションは、「誰に・何を・どうやって」",text:"[[positioning]]は、三つの切り口で決まる立ち位置のこと。「みんなに好かれる」は、ポジションではありません。"},{title:"やらないことが、強みを守る壁になる",text:"[[trade-off]]があるから、真似するには何かを手放さなければならない。「やらない」と決めることは、我慢ではなく、選んでいること。"},{title:"真似されにくさは、「つながり」から生まれる",text:"一つの活動は真似できても、[[activity-system]]（活動が輪になったもの）全体は真似しにくい。第1章の[[strategy-story]]の言い換えでもあります。"},{title:"順番は、方向が先、速さがあと",text:"ポジション → やらないこと → 活動のつながり、を決めてから、その中で効率を磨く。順番を逆にすると、間違った方向に、より速く進むことになります。"}],why:{title:"なぜ、これが大事なのか",text:"頑張っているのに利益が残らない。その原因の多くは、頑張り方ではなく**立っている場所**にあります。同じ土俵で効率を競うと、勝つのも、勝ち続けるのも難しい。**何をやり、何をやらないかを選び、それを活動のつながりで守る**。それが、長く続く強さになります。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま。今日は「違う場所に立つ」勝ち方を学んだわね。"},{who:"you",mood:"smile",text:"はい。「やらないと決める」のは、もっと怖いことだと思っていました。でも、強みを守る壁になるんですね。"},{who:"nana",mood:"smile",text:"そう。そして、第1章の「物語」も、第2章の「地図」も、ここで一本につながったでしょう？ 学びは、いつも積み重なっていくの。"}]}],clear:{perspective:{icon:"\uD83D\uDCCD",name:"やらないことを選ぶ目",tagline:"選ぶとは、捨てること",description:"何をやるかと同じ重みで、「何をやらないか」を考えられるようになりました。新しい施策を聞いたら、「それをやると、何を捨てることになる？」と、ひと呼吸おいて考えてみてください。",checks:["これをやると、何を捨てることになる？","ライバルがやらない（やれない）ことは何？","それは、ほかの活動とつながっている？"]},nana:[{who:"nana",mood:"smile",text:"おめでとう、{san}。第3の視点「やらないことを選ぶ目」を手に入れたわね。新しい提案を聞くたびに、「何を捨てることになるか」を、そっと考えてみて。"},{who:"you",mood:"smile",text:"はい！ 足し算だけじゃなくて、引き算も戦略なんですね。"},{who:"nana",mood:"proud",text:"その通り。立ち位置が決まったら、次は、その戦場そのものを読む旅よ。同じ努力でも、儲かりやすい業界と、儲かりにくい業界があるの。"}],teaser:"次の章：戦場を読む ─ 業界の「五つの力」を見抜き、進む道を選びます。同じ努力でも、儲かりやすい業界と、そうでない業界があるのはなぜでしょう？"}},{id:4,title:"戦場を読む",subtitle:"5フォースと基本戦略",theme:"ファイブフォース分析と3つの基本戦略",icon:"\uD83D\uDD2D",accent:"#74b3ff",blurb:"同じ努力でも、儲かりやすい業界と、儲かりにくい業界があります。その差を生む「五つの力」で戦場を読み、コスト・差別化・集中という3つの基本戦略から、進む道を選びます。",goals:["業界の儲けやすさを決める五つの力を説明できる","自分のお店・会社がどの力に弱いかを見立てられる","3つの基本戦略（コスト・差別化・集中）を使い分けられる"],minutes:30,termKeys:["industry-profitability","five-forces","cost-leadership","differentiation","focus"],termPreview:["業界の収益性","5つの競争要因","コストリーダーシップ","差別化","集中"],status:"ready",scenes:[{kind:"story",id:"s4-observatory",place:"ノースライト戦略研究所 ─ 屋上の観測所",time:"四日目 午前8:30",lines:[{who:"narrator",text:"四日目の朝。研究所の屋上には、小さな観測所がある。真鍮の望遠鏡が一台、港と商店街の方角に向けて据えられていた。"},{who:"nana",mood:"smile",text:"おはよう、{san}。昨日の旅で、ひだまり亭の「立ち位置」が決まったわね。今日は、その場所が**どんな戦場なのか**を、望遠鏡で見ていくわ。"},{who:"you",mood:"think",text:"戦場…ですか？ 立ち位置が決まったら、あとは頑張るだけ、というわけにはいかないんでしょうか。"},{who:"nana",text:"じゃあ、たとえ話をひとつ。夏祭りに、かき氷屋さんが二人いるわ。二人とも、同じ味、同じ値段、同じくらい頑張り屋よ。"},{who:"nana",mood:"think",text:"Aさんの屋台は、屋台が三つしかない神社の境内。氷は、近所の氷屋さんが毎年安く卸してくれる。Bさんは、同じかき氷屋が十軒も並ぶ参道。氷屋さんは一軒だけで、今年は値上げ。しかも、隣にはアイスの屋台まである。"},{who:"you",mood:"surprise",text:"それは…Aさんのほうが、ずっと楽に儲かりそうです。Bさんは、頑張っても、利益がほとんど残らないかも。"},{who:"nana",mood:"proud",text:"そう。**同じ頑張りでも、手元に残るお金は、立っている場所で大きく変わる**の。努力だけで、利益は決まらないのよ。"},{who:"you",mood:"think",text:"…戦場の「形」そのものが、儲けやすさを決めているんですね。"},{who:"nana",mood:"smile",text:"いい言葉ね。今日は、その戦場の形を読む、五枚のレンズを手に入れるわよ。ひだまり亭を覗くのは、そのあとで。"},{who:"narrator",text:"望遠鏡のレンズの向こうで、朝の商店街が、小さく光っていた。"}]},{kind:"explain",id:"s4-industry",eyebrow:"核心① ／ 儲けは、戦場の形で決まる",title:"利益を決めるのは、努力だけではない",blocks:[{type:"p",text:"かき氷屋のAさんとBさんは、同じ味で、同じくらい頑張っていました。それでも、手元に残るお金は大きく違いました。この「その場所の、もともとの儲けやすさ」を、[[industry-profitability|業界の収益性]]と呼びます。"},{type:"compare",left:{label:"儲かりやすい戦場",emoji:"\uD83C\uDF24️",items:["新しい屋台が、簡単には入ってこない","仕入先が複数あり、値上げを断れる","お客さんが、他の屋台へ移りにくい","代わりになる食べ物が少ない"],note:"利益が、手元に残りやすい"},right:{label:"儲かりにくい戦場",emoji:"\uD83C\uDF27️",items:["新しい屋台が、次々に出てくる","仕入先が一つだけで、値上げを飲まされる","お客さんが、安いほうへすぐ流れる","アイスなど、代わりが山ほどある"],note:"利益が、あちこちへ奪われやすい"},caption:"どちらが良い、悪い、ではなく、「いま自分はどちらにいるか」を知ることが大事です。"},{type:"callout",tone:"point",title:"戦略の第一歩は、戦場を読むこと",text:"頑張り方を考える前に、「この戦場は、そもそも、どれくらい儲かる形をしているのか」を確かめます。同じ努力でも、戦場が違えば、結果は変わります。"},{type:"callout",tone:"warn",title:"「儲からないのは、自分が下手だから」とは限らない",text:"利益が残らないとき、つい自分の頑張りが足りないせいだと考えがちです。でも、**戦場の形のせい**かもしれません。逆に、儲かりやすい業界にいても、自分のポジションが弱ければ、利益は残りません。見るべきは、戦場と、自分の立ち位置の**両方**です。"},{type:"nana",mood:"smile",text:"第3章で決めた「立ち位置」は、この戦場の中のどこに立つか、という話。戦場の形が分かると、その立ち位置の意味が、もっとはっきり見えてくるわ。"}]},{kind:"explain",id:"s4-forces",eyebrow:"核心② ／ 五つのレンズ",title:"戦場を読む「五つの力」",blocks:[{type:"p",text:"業界の儲けやすさを決める力は、大きく五つに整理できます。経営学者のマイケル・ポーターがまとめたもので、[[five-forces|5つの競争要因]]（ファイブフォース）と呼ばれます。まず、夏祭りの屋台で見てみましょう。"},{type:"forces",title:"夏祭りのかき氷屋で見る、五つの力",center:{name:"既存の競争",emoji:"⚔️",gist:"同じ参道に並ぶ、かき氷屋どうしの客の奪い合い。",note:"例：十軒が同じ味・同じ値段で並び、安くするしか差がつけられない"},forces:[{name:"新規参入の脅威",emoji:"\uD83D\uDEAA",gist:"儲かると見れば、新しい屋台が次々に入ってくる。入りやすいほど、利益は薄まる。",note:"例：人気の場所に、隣に同じ屋台が、もう一軒出た"},{name:"売り手の力",emoji:"\uD83D\uDCE6",gist:"仕入先が強いと、値上げを断れず、利益が削られる。",note:"例：氷屋が一軒だけで、「今年は値上げします」と言ってきた"},{name:"買い手の力",emoji:"\uD83E\uDDD1‍\uD83E\uDD1D‍\uD83E\uDDD1",gist:"お客さんが強いと、値引きを求められ、他へも移りやすい。",note:"例：どの屋台も同じなので、「安いほう」へ流れていく"},{name:"代替品の脅威",emoji:"\uD83C\uDF66",gist:"別のもので、同じ役割が果たされてしまう。",note:"例：かき氷の代わりに、アイスや冷たい飲み物が売れる"}]},{type:"callout",tone:"point",title:"力が強いほど、利益は奪われる",text:"五つの力は、どれも**「業界の利益を、誰かが持っていく力」**です。仕入先に、お客さんに、新しいライバルに、代わりの商品に、そして目の前のライバルに。力が強いほど、手元に残る利益は小さくなります。"},{type:"list",style:"check",title:"五つの力を見るときの、問いかけ",items:["**新規参入**：新しく入るのは簡単か？（資金・技術・ブランドの壁は高いか）","**代替品**：同じ悩みを、まったく別のもので解決できてしまわないか？","**買い手**：お客さんは、簡単に他へ移れるか？ 値段に敏感か？","**売り手**：仕入先は少数か？ 他に代わりはあるか？","**既存の競争**：ライバルは多いか？ 似たり寄ったりの店ばかりか？"]},{type:"nana",mood:"smile",text:"覚える順番は、気にしなくていいわ。「誰が、どの方向から、利益を引っ張っているか」を、一つずつ望遠鏡で確かめるだけ。さあ、ひだまり亭を覗いてみましょう。"}]},{kind:"story",id:"s4-pressure",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"午前11:00",lines:[{who:"narrator",text:"屋上を降りて、ひだまり亭へ。昼の仕込みの途中だというのに、大将の表情が、いつもより硬い。"},{who:"taisho",mood:"worry",text:"ナナ先生、{san}…。さっき、朝市の魚屋の源さんが来てな。「来月から、仕入れ値を少し上げさせてくれ」と言うんだ。"},{who:"you",mood:"surprise",text:"値上げ、ですか。ほかの魚屋さんに頼むことは、できないんですか？"},{who:"taisho",mood:"think",text:"朝いちばんに、ここまで良い魚を出してくれるのは、源さんだけなんだ。長い付き合いだしな。断りにくいんだよ。"},{who:"narrator",text:"そこへ、常連の会社員さんが顔を出した。「大将、最近、駅前のコンビニの惣菜、けっこう良くなってきたよ。いや、煮物は、やっぱりここじゃないとだめだけどね」。"},{who:"taisho",mood:"worry",text:"…来月はチェーンが開く。コンビニの惣菜もある。魚は値上がり。四方から押されてる気分だ。どこから手をつけたらいいか、分からん。"},{who:"nana",mood:"smile",text:"大将、いまの話、実は全部、**同じ地図の上**に置けるのよ。「新しい店が来る」「代わりの商品がある」「仕入先が値上げする」「お客さんが選べる」。方向は違うけれど、どれも、利益を引っ張る**力**なの。"},{who:"you",mood:"think",text:"バラバラに見えていた悩みが、一つの図に整理できる、ということですか？"},{who:"nana",mood:"proud",text:"そう。さあ、望遠鏡の五枚のレンズ、「五つの力」を、順番に見ていきましょう。"}]},{kind:"explain",id:"s4-apply",eyebrow:"核心③ ／ ひだまり亭を覗く",title:"五つの力を、ひだまり亭に当てはめる",blocks:[{type:"p",text:"ひだまり亭の「昼ごはん市場」を、五つの力で見てみましょう。ここまでに出てきた事実を材料に、力の強さを見立てます。"},{type:"forces",title:"ひだまり亭の戦場（昼ごはん市場）",center:{name:"既存の競争",emoji:"⚔️",level:"low",gist:"近所の定食屋は、あと2軒。どちらも夜が中心で、昼はほとんど閉めている。",note:"同じ昼の客を取り合う相手は、実はまだ少ない"},forces:[{name:"新規参入の脅威",emoji:"\uD83D\uDEAA",level:"high",gist:"来月、まんぷく弁当が開店。資金も仕入れ力も、桁違いの相手。",note:"いちばん大きな変化。昼の会社員を、まるごと取りにくる"},{name:"売り手の力",emoji:"\uD83D\uDCE6",level:"high",gist:"朝いちばんに良い魚を出してくれるのは、源さんだけ。値上げを断りにくい。",note:"仕入先が一か所に偏っているのが、弱点"},{name:"買い手の力",emoji:"\uD83E\uDDD1‍\uD83E\uDD1D‍\uD83E\uDDD1",level:"mid",gist:"常連さんは、煮物と焼き魚が目当てで、離れにくい。初めてのお客さんは、他へも流れやすい。",note:"常連づくりが、この力を弱める鍵"},{name:"代替品の脅威",emoji:"\uD83C\uDF59",level:"high",gist:"駅前のコンビニの惣菜や弁当が、手軽さで「昼の悩み」を解決してしまう。",note:"同じ「昼ごはん」でも、別の形で奪われる"}]},{type:"callout",tone:"point",title:"強い力と、弱い力を分けて見る",text:"ひだまり亭の場合、**強い力は「新規参入」「売り手」「代替品」**。弱い力は「既存の競争」です。全部を一度に何とかしようとせず、強い力から順に、手を打つ場所が決まります。"},{type:"callout",tone:"warn",title:"見立ては、絶対の答えではない",text:"力の強さは、集められた事実からの**見立て**です。事実が変われば、見立ても変わります。たとえば、近くにチェーンがもう一軒増えれば、「既存の競争」は一気に強くなります。**定期的に、読み直す**ことが大切です。"},{type:"nana",mood:"think",text:"大将が感じていた「四方から押されている感じ」は、実は、強い力が3つ重なっていたから。方向が分かれば、慌てずに済むわ。"}]},{kind:"explain",id:"s4-respond",eyebrow:"核心④ ／ 力に向き合う",title:"力を弱める、避ける、味方につける",blocks:[{type:"p",text:"戦場が読めたら、次は「その力を、どうやって弱めるか」を考えます。五つの力は、**戦略しだいで変えていける**ものです。ひだまり亭の例で、四つの向き合い方を見てみましょう。"},{type:"list",style:"number",title:"力への、向き合い方（ひだまり亭の例）",items:["**新規参入の脅威 → 壁をつくる**：真似されにくい活動の輪（第3章の[[activity-system]]）をつくり、チェーンが入ってきても、簡単には奪えない状態にする","**代替品の脅威 → 代わりでは満たせない価値をつくる**：コンビニでは出せない、出来立ての煮物と焼き魚で、「わざわざ来る理由」を持つ","**買い手の力 → 離れにくくする**：常連さんの顔と好みを覚える接客で、「ここでなければ」の関係を育てる","**売り手の力 → 頼り先を分ける**：仕入先を2か所に分け、一軒の値上げに振り回されないようにする"]},{type:"chain",title:"力を弱めると、利益はどうなる？",nodes:[{label:"強い力を見つける",emoji:"\uD83D\uDD0D"},{label:"その力を弱める手を打つ",emoji:"\uD83D\uDEE0️",linkLabel:"そのために"},{label:"利益が、奪われにくくなる",emoji:"\uD83D\uDEE1️",linkLabel:"だから"},{label:"手元に、利益が残る",emoji:"\uD83D\uDCB0",tone:"goal",linkLabel:"だから"}],caption:"五つの力は、与えられた条件ではなく、「向き合い方」で変えていけるものです。"},{type:"callout",tone:"why",title:"全部に、手は打てない",text:"四つとも全部に手を打とうとすると、人手も時間も足りなくなります。第3章の**トレードオフ**を思い出してください。どの力に手を打ち、どの力は受け入れるかを選ぶことも、戦略です。"},{type:"nana",mood:"smile",text:"「力を読む」→「強い力から手を打つ」。この順番で考えるだけで、慌てて値下げしたくなる気持ちが、ずいぶん落ち着くのよ。"}]},{kind:"explain",id:"s4-generic",eyebrow:"核心⑤ ／ 三つの基本戦略",title:"戦場での勝ち方は、三つに整理できる",blocks:[{type:"p",text:"戦場が読めたら、次は「どう勝つか」です。ポーターは、その基本の形を三つに整理しました。[[cost-leadership|コストリーダーシップ]]、[[differentiation|差別化]]、[[focus|集中]]です。"},{type:"map",title:"三つの基本戦略",regions:[{name:"コストリーダーシップ",emoji:"\uD83D\uDCB0",tagline:"安さで、広いお客さんを取る",tone:"sea",schools:[{name:"勝ち方",gist:"仕入れ・手順・規模を磨いて、業界でいちばん低いコストにする"},{name:"向いている店",gist:"規模が大きく、同じ手順で大量にさばける店",tag:"例：弁当チェーン"},{name:"落とし穴",gist:"「いちばん安い」でなければ意味が薄い。もっと安い相手が現れると、一気に苦しくなる"}]},{name:"差別化",emoji:"✨",tagline:"価格以外の違いで、選ばれる",tone:"lantern",schools:[{name:"勝ち方",gist:"お客さんが価値を感じる独自性をつくり、少し高くても選ばれるようにする"},{name:"向いている店",gist:"味・品質・ブランド・サービスで、違いを出せる店"},{name:"落とし穴",gist:"違いをつくり、守るのに費用がかかる。お客さんが価値を感じない違いは、意味がない"}]},{name:"集中",emoji:"\uD83C\uDFAF",tagline:"狭い一部に絞って、深く刺さる",tone:"sky",schools:[{name:"勝ち方",gist:"お客さんや商品を絞り、その中で、安さか違いのどちらかで勝つ"},{name:"向いている店",gist:"絞った相手の要望に、深く応えられる店",tag:"ひだまり亭"},{name:"落とし穴",gist:"絞った分野が小さすぎたり、大手が本気で入ってきたりすると、守りにくい"}]}]},{type:"callout",tone:"example",title:"ひだまり亭と、まんぷく弁当を並べると",text:"まんぷく弁当は、大量仕入れと標準化で勝つ**コストリーダーシップ**。ひだまり亭は、昼の会社員に絞り（**集中**）、手作りの味で選ばれる（**差別化**）、いわば「差別化\xd7集中」。第3章で選んだ立ち位置は、この地図で見ると、ここに当たります。"},{type:"callout",tone:"point",title:"どれが偉い、ではなく、戦場と自分に合うか",text:"三つの勝ち方に、優劣はありません。**読んだ戦場の力関係と、自分の強みに合っているか**で選びます。同じ戦場でも、規模の大きな会社と、小さな店では、選ぶ勝ち方が変わります。"},{type:"nana",mood:"smile",text:"第3章の「やらないこと」と、ここでつながるわ。基本戦略は、「何を捨てるか」の選び方でもあるの。安さを捨てて違いを取るのか、広さを捨てて深さを取るのか。"}]},{kind:"explain",id:"s4-stuck",eyebrow:"核心⑥ ／ いちばん危ない場所",title:"「どっちつかず」が、いちばん危ない",blocks:[{type:"p",text:"三つの勝ち方を見ると、つい、欲張りたくなります。「安くて、しかも違いがあって、しかも全員向け」。でも、ポーターは、これを**「どっちつかず」**と呼んで、いちばん危ない状態だと警告しました。"},{type:"chain",title:"どっちつかずの店は、どうなる？",nodes:[{label:"安さも、違いも、全部ほしくなる",emoji:"\uD83E\uDD32"},{label:"安さを足せば、違いが薄まる",emoji:"⚖️",linkLabel:"ところが"},{label:"違いを足せば、コストが膨らむ",emoji:"\uD83D\uDCC8",linkLabel:"ところが"},{label:"価格でも、味でも、一番になれない",emoji:"\uD83D\uDE15",tone:"bad",linkLabel:"結局"},{label:"選ばれる理由が、なくなる",emoji:"\uD83D\uDCC9",tone:"bad",linkLabel:"だから"}],caption:"第3章の「トレードオフ」から逃げた先に、「どっちつかず」が待っています。"},{type:"compare",left:{label:"どっちつかず",emoji:"\uD83C\uDF2B️",items:["そこそこの値段で、そこそこの味","全員を狙って、誰にも刺さらない","価格競争では、チェーンに勝てない"],note:"どこでも「いちばん」になれない"},right:{label:"一つに決める",emoji:"\uD83C\uDFAF",items:["安さに振り切る、または違いに振り切る","または、狭い相手に絞って深く応える","捨てるものがはっきりしている"],note:"どこかで「いちばん」になれる"}},{type:"callout",tone:"why",title:"なぜ、どっちつかずは危ないの？",text:"お客さんが店を選ぶとき、理由は「いちばん安い」か「ここでなければ」のどちらかです。**どちらでもない店は、選ばれる理由がありません**。安さで負け、違いでも負けて、気づけば、誰からも選ばれなくなります。"},{type:"list",style:"check",title:"戦場を読む、点検リスト",items:["利益を引っ張っている、いちばん強い力はどれか","その力を弱める手は、打てているか","自分の勝ち方は、コスト・差別化・集中のどれか","安さと違いの両方を、中途半端に狙っていないか","戦場の力関係は、最近変わっていないか（読み直したか）"]},{type:"nana",mood:"proud",text:"戦場を読めたら、もう半分は勝ったようなもの。次は、自分の内側にある**武器**を見つけにいくわよ。外の戦場と、内側の武器。この二つが合ったとき、戦略は完成するの。"}]},{kind:"terms",id:"s4-terms",title:"戦場に、名前をつけよう",intro:[{who:"nana",mood:"smile",text:"今日の旅で、名前のついた言葉が、いくつも出てきたわね。大事な5つを、カードで確かめましょう。"},{who:"you",mood:"think",text:"「5つの競争要因」と「業界の収益性」は、かき氷屋さんの話に戻れば思い出せそうです。"},{who:"nana",mood:"proud",text:"その調子。「コストリーダーシップ」「差別化」「集中」は、まんぷく弁当とひだまり亭を並べて覚えると、頭に入りやすいわよ。第3章の「トレードオフ」も、いっしょに思い出してね。"}],terms:["industry-profitability","five-forces","cost-leadership","differentiation","focus"]},{kind:"choice",id:"s4-practice",title:"ひだまり亭の戦場を読んで、進む道を決めよう",intro:"午後四時。屋上の望遠鏡の前で、大将が言いました。「戦場の形は、だいぶ分かってきた。…{san}、五つの力と三つの勝ち方を使って、ひだまり亭の進む道を、一緒に決めてくれないか」。",notes:["来月、駅前に「まんぷく弁当」が開店。昼の会社員をまとめて取りにくる、資金と仕入れ力のある相手。","駅前のコンビニの惣菜や弁当が手軽で、昼の会社員が、時々そちらにも流れている。","朝いちばんの魚は、源さん一軒が頼り。先日「来月から値上げ」と言われたが、断りにくい。","常連さんは、煮物と焼き魚が目当てで、「他の店では代わりがきかない」と話している。","近所の定食屋は、あと2軒あるが、どちらも夜が中心で、昼はほとんど閉めている。"],nanaIntro:"今回も、正解を当てるクイズじゃないわ。**「戦場の読み」→「勝ち方」→「打ち手」**が、「だから」でつながるかを見てね。最初の「読み」は、観察メモの事実と合っているかも大事よ。",steps:[{id:"read",nodeLabel:"戦場の読み",title:"ステップ1 ── 戦場を、どう読む？",question:"観察メモをもとに、五つの力の強さを、どう見立てますか？",options:[{id:"calm",emoji:"\uD83C\uDF24️",label:"ほとんど脅威はない。これまで通りで、大きな力は働いていない",short:"脅威は少ない",start:"weak",reaction:"観察メモを見直してみて。チェーンの出店、コンビニの惣菜、魚の値上げ…。**事実は、強い力が重なっていると言っているわ**。このまま進めて、何が起きるか見てみましょう。"},{id:"forces",emoji:"\uD83D\uDD2D",label:"新規参入（チェーン）・代替品（コンビニ）・売り手（魚屋）の力が強い。一方、常連さんは離れにくく、既存の競争は弱い",short:"参入・代替品・売り手が強い",start:"good",reaction:"いい読みね。観察メモの事実と、五つの力の見立てが、ぴったり重なっているわ。**強い力と弱い力を分けて見られている**のが、特にいいところよ。"},{id:"rivals",emoji:"⚔️",label:"近所の定食屋との、昼の客の奪い合いが、いちばんの脅威",short:"近所の定食屋との競争が最大",start:"ok",reaction:"近所の定食屋に目が向くのは、自然なことね。でも、観察メモを見て。**その2軒は、昼はほとんど閉めている**の。いま強いのは、別の力よ。先を見てみましょう。"}]},{id:"way",nodeLabel:"勝ち方",title:"ステップ2 ── どの勝ち方で戦う？",question:"戦場の読みに合う、基本の勝ち方を選んでください。",options:[{id:"cost",emoji:"\uD83D\uDCB0",label:"コストリーダーシップ。仕入れと手順を徹底的に磨いて、地域でいちばん安くする",short:"地域でいちばん安くする",requires:["rivals"],reaction:"「近所の定食屋との奪い合い」という読みと、つながったわ。ライバルが同じ土俵なら、安さで勝つのも、一つの筋ね。",mismatchReaction:"安さで勝つのは、立派な基本戦略。でも、いまの読みと「だから」でつながらないわ。なぜ、いま安さなのか、読みから説明できるかしら。"},{id:"middle",emoji:"\uD83C\uDF2B️",label:"全部のお客さんに、そこそこの値段で、そこそこの味を出す",short:"そこそこで、全員向け",requires:["calm"],reaction:"「脅威は少ない」という読みと、つながったわ。脅威がないなら、何も変えなくていい、という筋ね。",mismatchReaction:"全部を狙うのは、聞こえはいいけれど、いまの読みと噛み合っていないわ。強い力が働いているときに、そこそこの店で大丈夫かしら。"},{id:"focus",emoji:"\uD83C\uDFAF",label:"集中。昼休みの会社員に絞り、出来立ての手作りで、その人たちのために磨き上げる（差別化\xd7集中）",short:"昼の会社員に絞り、手作りで磨く",requires:["forces"],reaction:"つながったわ！ 強い力（参入・代替品）に対して、**弁当やコンビニでは代わりのきかない価値**を、絞った相手に届ける。第3章のポジションが、基本戦略として整理されたのよ。",mismatchReaction:"絞って磨くのは、素晴らしい勝ち方。でも、いまの読みと「だから」でつながっていないわ。なぜ、いま「集中」なのか、読みから説明できる？"}]},{id:"move",nodeLabel:"打ち手",title:"ステップ3 ── 強い力に、どう手を打つ？",question:"最後は、読んだ力に対する、具体的な打ち手です。第3章の「活動システム」も思い出してね。",options:[{id:"wait",emoji:"⏳",label:"チェーンの様子を見てから、お客さんの動きに合わせて考える",short:"様子を見る",requires:["calm","middle"],reaction:"ここまで、一貫しているわね。でも、強い力が来てから動くのでは…結末で確かめましょう。",mismatchReaction:"様子見は、時に必要。でも、前の選択とつながっていないわ。「様子を見る」理由を、読みから説明できる？"},{id:"price",emoji:"\uD83C\uDFF7️",label:"チェーンに合わせて、値下げと原価削減を進める",short:"値下げと原価削減",requires:["rivals","cost"],reaction:"「奪い合い」→「安さで勝つ」→「値下げと原価削減」。筋は通っているわ。ただ、その土俵に、本当に立てるのかは、結末で見てみましょう。",mismatchReaction:"値下げは、安さで勝つ戦略の一部。でも、これまでの選択と噛み合っていないわ。"},{id:"shield",emoji:"\uD83D\uDEE1️",label:"常連さんの顔と好みを覚えて離れにくくし、魚の仕入先を2か所に分け、出来立ての輪で、チェーンとコンビニに壁をつくる",short:"常連づくり・仕入先分散・輪の壁",requires:["forces","focus"],reaction:"来たわね！ 買い手を離れにくくし、売り手への依存を減らし、参入と代替品には、真似されにくい活動の輪で壁をつくる。**強い力それぞれに、手が打てている**わ。",mismatchReaction:"力に手を打つのは、大事なこと。でも、前の読みと勝ち方に噛み合っていないと、どの力を弱めたいのか、狙いがぼやけてしまうわ。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"力を読んで、絞って、手を打った",quality:1,when:{firstPick:["forces"],matches:[2]},narration:"まんぷく弁当が開いた月。昼の客足は、一時、少し落ちました。でも、大将は慌てませんでした。常連さんは離れず、源さんの値上げにも、二か所目の仕入先があるおかげで、冷静に向き合えました。「どこが強くて、どこが弱いか分かってると、慌てずに済むな」と、大将は笑います。",nana:"いい戦場の読み方ね。**強い力を見つける → 勝ち方を選ぶ → 力に手を打つ**。第3章の「ポジション」と「活動システム」が、戦場の読みとつながったわ。ひだまり亭が戦う場所と、勝ち方が、はっきりしたわね。でも、その勝ち方を支える、**自分の中にある武器**は何かしら？ それを探すのが、次の第5章よ。"},{id:"linked-rivals",emoji:"\uD83C\uDFF7️",title:"筋は通ったけれど、読みが外れていた",quality:.5,when:{firstPick:["rivals"],matches:[2]},narration:"近所の定食屋との奪い合いに備えて、値下げと原価削減を進めました。ところが、本当に脅威だったのは、駅前のチェーンと、コンビニの惣菜でした。価格競争では大手に太刀打ちできず、利益だけが細っていきました。",nana:"進め方は、「だから」でつながっていたわ。でも、**最初の読みが外れていると、きれいに進めるほど、ずれが大きくなる**の。戦場を読み違えると、全部がずれてしまうのよ。観察メモの事実を、もう一度見直してみて。"},{id:"linked-calm",emoji:"\uD83C\uDF2B️",title:"脅威を見ないまま、どっちつかずになった",quality:.3,when:{firstPick:["calm"],matches:[2]},narration:"「脅威は少ない」と読んで、何も変えず、全員向けのそこそこの店のまま、様子を見ました。チェーンが開店し、コンビニの惣菜も力をつけると、「安さ」でも「違い」でも選ばれず、お客さんは、少しずつ離れていきました。",nana:"一貫してはいたけれど、**脅威を見ないまま**、どっちつかずになってしまったわね。戦場を読むのは、悪い知らせを見つけるためでもあるの。強い力を、きちんと見るところから、やり直しましょう。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、読みと打ち手が噛み合わなくなった",quality:.4,when:{matches:[1]},narration:"最初の読みは悪くなかったのですが、途中で選んだ勝ち方や打ち手が、読みと噛み合わなくなりました。どの力に対して手を打っているのか、現場にも伝わりません。",nana:"途中で、「それは、どの力を弱める動き？」が抜けてしまったわね。**読み・勝ち方・打ち手は、三つで一組**。もう一度、つなげて考えてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"読みも、勝ち方も、打ち手もバラバラだった",quality:.1,narration:"戦場の読みも、勝ち方も、打ち手も、それぞれ別の方向を向いていました。気づけば、どの力に、どう向き合っているのか、大将にも、分からなくなっていました。",nana:"一つひとつは悪くなくても、つながっていないと、戦場は読めても、勝てないの。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"quiz",id:"s4-quiz",title:"確認クイズ",intro:"戦場の読み方を確かめましょう。「なぜ？」の解説まで読むのが、いちばんの復習よ。",questions:[{id:"q1",scenario:"魚屋の源さんが、「来月から仕入れ値を上げる」と言ってきました。ひだまり亭には、朝いちばんに良い魚を出してくれる店が、ほかにありません。",question:"[[five-forces|5つの競争要因]]のうち、いま強く働いているのは、どの力でしょう？",options:[{text:"代替品の脅威",feedback:"代替品は、「別のもので同じ役割を果たされてしまう」力。コンビニの惣菜などが当たるわ。魚の値上げとは、別の方向の力よ。"},{text:"買い手の力",feedback:"買い手の力は、お客さんの強さのこと。今回は、仕入先からの話だから、反対側の力ね。"},{text:"売り手の力",feedback:"その通り！ 仕入先が少ないほど、値上げを断りにくい。これが「売り手の力」よ。仕入先を分けることで、弱められるわ。"},{text:"新規参入の脅威",feedback:"新規参入は、新しい店が入ってくる力。まんぷく弁当の出店が当たるわね。魚の値上げは、仕入先の力の話よ。"}],answer:2,explanation:"仕入先が少数で、代わりがきかないとき、**売り手の力**は強くなります。値上げを断れず、利益が削られます。対策は、仕入先を複数に分けて、依存を減らすことです。"},{id:"q2",scenario:"ある店は、「地域でいちばん安く」を掲げ、仕入れも手順も徹底的に削っています。別の店は、独自の味で、少し高くても選ばれています。",question:"この二つの店の勝ち方を、三つの基本戦略で言うと、どう整理できるでしょう？",options:[{text:"前者はコストリーダーシップ、後者は差別化",feedback:"正解！ 「安さで広く取る」のがコストリーダーシップ、「価格以外の違いで選ばれる」のが差別化よ。"},{text:"前者は差別化、後者はコストリーダーシップ",feedback:"逆になっているわ。価格を武器にするのがコストリーダーシップ、違いを武器にするのが差別化よ。"},{text:"前者は集中、後者はコストリーダーシップ",feedback:"集中は、お客さんや商品を「狭く絞る」勝ち方。今回の二つの店は、絞っているかどうかではなく、「何を武器にしているか」で分けるのよ。"},{text:"どちらも集中",feedback:"二つの店とも、お客さんを絞っているとは書かれていないわ。武器が「安さ」と「違い」で分かれているのがポイントよ。"}],answer:0,explanation:"コストリーダーシップは**安さ**、差別化は**価格以外の違い**、集中は**範囲を絞る**ことが、それぞれの核です。第3章の「やらないことを決める」とも、つながっています。"},{id:"q3",scenario:"ある店が、価格ではチェーンに勝てず、味でも独自性が弱く、お客さんが少しずつ減っています。",question:"この状態を、基本戦略の考え方から説明すると、どれがいちばん近いでしょう？",options:[{text:"どの力も弱いので、そのまま続ければよい",feedback:"お客さんが減っているのは、何かが強く働いているサイン。「そのまま続ける」では、状況は変わらないわ。"},{text:"安さも違いも中途半端な「どっちつかず」で、選ばれる理由が薄くなっている",feedback:"その通り！ お客さんが店を選ぶ理由は、「いちばん安い」か「ここでなければ」。どちらでもない店は、選ばれる理由を失ってしまうの。"},{text:"お客さんの見る目が厳しいだけで、戦略の問題ではない",feedback:"お客さんのせいにしても、状況は変わらないわ。むしろ、選ばれる理由をつくれていないのが、戦略の問題よ。"},{text:"全員を狙えている、集中戦略が成功した姿",feedback:"集中は、狭く絞る勝ち方。全員を狙っている状態は、集中とは正反対よ。"}],answer:1,explanation:"安さでも違いでも一番になれない状態が**どっちつかず**です。第3章の[[trade-off|トレードオフ]]から逃げて、全部を取りにいくと、この状態に陥りがちです。**何を捨てるかを決めること**が、勝ち方を決めることです。"}]},{kind:"summary",id:"s4-summary",title:"今日の学びを、一枚に",points:[{title:"利益は、戦場の形でも決まる",text:"同じ頑張りでも、手元に残る利益は、戦場で変わります。この「もともとの儲けやすさ」が[[industry-profitability]]です。"},{title:"五つの力で、戦場を読む",text:"[[five-forces]]は、新規参入・代替品・買い手・売り手・既存の競争の5つ。力が強いほど、利益は奪われます。"},{title:"強い力から、手を打つ",text:"壁をつくる、代わりでは満たせない価値をつくる、離れにくくする、頼り先を分ける。全部は無理なので、強い力から選びます。"},{title:"勝ち方は、三つに整理できる",text:"安さの[[cost-leadership]]、違いの[[differentiation]]、絞る[[focus]]。どれが偉い、ではなく、戦場と自分に合うかで選びます。"},{title:"どっちつかずが、いちばん危ない",text:"安さも違いも欲張ると、選ばれる理由が消えます。第3章の[[trade-off]]のとおり、何を捨てるかを決めることが、勝ち方になります。"}],why:{title:"なぜ、これが大事なのか",text:"努力が報われない原因が、自分の中ではなく、**戦場の形**にあることがあります。戦う前に戦場を読めば、「頑張る場所」を選べますし、悪い知らせにも、慌てずに向き合えます。**戦場を読む力は、無駄な戦いを避け、勝てる戦いに力を集める力**です。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま。今日は、望遠鏡で戦場の形を読む旅だったわね。"},{who:"you",mood:"smile",text:"はい。大将の悩みが、五つの力に整理できたとき、「慌てなくていいんだ」と思えました。"},{who:"nana",mood:"smile",text:"それが、戦場を読む本当の効果。第3章の「ポジション」や「トレードオフ」が、ここでも生きていたでしょう？ 学びは、積み重なっていくの。"}]}],clear:{perspective:{icon:"\uD83D\uDD2D",name:"力関係を見抜く目",tagline:"戦う前に、戦場を読む",description:"努力の前に、その業界で誰が力を持っているかを見立てられるようになりました。うまくいかないときは、自分の頑張りだけでなく、「どの力が、いま強く働いているか」を見てみてください。",checks:["買い手と売り手、どちらが強い？","新しく参入されやすい？ 代わりになるものは？","どの基本戦略（コスト・差別化・集中）で戦う？"]},nana:[{who:"nana",mood:"smile",text:"おめでとう、{san}。第4の視点「力関係を見抜く目」を手に入れたわね。新しい仕事の話を聞いたら、まず、どの力が強いかを考えてみて。"},{who:"you",mood:"smile",text:"はい！ 悪い知らせも、「どの力が強まったか」と考えれば、落ち着いて見られそうです。"},{who:"nana",mood:"proud",text:"その通り。ここまでが「外」の戦場。次は、自分の「内側」にある武器を見つけにいくわよ。大将の煮物と焼き魚は、本当に武器と呼べるのかしら？"}],teaser:"次の章：自分の武器を知る ─ 外ではなく内側から、競争優位の源を探します。第1章で出会った、大将の煮物と焼き魚が、本当に「武器」と呼べるのかを確かめます。"}},{id:5,title:"自分の武器を知る",subtitle:"リソース・ベースド・ビューとVRIO",theme:"経営資源に基づく戦略（RBV）とVRIO分析",icon:"\uD83D\uDDE1️",accent:"#a58bff",blurb:"外の環境だけでなく、内側にある「自分の武器」から戦略を考える方法です。持っている資源のうち、何が本当に競争優位になるのかを、VRIOの4つの問いで見極めます。",goals:["自社の経営資源（強み）を棚卸しできる","VRIOの4つの問いで、強みが競争優位になるか判定できる","外から見る視点（第3・4章）と内から見る視点を組み合わせられる"],minutes:28,termKeys:["rbv","resources","vrio","inimitability","core-competence"],termPreview:["リソース・ベースド・ビュー","経営資源","VRIO","模倣困難性","コアコンピタンス"],status:"ready",scenes:[{kind:"story",id:"s5-kitchen",place:"商店街〈ひだまり通り〉 ─ ひだまり亭の厨房",time:"五日目 午前7:00",lines:[{who:"narrator",text:"五日目の朝。まだ暖簾の出ていないひだまり亭の厨房で、大将が煮物の火加減を見ている。出汁の香りが、勝手口まで届いていた。"},{who:"nana",mood:"smile",text:"おはよう、大将。昨日は、戦場の形をみんなで読んだわね。今日は、その戦場に持っていく**手の中の道具**を見せてもらうわ。"},{who:"taisho",mood:"smile",text:"手の中の道具？ そりゃあ、煮物の腕だろう。うちの武器といえば、それしかねえ。"},{who:"nana",text:"じゃあ、ひとつ、やってみましょう。この店で**「ある」ものを、思いつくだけ全部**挙げてみて。{san}は、メモを取ってね。"},{who:"taisho",mood:"think",text:"えーと…火力の強いガスコンロ。業務用の冷蔵庫。商店街の角っていう店の場所。煮物の腕。朝市の源さんとの付き合い。それに、常連さんの顔と好みを、だいたい全部覚えてる。"},{who:"you",mood:"think",text:"ノートに書いたら、六つになりました。どれも、この店が「持っているもの」ですね。"},{who:"nana",mood:"proud",text:"そう。でもね、大将。「ある」ことと、「効く」ことは、**別のこと**なの。"},{who:"you",mood:"surprise",text:"あるのに、効かないものがあるんですか？"},{who:"nana",mood:"smile",text:"釣りの名人は、高い竿を持っているから釣れるわけじゃないでしょう？ 高い竿を持つ人は、ほかにもたくさんいるもの。名人の強さは、別のところにあるはずよ。"},{who:"taisho",mood:"worry",text:"…つまり、うちの煮物の腕も、本当に武器かどうか、疑ってるってことかい？"},{who:"nana",mood:"smile",text:"疑うんじゃなくて、**確かめる**の。本物の武器は、確かめたあとも、ちゃんと残るから。今日は、その確かめ方を覚えましょう。"}]},{kind:"explain",id:"s5-rbv",eyebrow:"核心① ／ 外から見るか、内から見るか",title:"競争優位は、「内側」からも生まれる",blocks:[{type:"p",text:"同じ釣り場で、同じ時間に釣り糸を垂らしても、釣果に大きな差が出ることがあります。その差は、釣り場の違いではなく、**その人の腕、道具、経験**といった「内側」にある。こう考えるのが、[[rbv|リソース・ベースド・ビュー]]（RBV）です。"},{type:"compare",left:{label:"外から見る（第3・4章）",emoji:"\uD83D\uDD2D",items:["どこで戦うか、どの立ち位置に立つか","戦場（五つの力）は、儲かる形をしているか","出発点は「外の環境」","ポジショニング派の見方"],note:"戦場から、戦略を考える"},right:{label:"内から見る（今日）",emoji:"\uD83D\uDDE1️",items:["自分は、何を持っているか","そのうち、他社と差がつくものはどれか","出発点は「内側の資源」","リソース・ベースド・ビュー"],note:"武器から、戦略を考える"},caption:"どちらが正しい、ではありません。どちらも「象の一部」です（第2章を思い出して）。"},{type:"callout",tone:"why",title:"なぜ、内側を見る必要があるの？",text:"同じ業界にいる店どうしでも、利益に大きな差がつくことがあります。業界（外）が同じなら、その差を生んでいるのは、**それぞれが持っているもの（内）**です。外が同じなら、差は内にあります。"},{type:"chain",title:"外と内を、つなげる",nodes:[{label:"戦場を読む（五つの力）",emoji:"\uD83D\uDD2D"},{label:"自分の武器を知る（内側の資源）",emoji:"\uD83D\uDDE1️",linkLabel:"そのうえで"},{label:"戦場と武器が合う勝ち方を選ぶ",emoji:"\uD83E\uDDE9",tone:"goal",linkLabel:"だから"}],caption:"外だけ見ても、内だけ見ても、戦略は完成しません。両方が合ったとき、はじめて筋が通ります。"},{type:"nana",mood:"smile",text:"昨日は戦場を読んで、今日は手の中の道具を調べる。この二つがそろって、はじめて「どこで、何をもって戦うか」が決まるのよ。"}]},{kind:"explain",id:"s5-inventory",eyebrow:"核心② ／ 持っているものを並べる",title:"武器の候補は、「見えにくい資源」にある",blocks:[{type:"p",text:"武器探しは、まず「何を持っているか」を並べるところから始まります。会社やお店が持つ、事業に使えるもの全般を、[[resources|経営資源]]と呼びます。"},{type:"compare",left:{label:"見える資源",emoji:"\uD83C\uDFEA",items:["厨房の設備・調理器具","お店の場所・建物","手元のお金（資金）","仕入れた食材"],note:"お金があれば、買える"},right:{label:"見えにくい資源",emoji:"\uD83C\uDF31",items:["大将の腕・手仕込みの技","朝市の魚屋さんとの信頼関係","常連さんの顔と好みの記憶","「ここの煮物」という評判"],note:"時間をかけて、育てるしかない"},caption:"ひだまり亭の棚卸しは、この二つに分けると整理しやすくなります。"},{type:"callout",tone:"point",title:"差をつくるのは、たいてい「見えにくい資源」",text:"お金で買える資源は、**ライバルも買えます**。高性能なオーブンを入れても、チェーンはもっと安く、もっと台数を入れられます。一方、三十年かけた腕や、二十年の信頼は、お金を積んでも、一朝一夕には手に入りません。"},{type:"callout",tone:"warn",title:"「ある」と「効く」は、別のこと",text:"資源を並べただけでは、まだ武器とは呼べません。ある資源が、**本当に競争優位になるのか**は、別に確かめる必要があります。立地や設備のように「あるけれど、効かない」ものも、混じっているからです。"},{type:"list",style:"check",title:"棚卸しのコツ",items:["**できること**：腕・技術・ノウハウ（人に宿るもの）","**持っている関係**：取引先・お客さん・地域との結びつき","**積み上げたもの**：評判・信頼・ブランド・歴史","**設備・場所・資金**：買える、または借りられるもの","まず「全部書く」。良し悪しの判断は、あとで"]},{type:"nana",mood:"smile",text:"全部書き出したら、次は「ふるい」にかけるの。何を残して、何を外すか。そのための道具が、VRIOという4つの問いよ。"}]},{kind:"story",id:"s5-oven",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"午後2:30",lines:[{who:"narrator",text:"昼の営業を終えた店内。大将が、分厚いカタログを抱えて、そわそわと二人のテーブルにやってきた。"},{who:"taisho",mood:"smile",text:"なあ、ナナ先生。これを見てくれ。最新の高性能オーブンだ。焼き魚が、速くて、ムラなく仕上がる。百万円だが、これでチェーンにも負けねえ設備になる。"},{who:"you",mood:"think",text:"たしかに、立派ですね。ただ…お金を出せば、誰でも買えるんじゃないでしょうか。"},{who:"taisho",mood:"worry",text:"そりゃあ、そうだが。買えば、確実に良くなるだろう？"},{who:"nana",mood:"think",text:"大将。その一台、まんぷく弁当も、近所の定食屋さんも、買えるわよね？"},{who:"taisho",mood:"surprise",text:"…買えるな。むしろ、チェーンのほうが、安く何台でも買えちまう。"},{who:"nana",mood:"smile",text:"**買える武器は、相手も買える**の。そこに差は生まれにくいわ。じゃあ、買えないものは、何だと思う？"},{who:"taisho",mood:"think",text:"…三十年かけた煮物の腕。源さんとの二十年の付き合い。常連さんの信頼。どれも、金じゃ買えねえな。"},{who:"nana",mood:"proud",text:"そこに気づけたなら、もう半分来ているわ。あとは、「効く武器」を見分ける**四つの問い**を覚えるだけ。さあ、行くわよ。"}]},{kind:"explain",id:"s5-vrio",eyebrow:"核心③ ／ 4つの問い",title:"武器かどうかを見極める、VRIOの4つの問い",blocks:[{type:"p",text:"棚卸しした資源が、本当に武器になるのかを調べる道具が、[[vrio|VRIO]]（ヴリオ）です。4つの問いに、**順番に**答えていきます。「いいえ」が出た時点で、そこが結論です。"},{type:"ladder",title:"VRIOの4つの問い",steps:[{letter:"V",name:"Value ／ 価値",question:"お客さんにとって、価値があるか？（売上や利益につながる力になるか）",no:"競争劣位。持っていても武器にならず、むしろ負担になる",example:"煮物の腕 → 常連さんが「ここでなければ」と通う理由になっている"},{letter:"R",name:"Rarity ／ 希少性",question:"ライバルの中で、持っているところは少ないか？",no:"競争均衡。みんな持っているので、差にならない",example:"ガスコンロや冷蔵庫 → どの店も持っている"},{letter:"I",name:"Imitability ／ 真似されにくさ",question:"ライバルが真似しようとすると、時間やコストが大きくかかるか？",no:"一時的な競争優位。すぐに追いつかれてしまう",example:"最新のオーブン → お金があれば、誰でも買える"},{letter:"O",name:"Organization ／ 組織",question:"その資源を、店・会社の仕組みとして、活かしきれているか？",no:"宝の持ち腐れ。持っていても、使いこなせていない",example:"煮物の腕が大将ひとりに頼りきりで、休むと店が回らない"}],goal:{label:"持続的な競争優位",text:"4つとも「はい」なら、本物の武器。長く、お客さんに選ばれ続ける力になります。"}},{type:"callout",tone:"why",title:"なぜ、この順番なの？",text:"お客さんが価値を感じないものは、他がどれだけ立派でも、意味がありません（V）。価値があっても、誰もが持っているなら差になりません（R）。珍しくても、すぐ真似されるなら続きません（I）。最後に、持っていても使いこなせなければ、効果が出ません（O）。**手前の問いほど、土台**です。"},{type:"callout",tone:"point",title:"「いいえ」は、弱点の場所を教えてくれる",text:"「いいえ」が出ても、それで終わりではありません。**どの問いで止まったかが、直すべき場所**です。たとえばOで止まったなら、仕組みを整えれば、武器になる可能性があります。"},{type:"nana",mood:"smile",text:"4つ全部に「はい」と言えるものは、実はとても少ないの。だからこそ、見つけたら、大事に育てる価値があるのよ。"}]},{kind:"explain",id:"s5-apply",eyebrow:"核心④ ／ ひだまり亭の判定",title:"ひだまり亭の資源を、仕分けてみる",blocks:[{type:"p",text:"厨房で挙げた6つ（のうち、これから買う候補を1つ含む）を、VRIOで仕分けてみます。ここまでの旅で出てきた事実が、判断の材料です。"},{type:"matrix",title:"ひだまり亭のVRIO判定",columns:["価値","希少","真似にくい","組織"],rows:[{name:"煮物の腕と手仕込みの技",emoji:"\uD83C\uDF72",marks:["yes","yes","yes","maybe"],verdict:"ほぼ武器（組織が課題）",tone:"good",note:"三十年かけた技で、他の店では代わりがきかない。ただ、仕込みの多くを大将ひとりが担っていて、店の仕組みとして活かしきれていない。"},{name:"源さんとの二十年の付き合い",emoji:"\uD83D\uDC1F",marks:["yes","yes","yes","maybe"],verdict:"強い武器（頼りすぎに注意）",tone:"good",note:"朝いちばんの良い魚は、他の店には回ってこない。信頼は、お金で買えない。ただ、仕入先が一軒に偏っていて、第4章の「売り手の力」に弱い。"},{name:"常連さんの顔と好みの記憶",emoji:"\uD83E\uDDD1‍\uD83D\uDCBC",marks:["yes","maybe","yes","yes"],verdict:"武器になる",tone:"good",note:"「いつもの」が通じる安心感。覚える努力は誰でもできるが、積み重ねた年月は、すぐには真似できない。"},{name:"商店街の角という立地",emoji:"\uD83D\uDCCD",marks:["yes","no","no","yes"],verdict:"みんなと同じ（差にならない）",tone:"mid",note:"人通りの良さは大事。でも、近所の店も、ほぼ同じ条件にある。"},{name:"火力の強い厨房設備",emoji:"\uD83D\uDD25",marks:["yes","no","no","yes"],verdict:"みんなと同じ（差にならない）",tone:"mid",note:"料理には欠かせない。でも、お金を出せば誰でも手に入る。"},{name:"【候補】新しい高性能オーブン（100万円）",emoji:"\uD83C\uDD95",marks:["yes","maybe","no","yes"],verdict:"一時的な優位どまり",tone:"bad",note:"いまは近所の店にないかもしれないが、お金さえあれば誰でも買える。チェーンは、もっと安く、何台でも入れられる。"}]},{type:"callout",tone:"point",title:"結果の読み方",text:"6つのうち、武器になりそうなのは**「腕」「源さんとの関係」「常連さんの記憶」**の三つ。どれも、時間をかけて育った、見えにくい資源です。立地と設備は「必要だけれど、差にならない」もの。買える新しいオーブンは、**お金をかけても、武器にはなりにくい**ものでした。"},{type:"callout",tone:"warn",title:"武器にも、弱点がある",text:"いちばん強い武器にも、「組織」の△がついています。大将ひとりに頼る、源さん一軒に頼る。**強い武器ほど、「頼りすぎ」が最大のリスク**になります。ここを直すのが、次の仕事です。"},{type:"nana",mood:"think",text:"「武器と弱点は、表裏一体」。判定して終わりではなくて、△や\xd7をどう育てるかまで考えるのが、本当の使い方よ。"}]},{kind:"explain",id:"s5-inimitable",eyebrow:"核心⑤ ／ 真似されにくさの正体",title:"「真似されにくさ」は、どこから生まれる？",blocks:[{type:"p",text:"4つの問いのうち、競争優位が「続くかどうか」を決めるのは、三つ目の[[inimitability|模倣困難性]]です。ライバルが追いかけてきても、簡単には追いつけない。その理由は、主に三つあります。"},{type:"list",style:"number",title:"真似されにくくなる、三つの理由",items:["**時間がかかる**：三十年の腕、二十年の付き合いは、お金を払っても早送りできない","**何が効いているのか、外から分かりにくい**：煮物の旨さは、出汁・火加減・仕込みの順番・魚の鮮度が重なってできている。レシピだけ盗んでも、同じ味にならない","**人と人との信頼に根ざしている**：源さんや常連さんとの関係は、人間関係そのもの。契約書や設備のように、コピーできない"]},{type:"callout",tone:"example",title:"第3章の「活動システム」ともつながっている",text:"第3章で見たとおり、一つの活動は真似できても、**活動が輪になった全体**は真似しにくい。これは、上の二つ目の理由と同じ構造です。資源の「つながり」もまた、真似されにくさの源になります。"},{type:"compare",left:{label:"買える資源",emoji:"\uD83D\uDED2",items:["高性能な設備","立派な内装","広告で得る知名度","人材の一時的な採用"],note:"ライバルも、買って追いつける"},right:{label:"育つ資源",emoji:"\uD83C\uDF33",items:["長年かけた技と経験","取引先との信頼関係","お客さんの記憶と愛着","活動のつながり（輪）"],note:"ライバルは、時間がないと追いつけない"}},{type:"callout",tone:"warn",title:"武器も、古くなる",text:"いまは武器でも、環境が変われば、価値（V）が薄れることがあります。たとえば、昼に歩く会社員が減れば、常連さんの記憶も、活かせる場面が減ります。**武器は、一度見つけて終わりではなく、定期的に点検するもの**です。"},{type:"nana",mood:"smile",text:"「育つ資源」を持っている店は、焦らなくていいの。でも、育て続けないと、いつか「ただの思い出」になってしまうのよ。"}]},{kind:"explain",id:"s5-core",eyebrow:"核心⑥ ／ 武器を束ねる",title:"武器が束なって、「核」になる",blocks:[{type:"p",text:"料理人の「出汁の技」は、煮物にも、汁物にも、炊き込みごはんにも使われます。一つの核となる力から、いろいろな料理が生まれる。このように、複数の資源や活動が束なった**会社の中心的な強み**を、[[core-competence|コアコンピタンス]]と呼びます。"},{type:"formula",parts:[{label:"源さんとの関係",sub:"朝いちばんの魚"},{label:"煮物の腕",sub:"その日の手仕込み"},{label:"常連さんの記憶",sub:"「いつもの」が通じる"},{label:"ひだまり亭の核",sub:"新鮮な魚を、手仕込みで、一人ずつ"}],ops:["＋","＋","＝"],caption:"三つの武器が束なって、「ここでなければ」という、ひだまり亭の核になっています。"},{type:"callout",tone:"point",title:"外の戦場と、内の核を、合わせる",text:"第4章で、ひだまり亭は「集中\xd7差別化」で戦うと整理しました。その勝ち方を**内側から支えているのが、この核**です。外（戦場・勝ち方）と内（武器・核）が噛み合っているから、筋が通っています。"},{type:"callout",tone:"why",title:"核から離れすぎない",text:"新しい分野に広げるとき、**核が使えるか**を確かめましょう。たとえば、弁当を始めても、「新鮮な魚を、手仕込みで、一人ずつ」という核は活きません。第3章の「やらないこと」を決める基準としても、核は頼りになります。"},{type:"list",style:"check",title:"武器の点検リスト",items:["持っているものを、見えにくい資源まで、全部書き出したか","VRIOの4つの問いに、順番に当てはめたか","「いいえ」が出た場所を、弱点として把握しているか","その弱点を、育てる（直す）手は打てているか","武器は、外の戦場（第4章）と合っているか"]},{type:"nana",mood:"proud",text:"戦場は読めた。武器も分かった。ここまでで、材料は全部そろったわ。最後は、それを**一本の戦略ストーリー**に束ねる番よ。"}]},{kind:"terms",id:"s5-terms",title:"武器に、名前をつけよう",intro:[{who:"nana",mood:"smile",text:"今日の旅で、名前のついた言葉が出てきたわね。大事な5つを、カードで確かめましょう。"},{who:"you",mood:"think",text:"「VRIO」は、4つの問いの頭文字でしたよね。V・R・I・O…順番に言えます！"},{who:"nana",mood:"proud",text:"上出来。「経営資源」は、ひだまり亭の棚卸しに戻ると思い出せるわ。第3章の「活動システム」や、第4章の「差別化」「集中」と、つなげて覚えてみてね。"}],terms:["rbv","resources","vrio","inimitability","core-competence"]},{kind:"choice",id:"s5-practice",title:"ひだまり亭の武器を見極めて、使い方を決めよう",intro:"午後四時。大将が、メモを握りしめて言いました。「六つの資源は、仕分けられた。…{san}、この結果をふまえて、何に力を入れるか、一緒に決めてくれないか。使えるお金は、百万円までだ」。",notes:["大将の煮物は、三十年かけて磨いた手仕込み。常連さんは「他では代わりがきかない」と言う。ただし、仕込みは、ほぼ大将ひとりが担っている。","源さんとは二十年の付き合いで、朝いちばんの良い魚が回ってくる。同じ質の魚を出す店は、いまのところ見つかっていない。","店は商店街の角。人通りは良いが、近所の同業も、ほぼ同じ立地にある。","厨房の設備は、ごく普通のガスコンロと冷蔵庫。お金を出せば、誰でも買える。","最新の高性能オーブン（100万円）は、チェーンも近所の店も、買おうと思えば買える。"],nanaIntro:"今回も、正解を当てるクイズじゃないわ。**「武器の候補」→「VRIOの判定」→「使い方」**が、「だから」でつながるかを見てね。最初の「候補」は、観察メモの事実と合っているかも大事よ。",steps:[{id:"pick",nodeLabel:"武器の候補",title:"ステップ1 ── どれを、武器の中心に据える？",question:"観察メモをもとに、どれを、ひだまり亭の武器の中心にしますか？",options:[{id:"place",emoji:"\uD83D\uDCCD",label:"商店街の角という立地と、使い慣れた厨房設備",short:"立地と設備",start:"ok",reaction:"安定した資源に目が向くのは、自然なことね。ただ、観察メモを見て。**近所の店も、ほぼ同じ立地・同じ設備**を持っているわ。このまま進めて、VRIOの判定を見てみましょう。"},{id:"skill",emoji:"\uD83C\uDF72",label:"煮物の腕・源さんとの付き合い・常連さんの記憶（時間をかけて育った、見えにくい資源）",short:"腕・関係・記憶",start:"good",reaction:"いい着眼点ね。観察メモの事実——三十年の腕、二十年の付き合い、代わりのきかなさ——と、ぴったり重なっているわ。ここから、VRIOで確かめていきましょう。"},{id:"equip",emoji:"\uD83C\uDD95",label:"100万円の高性能オーブンなど、お金で買える最新の設備",short:"最新の設備",start:"weak",reaction:"新しい設備に期待が集まる気持ちは分かるわ。でも、**買える武器は、相手も買える**のよ。このまま進めて、何が起きるか見てみましょう。"}]},{id:"judge",nodeLabel:"VRIOの判定",title:"ステップ2 ── VRIOで、どう判定する？",question:"選んだ候補を、4つの問いで判定します。どれが、いちばん筋の通った判定でしょう？",options:[{id:"judge-equip",emoji:"\uD83D\uDED2",label:"お金で買えるので、近いうちに真似される。武器としては、一時的な優位どまり",short:"買えるので、一時的な優位どまり",requires:["equip"],reaction:"「最新の設備」という候補と、つながったわ。買える武器は、相手も買える。VRIOの「真似されにくさ」で止まる、という判定ね。",mismatchReaction:"判定そのものは筋が通っているけれど、前の候補と噛み合っていないわ。どの資源を判定しているのか、確認してみて。"},{id:"judge-place",emoji:"\uD83C\uDFEA",label:"価値はあるが、近所の店も持っているので、差にならない。均衡にとどまる",short:"みんな持っているので、差にならない",requires:["place"],reaction:"「立地と設備」という候補と、つながったわ。VRIOの「希少性」で止まる、という判定ね。必要だけれど、差にはならないわ。",mismatchReaction:"判定そのものは筋が通っているけれど、前の候補と噛み合っていないわ。どの資源を判定しているのか、確認してみて。"},{id:"judge-skill",emoji:"\uD83D\uDD0E",label:"価値・希少・真似されにくさは満たす。ただし、大将ひとりと源さん一軒に頼っていて、組織の面が弱い",short:"3つは合格。組織の面が弱い",requires:["skill"],reaction:"「腕・関係・記憶」という候補と、つながったわ。**3つの問いに「はい」と言えたうえで、弱点（頼りすぎ）まで見つけられている**のが、いい判定よ。",mismatchReaction:"判定そのものは筋が通っているけれど、前の候補と噛み合っていないわ。どの資源を判定しているのか、確認してみて。"}]},{id:"use",nodeLabel:"使い方",title:"ステップ3 ── 武器を、どう活かす？",question:"最後は、判定を受けた、お金と力の使い方です。第3章の「活動のつながり」も思い出してね。",options:[{id:"rely",emoji:"\uD83C\uDFE0",label:"立地の良さに任せて、これまで通りの営業を続ける",short:"立地に頼って、現状維持",requires:["place","judge-place"],reaction:"「みんなと同じ武器」に頼る、という筋ね。ここまで、一貫しているわ。結末で、確かめましょう。",mismatchReaction:"現状維持も、選択肢の一つ。でも、これまでの判定と「だから」でつながっていないわ。"},{id:"buy",emoji:"\uD83D\uDCB8",label:"百万円で最新のオーブンを買い、チェーンに負けない設備を整える",short:"最新オーブンを買う",requires:["equip","judge-equip"],reaction:"ここまで、一貫しているわね。でも、買える武器にお金をかけた先に何が起きるか…結末で確かめましょう。",mismatchReaction:"設備投資は、時に必要。でも、これまでの判定と「だから」でつながっていないわ。何のための投資か、説明できるかしら。"},{id:"grow",emoji:"\uD83C\uDF31",label:"仕込みの工程を書き出して、若い人と分担し、技を店の仕組みにする。源さんとの関係は守りつつ、第2の仕入先も育てる",short:"技を仕組みに。仕入先も分散",requires:["skill","judge-skill"],reaction:"来たわね！ **弱点（頼りすぎ）を、育てて直す**使い方よ。見えにくい資源を、組織の力に変える。第4章の「売り手の力」への手当てにもなっているわ。",mismatchReaction:"武器を育てるのは、素晴らしい使い方。でも、前の候補・判定に噛み合っていないと、何を育てたいのか、狙いがぼやけてしまうわ。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"見えにくい武器を、仕組みに変えた",quality:1,when:{firstPick:["skill"],matches:[2]},narration:"半年後。ひだまり亭には、大将と一緒に仕込みを担う若い料理人が、一人増えました。仕込みの工程は手順書になり、第2の仕入先との取引も始まりました。源さんの値上げにも、冷静に向き合えます。大将は言います。「俺ひとりの腕が、店の腕になったな。百万円は、オーブンじゃなくて、人と仕組みに使ったよ」。",nana:"いい武器の見極めと、活かし方ね。**候補を選ぶ → VRIOで判定する → 弱点を育てる**。第4章の戦場の読みとも、ちゃんと噛み合っているわ。外（戦場）と、内（武器）が、そろったわね。さあ、材料は全部そろったわ。最後の第6章で、全部を一本の戦略ストーリーに束ねましょう。"},{id:"linked-equip",emoji:"\uD83D\uDCB8",title:"筋は通ったけれど、買える武器に投資した",quality:.5,when:{firstPick:["equip"],matches:[2]},narration:"最新のオーブンを入れて、焼き魚は速く、きれいに仕上がるようになりました。ところが、半年もしないうちに、チェーンも、近所の定食屋も、同じような設備を入れました。差はあっという間に縮まり、百万円をかけた強みは、ほとんど手元に残りませんでした。",nana:"進め方は、「だから」でつながっていたわ。でも、**買える武器は、相手も買える**の。お金のかけどころを、見えにくい資源に向けられたら、結果は違ったはずよ。もう一度、候補から考えてみて。"},{id:"linked-place",emoji:"\uD83C\uDFE0",title:"ありふれたものに、頼ってしまった",quality:.4,when:{firstPick:["place"],matches:[2]},narration:"立地と設備に頼って、これまで通り営業を続けました。チェーンが開店すると、「角の立地」の強みは、そっくり向こうにも当てはまりました。大将の煮物の腕は、大将ひとりの中に眠ったままで、差を生み出せませんでした。",nana:"一貫してはいたけれど、**差にならないものを、武器と思い込んでしまった**わね。本当の武器は、足元にあったのに。見えにくい資源にも、目を向けてみて。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、判定と使い方が噛み合わなくなった",quality:.4,when:{matches:[1]},narration:"最初の見立ては悪くなかったのですが、途中で選んだ判定や使い方が、候補と噛み合わなくなりました。何を武器として育てたいのか、現場にも伝わりません。",nana:"途中で、「それは、選んだ武器の話？」が抜けてしまったわね。**候補・判定・使い方は、三つで一組**。もう一度、つなげて考えてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"候補も、判定も、使い方もバラバラだった",quality:.1,narration:"武器の候補も、VRIOの判定も、お金の使い方も、それぞれ別の方向を向いていました。気づけば、何を武器として磨いているのか、大将にも、分からなくなっていました。",nana:"一つひとつは悪くなくても、つながっていないと、武器は育たないの。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"quiz",id:"s5-quiz",title:"確認クイズ",intro:"武器の見極め方を確かめましょう。「なぜ？」の解説まで読むのが、いちばんの復習よ。",questions:[{id:"q1",scenario:"ひだまり亭も、近所の定食屋も、ごく普通のガスコンロと冷蔵庫を使っています。",question:"この設備を、[[vrio|VRIO]]の4つの問いで見ると、どう判定できるでしょう？",options:[{text:"価値も希少性もあり、持続的な競争優位になる",feedback:"どの店も持っている設備は、「希少」とは言えないわ。希少性の問いで、「いいえ」が出てしまうの。"},{text:"価値がないので、競争劣位",feedback:"料理には欠かせない設備だから、価値はあるわ。問題は、価値の有無ではなく、「他の店も持っている」ことよ。"},{text:"価値も希少性もあるが、真似されやすいので、一時的な優位",feedback:"希少性の段階で、すでに「いいえ」が出ているわ。「一時的な優位」は、珍しいけれど真似されやすい場合の結論よ。"},{text:"価値はあるが、みんな持っているので希少ではなく、差にならない（競争均衡）",feedback:"その通り！ 必要だけれど、差にはならない。これが「競争均衡」よ。どの店も持っているものは、武器ではなく、土俵に立つための条件なの。"}],answer:3,explanation:"価値（V）はあっても、ライバルも持っているなら希少性（R）で止まり、**競争均衡**にとどまります。立地や基本的な設備のように、「ないと困るが、あっても差にならない」資源は、たくさんあります。"},{id:"q2",scenario:"ある会社が、他社が一年あれば真似できる新機能で、一時的に売上を伸ばしました。",question:"VRIOの視点では、どの問いで「いいえ」が出て、どんな結論になるでしょう？",options:[{text:"真似されにくさ（I）が「いいえ」で、一時的な競争優位にとどまる",feedback:"正解！ いまは他社にないが、真似されやすい。だから、優位は一時的。「続くかどうか」を決めるのは、真似されにくさよ。"},{text:"価値（V）が「いいえ」で、競争劣位",feedback:"売上が伸びたのだから、お客さんは価値を感じているわ。価値の問いは、「はい」よ。"},{text:"組織（O）が「いいえ」で、宝の持ち腐れ",feedback:"売上を伸ばせているので、活かせてはいるわ。今回の問題は、「一年で追いつかれる」ことよ。"},{text:"希少性（R）が「いいえ」で、競争均衡",feedback:"いまは他社が持っていないので、希少性は「はい」よ。問題は、そのあと、すぐ追いつかれる点なの。"}],answer:0,explanation:"珍しくても（R）、真似されやすければ（I）、優位は長続きしません。**競争優位が「続くかどうか」は、模倣困難性で決まる**、というのが、VRIOの大事な読み方です。"},{id:"q3",scenario:"大将の煮物の腕は、価値も希少性も真似されにくさもあります。ただ、仕込みの多くを大将ひとりが担い、休むと店が回りません。",question:"VRIOの4つ目の問い（組織）の観点で、いちばん近い説明はどれでしょう？",options:[{text:"腕があれば、組織の面は問題にならない",feedback:"腕があっても、それが一人に閉じていたら、店の力としては使いきれないわ。Oの問いは、そこを見ているの。"},{text:"大将ひとりに頼るのは、むしろ強みなので、直す必要はない",feedback:"頼りきりは、休めない、体を壊したら止まる、というリスクでもあるの。強みの裏返しの弱点として、見ておく必要があるわ。"},{text:"せっかくの武器を、店の仕組みとして活かしきれておらず、手順書や分担で、組織の力にする必要がある",feedback:"その通り！ 武器を持っていても、組織として使いこなせなければ「宝の持ち腐れ」。仕組みにして、はじめて長く続く優位になるのよ。"},{text:"腕には、価値がないので、武器とは呼べない",feedback:"常連さんが通う理由になっているのだから、価値はあるわ。問題は価値ではなく、「活かし方」よ。"}],answer:2,explanation:"VRIOの最後の問い（O）は、**持っている武器を、組織として活かせているか**。「いいえ」が出たら、そこが育てるべき場所です。第3章の[[activity-system|活動システム]]のように、仕組みとしてつなげることが、武器を長持ちさせます。"}]},{kind:"summary",id:"s5-summary",title:"今日の学びを、一枚に",points:[{title:"競争優位は、内側からも生まれる",text:"外（立ち位置・戦場）だけでなく、内側の資源から考えるのが[[rbv]]です。外と内が合ったとき、戦略に筋が通ります。"},{title:"まず、持っているものを全部並べる",text:"見える資源（設備・場所）と、見えにくい資源（腕・信頼・記憶）。差をつくるのは、たいてい後者の[[resources]]です。"},{title:"「ある」と「効く」は別。4つの問いで見極める",text:"[[vrio]]は、価値・希少性・真似されにくさ・組織の4つ。全部「はい」なら本物の武器。「いいえ」が出た場所は、弱点です。"},{title:"続くかどうかは、真似されにくさで決まる",text:"時間がかかる、何が効いているか分かりにくい、信頼に根ざす。この三つが、[[inimitability]]の源です。買える資源は、相手も買えます。"},{title:"武器が束なって、核になる",text:"複数の資源と活動が束なったものが[[core-competence]]。新しいことを始めるときは、「核が使えるか」を確かめます。"}],why:{title:"なぜ、これが大事なのか",text:"他社の真似や、流行の設備に飛びつきたくなる気持ちは、誰にでもあります。でも、**差をつくるのは、足元に育ってきた、見えにくい資源**であることが多い。それを見極め、弱点まで育てる力があれば、お金を使う場所を間違えません。**「あるもの」と「効くもの」を分ける目**が、無駄な投資を防ぎます。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま。今日は、自分の手の中の武器を、確かめる旅だったわね。"},{who:"you",mood:"smile",text:"はい。大将の煮物は、疑いようのない武器だと思っていましたが、「組織」の問いで、頼りすぎという弱点も見つかって、驚きました。"},{who:"nana",mood:"smile",text:"強い武器ほど、弱点も見えやすいの。それに気づけたことが、いちばんの収穫よ。第3章の「真似されにくさ」とも、つながったでしょう？"}]}],clear:{perspective:{icon:"\uD83D\uDDE1️",name:"強みを見極める目",tagline:"「あるもの」と「効くもの」を分ける",description:"持っているものの中から、本当に競争優位になる武器を見極められるようになりました。「うちの強みは…」と聞いたら、「それは、お金で買えるもの？ ライバルも持っているもの？」と、そっと確かめてみてください。",checks:["それは、価値がある？ 珍しい？","真似されにくい？（買える？ 時間がかかる？）","組織として、使いこなせている？"]},nana:[{who:"nana",mood:"smile",text:"おめでとう、{san}。第5の視点「強みを見極める目」を手に入れたわね。誰かの「うちの強みは…」を聞いたら、ぜひ4つの問いで確かめてみて。"},{who:"you",mood:"smile",text:"はい！ 「ある」と「効く」を分けて考えるクセ、ついてきました。"},{who:"nana",mood:"proud",text:"これで、材料は全部そろったわ。物語、地図、立ち位置、戦場、武器。最後は、それを一本の戦略ストーリーに束ねるわよ。"}],teaser:"次の章：戦略を組み立てる ─ すべての視点を、ひとつの戦略ストーリーに束ねます。ここまでに手に入れた五つの視点を、ひだまり亭の戦略にまとめ上げます。"}},{id:6,title:"戦略を組み立てる",subtitle:"策定プロセス",theme:"戦略策定のプロセス",icon:"\uD83E\uDDE9",accent:"#8bd86a",blurb:"ここまでの視点を、一本の筋にまとめ上げる章です。ありたい姿から、分析、選択肢づくり、選ぶ、実行、見直しまで。外（第4章）と内（第5章）をSWOTで一枚にし、最後は第1章の「物語」に戻って、自分の手で戦略ストーリーを組み立てます。",goals:["戦略策定の流れ（ありたい姿→分析→選択肢→選ぶ→実行→見直し）を説明できる","五つの力・VRIO・ポジショニングを、順番に使い分けられる","分析の結果を、「だから」でつながる一本の物語にまとめられる"],minutes:32,termKeys:["strategy-process","environment-analysis","swot","vision","strategy-story"],termPreview:["戦略策定プロセス","環境分析","SWOT分析","ビジョン","戦略ストーリー（再訪）"],status:"ready",scenes:[{kind:"story",id:"s6-journey",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"六日目 午前10:00",lines:[{who:"narrator",text:"六日目の朝。仕込みを終えたひだまり亭の壁には、あのバラバラなチラシが、まだ貼られたままだった。その横の席には、{san}のノートが何冊も積み上がっている。"},{who:"taisho",mood:"worry",text:"いやあ、ここ数日で、ずいぶん勉強させてもらったがな。五つの力に、VRIOに、ポジションに…頭の中が、道具箱をひっくり返したみたいだ。結局、どれから手をつけりゃいいんだ？"},{who:"you",mood:"think",text:"実は、私も同じです。一つひとつは分かったつもりなんですが、「全部使って、結局どうするの？」と聞かれたら、答えられる気がしません。"},{who:"nana",mood:"smile",text:"いい気づきよ。それは、**部品は揃ったけれど、組み立て図がまだ**という状態なの。"},{who:"nana",text:"旅行を思い浮かべてみて。パスポートも、地図も、天気予報も、財布もある。でも、「どこへ行って、何日かけて、どの順に回るか」が決まっていなければ、旅には出られないでしょう？"},{who:"taisho",mood:"think",text:"そりゃ、行き先が決まってなきゃ、地図を開いたって意味がねえな。"},{who:"nana",mood:"proud",text:"そう。戦略づくりも、同じよ。**行き先を決め、天気と体力を確かめ、道を何本か出して、一本選び、出発して、途中で直す**。この順番が、「戦略の組み立て方」なの。"},{who:"you",mood:"surprise",text:"戦略にも、組み立ての順番があるんですね。てっきり、ひらめきで決めるものだと思っていました。"},{who:"nana",mood:"smile",text:"ひらめきも大事よ。でも、**ひらめきを、順番の中に置いてあげる**の。今日は、その順番と、第4章・第5章の分析を一枚にまとめる道具を覚えましょう。"},{who:"nana",text:"そして最後に、壁のそのチラシの「バラバラ」を、**一本の物語**に変えるわよ。"},{who:"taisho",mood:"smile",text:"壁のチラシが、一本の筋になるってのか。そいつは楽しみだ。"}]},{kind:"explain",id:"s6-process",eyebrow:"戦略づくりの順番",title:"戦略は、旅の計画のように組み立てる",blocks:[{type:"p",text:"旅行の計画を立てるとき、私たちはほとんど無意識に、ある順番を踏んでいます。行き先を決め、天気と体力を確かめ、行ける道を何本か出して、一本に決めて、出発して、途中で道を直す。戦略づくりも、まったく同じ形をしています。これを[[strategy-process|戦略策定プロセス]]と呼びます。"},{type:"chain",title:"旅の計画の順番 ＝ 戦略の順番",nodes:[{label:"① ありたい姿を描く（行き先を決める）",emoji:"\uD83C\uDFC1"},{label:"② 分析する（天気と体力を確かめる）",emoji:"\uD83D\uDD0D",linkLabel:"次に"},{label:"③ 選択肢を出す（行ける道を何本か出す）",emoji:"\uD83D\uDEE4️",linkLabel:"次に"},{label:"④ 選ぶ（一本に決める。やらないことも決める）",emoji:"✅",linkLabel:"次に"},{label:"⑤ 実行する（出発する）",emoji:"\uD83D\uDEB6",linkLabel:"次に"},{label:"⑥ 見直す（途中で道を直す）",emoji:"\uD83D\uDD04",tone:"goal",linkLabel:"次に"}],caption:"⑥のあとは、また①や②に戻ります。ぐるぐる回しながら、精度を上げていきます。"},{type:"callout",tone:"point",title:"六つは、一方通行ではありません",text:"分析してみたら、行き先が遠すぎた。見直してみたら、前提が変わっていた。そんなときは、前の段階に戻って構いません。**行きつ戻りつしながら、ぐるぐる回す**のが、戦略づくりの普通の姿です。"},{type:"p",text:"この順番を飛ばすと、失敗の形が、だいたい決まっています。"},{type:"compare",left:{label:"いきなり打ち手から（思いつき型）",emoji:"\uD83D\uDCA1",items:["「流行っているから」で新メニューを足す","「隣がやっているから」で値下げする","理由は、あとから探す"],note:"第1章の壁のチラシは、これでした"},right:{label:"分析ばかり（動けない型）",emoji:"\uD83D\uDCDA",items:["資料だけが分厚くなる","調べるほど、決められなくなる","実行の前に、時間切れ"],note:"分析は、選ぶための材料です"},caption:"どちらも、六つのうちの一部だけを回している状態です。"},{type:"list",style:"bullet",title:"これまでの章は、どこで使う？",items:["**ありたい姿** … 今日の新しい道具、[[vision|ビジョン]]","**分析する** … 第4章の[[five-forces|五つの力]]（外）と、第5章の[[vrio|VRIO]]（内）","**選択肢を出す・選ぶ** … 第3章の[[positioning|ポジション]]と、「やらないこと」","**全体をつなぐ筋書き** … 第1章の[[strategy-story|戦略ストーリー]]"]},{type:"nana",mood:"smile",text:"大事なのは、道具の名前を覚えることじゃなくて、「**いま、どの段階か**」を言えること。「いまは分析の段階」「いまは選ぶ段階」と言えれば、道具箱の前で迷子にならないわ。"}]},{kind:"explain",id:"s6-swot",eyebrow:"外と内を、一枚に",title:"環境分析とSWOT ── 天気と体力を、並べて見る",blocks:[{type:"p",text:"山に登る前に、何を確かめますか。天気予報と、道の状態。そして、自分の体力と、装備です。どちらか片方だけでは、「今日は登っていい日か」を決められません。"},{type:"compare",left:{label:"外（自分では変えられない）",emoji:"\uD83C\uDF24️",items:["天気・気温","道の混み具合","山小屋の営業日"],note:"第4章で見た「戦場」にあたります"},right:{label:"内（自分で変えられる）",emoji:"\uD83C\uDF92",items:["体力・足の状態","靴と防寒具","地図とコンパス"],note:"第5章で見た「武器」にあたります"},caption:"山登りの前に確かめることも、戦略の前に確かめることも、外と内の両方です。"},{type:"p",text:"このように、外と内の両方を調べることを、[[environment-analysis|環境分析]]と呼びます。外と内には、それぞれ「プラスに働くもの」と「マイナスに働くもの」があります。この2\xd72を一枚にまとめた表が、[[swot|SWOT]]です。"},{type:"quad",title:"SWOT ── 外と内を、一枚に",rows:["内側（自分たちで変えられる）… 第5章の「武器の棚卸し」から","外側（自分たちでは変えられない）… 第4章の「戦場の読み」から"],cols:["プラスに働く","マイナスに働く"],cells:[{tag:"S",name:"強み",from:"Strengths",tone:"sea",items:["お客さんに選ばれる理由になるもの","VRIOで、武器と判定できたもの"]},{tag:"W",name:"弱み",from:"Weaknesses",tone:"coral",items:["足を引っ張っているもの","VRIOで、組織や真似されにくさが弱かったもの"]},{tag:"O",name:"機会",from:"Opportunities",tone:"lantern",items:["追い風になる、外の変化や需要","五つの力で、「力が弱い」ところ"]},{tag:"T",name:"脅威",from:"Threats",tone:"sky",items:["向かい風になる、外の変化や相手","五つの力で、「力が強い」ところ"]}],caption:"頭文字をつなぐと S・W・O・T。第4章と第5章の結果が、ここで一枚になります。"},{type:"callout",tone:"point",title:"分け方に迷ったら",text:"「**自分たちで変えられる？**」と聞いてみてください。変えられるなら内（強み・弱み）、変えられないなら外（機会・脅威）です。たとえば、「仕入先が一か所に偏っている」は、自分たちで直せるので弱み。「仕入先が値上げしてくる」は、自分たちでは決められないので脅威です。"},{type:"callout",tone:"warn",title:"並べて終わり、にしない",text:"SWOTは、書いただけでは何も決まりません。四つの枠が埋まって満足すると、**模造紙が一枚増えただけ**になります。大事なのは、「だから、どうする？」を考えるところまで。このあと、ひだまり亭の分析で、その続きをやります。"},{type:"nana",mood:"smile",text:"「プラスは強みと機会で、マイナスは弱みと脅威」と暗記するより、「**内か外か**」「**プラスかマイナスか**」の二つの質問で置き場所を決めるほうが、迷わないわ。"}]},{kind:"story",id:"s6-sticky",place:"商店街〈ひだまり通り〉 ─ ひだまり亭のカウンター",time:"午後2:30",lines:[{who:"narrator",text:"昼の営業が終わった店内。カウンターには、四色の付箋と大きな模造紙が広げられている。真ん中には、十字の線が一本ずつ。"},{who:"nana",mood:"smile",text:"さあ、第4章と第5章で見つけたことを、四つの枠に貼っていくわよ。まずは内側。**自分たちで変えられること**から。"},{who:"you",mood:"think",text:"強みは…大将の煮物と焼き魚の腕。常連さんの顔と好みの記憶。それに、朝いちばんの魚を回してくれる、源さんとの付き合いですね。VRIOで「武器」と判定したものです。"},{who:"taisho",mood:"worry",text:"弱みは…聞きたくねえが、俺ひとりに頼りすぎなこと。仕入先が源さん一か所に偏ってること。それと、席が12席しかねえこと、だな。"},{who:"nana",mood:"proud",text:"よく言えたわね、大将。弱みを自分の口で言えるのは、強さよ。次は外側。**自分たちでは変えられないこと**。"},{who:"you",mood:"normal",text:"機会は、昼の12時台に店の前を歩く会社員が多いこと。近所の定食屋が、昼をほとんど閉めていること。脅威は、来月開店のまんぷく弁当と、コンビニの惣菜や弁当です。"},{who:"taisho",mood:"think",text:"ちょいと待ってくれ。源さんの値上げの話は、どこに貼るんだ？ 仕入先が一か所なのは、さっき弱みに貼ったが…"},{who:"nana",mood:"smile",text:"いい質問ね。「仕入先が一か所に偏っている」のは、自分たちで直せるから**弱み**。「源さんが値上げを言ってくる」のは、自分たちでは決められないから**脅威**。同じ話でも、内と外で貼る場所が違うの。"},{who:"you",mood:"smile",text:"「自分たちで変えられるか」で分ける、ということですね。"},{who:"nana",mood:"normal",text:"ええ。ただね、四つの枠が埋まって満足してしまったら、模造紙が一枚増えただけよ。大事なのは、ここから。"}]},{kind:"explain",id:"s6-cross",eyebrow:"掛け合わせて、選択肢を出す",title:"ひだまり亭のSWOTから、打ち手の候補をつくる",blocks:[{type:"p",text:"付箋で書き出したことを、一枚にまとめると、ひだまり亭の環境は、こう見えます。第4章と第5章で出した結論が、そのまま入っています。"},{type:"quad",title:"ひだまり亭のSWOT",rows:["内側（自分たちで変えられる）","外側（自分たちでは変えられない）"],cols:["プラスに働く","マイナスに働く"],cells:[{tag:"S",name:"強み",from:"第5章：VRIOで武器と判定",tone:"sea",items:["大将の煮物と焼き魚の腕","常連さんの顔と好みの記憶","源さんとの付き合い（朝いちばんの魚）"]},{tag:"W",name:"弱み",from:"第5章：組織の問いで見つかった",tone:"coral",items:["大将ひとりに頼りすぎ","仕入先が源さん一か所に偏っている","席は12席。厨房は大将とパート1名"]},{tag:"O",name:"機会",from:"第4章：力が弱い所",tone:"lantern",items:["昼12時台に歩く会社員が多い（ただし、並んでいたら諦める）","近所の定食屋は、昼をほとんど閉めている"]},{tag:"T",name:"脅威",from:"第4章：力が強い所",tone:"sky",items:["来月、まんぷく弁当が開店","コンビニの惣菜・弁当","源さんからの値上げ"]}]},{type:"callout",tone:"warn",title:"これだけでは、まだ地図です",text:"SWOTは、「いま、どこにいるか」を示す地図です。「どこへ行くか」は、まだ書かれていません。ここから、**強み・弱みと、機会・脅威を掛け合わせて**、打ち手の候補を出します。"},{type:"quad",title:"掛け合わせて、打ち手の候補をつくる",rows:["強み（S）を、どう使う？","弱み（W）を、どうする？"],cols:["機会（O）に対して","脅威（T）に対して"],cells:[{tag:"S\xd7O",name:"攻める",from:"強みで、機会をつかむ",tone:"sea",items:["煮物の腕 \xd7 昼の会社員 → 「15分で出る、出来立ての煮物定食」を磨き切る"]},{tag:"S\xd7T",name:"差別化する",from:"強みで、脅威をかわす",tone:"sky",items:["常連さんの記憶 \xd7 まんぷく弁当 → 顔と好みを覚える接客で、「ここだけ」を濃くする"]},{tag:"W\xd7O",name:"補強する",from:"弱みを直して、機会を逃さない",tone:"lantern",items:["ひとり頼み \xd7 昼の需要 → 仕込みを手順書にして、パートさんにも任せる"]},{tag:"W\xd7T",name:"守る",from:"弱みと脅威が重なる所を固める",tone:"coral",items:["一か所頼みの仕入れ \xd7 値上げ → 二か所目の仕入先を見つけて、最悪に備える"]}],caption:"四つの枠から、候補が一つずつ出ました。まだ「候補」です。全部やるわけではありません。"},{type:"nana",mood:"smile",text:"いちばん危ないのは、**弱みと脅威が重なる所（W\xd7T）**。放っておくと、一気に傾くの。「守り」は地味だけれど、先に手を打つ価値があるわ。"}]},{kind:"story",id:"s6-many",place:"商店街〈ひだまり通り〉 ─ ひだまり亭",time:"午後4:00",lines:[{who:"narrator",text:"掛け合わせの表に、打ち手の候補が並んだ。大将は、すっかり目を輝かせている。"},{who:"taisho",mood:"smile",text:"見ろよ、やれそうなことが、こんなにあるぞ！ 15分の定食に、仕込みの手順書に、仕入先を増やして…ついでに夜の居酒屋営業と、お弁当の出前と、まんぷく弁当に合わせた値下げもやったらどうだ？"},{who:"you",mood:"worry",text:"大将、それは…壁のチラシが、また増えるだけのような気が。"},{who:"nana",mood:"smile",text:"{san}、いい勘ね。大将、試しに、付箋を**「だから」の矢印**でつないでみましょう。夜の居酒屋営業は、何の「だから」？"},{who:"taisho",mood:"think",text:"…夜も稼げりゃ、儲かるから、か。"},{who:"nana",text:"それは「儲かるから」であって、ありたい姿からの「だから」ではないわ。ひだまり亭のありたい姿は、なんだったかしら。"},{who:"you",mood:"normal",text:"「昼に急ぐ会社員が、15分でほっとできる、ひだまり通りのいつもの店」です。"},{who:"nana",mood:"proud",text:"その姿と「だから」でつながる打ち手だけが、物語の一部になれるの。つながらない打ち手は、どんなに良さそうでも、今回は**やらない**に回す。第3章の「やらないことを決める」と同じよ。"},{who:"taisho",mood:"worry",text:"もったいねえな…。でも、全部やって、また壁がチラシだらけになるよりは、マシか。"},{who:"nana",mood:"smile",text:"捨てるんじゃないの。**ありたい姿が変わったら、また拾えばいい**。「保留箱」に入れておくのよ。"}]},{kind:"explain",id:"s6-story",eyebrow:"一本の物語に束ねる",title:"戦略ストーリーを、もう一度 ── 第1章への帰り道",blocks:[{type:"p",text:"選んだことを、第1章で出会った[[strategy-story|戦略ストーリー]]に束ねます。SWOTや五つの力の結果は、そのままでは「材料の山」です。材料を、「だから」の矢印、つまり[[inga-ronri|因果論理]]でつなぐと、物語になります。"},{type:"chain",title:"束ねる前 ── 第1章の、壁のチラシ",nodes:[{label:"全品50円引き",emoji:"\uD83C\uDFF7️"},{label:"メニューを60品に",emoji:"\uD83D\uDCDC",broken:!0},{label:"ポイントカード",emoji:"\uD83D\uDCB3",broken:!0},{label:"お弁当、はじめました",emoji:"\uD83C\uDF71",tone:"bad",broken:!0}],caption:"どれも悪くないのに、どれも前の一手と「だから」でつながっていません。"},{type:"chain",title:"束ねたあと ── ひだまり亭の戦略ストーリー",nodes:[{label:"ありたい姿：昼に急ぐ会社員が、15分でほっとできる、いつもの店",emoji:"\uD83C\uDFC1"},{label:"外：昼の会社員は多く、近所は昼を閉めている。でも、まんぷく弁当が来る",emoji:"\uD83D\uDD2D",linkLabel:"分析すると"},{label:"内：煮物の腕と常連さんの記憶は、真似されにくい武器。弱みは、ひとり頼り",emoji:"\uD83D\uDDE1️",linkLabel:"そして"},{label:"やること：品数を絞り、15分で出来立てを出す。手順書で、ひとり頼りをなくす",emoji:"\uD83C\uDF72",linkLabel:"だから"},{label:"やらないこと：値下げ競争・夜営業・品数を増やすこと",emoji:"\uD83D\uDEAB",linkLabel:"同時に"},{label:"見直し：昼12時台の来店数と、提供時間を、毎月確認",emoji:"\uD83D\uDD04",tone:"goal",linkLabel:"そして"}],caption:"全部の矢印に、「だから」が入ります。しかも、その根拠は、外（第4章）と内（第5章）の分析です。"},{type:"list",style:"number",title:"戦略ストーリーを、五つの文で",items:["ありたい姿は、〇〇。","外を見ると、〇〇という機会と、〇〇という脅威がある。","内には、〇〇という武器と、〇〇という弱みがある。","だから、〇〇をやり、〇〇はやらない。","〇〇で確かめ、ずれたら直す。"]},{type:"list",style:"check",title:"つながっているか、点検",items:["やることの全部に、「なぜ？」と聞かれて答えられる？","やらないことが、一つ以上決まっている？","強みを使い、弱みと脅威に手を打っている？","ありたい姿から見直しまで、「だから」で読み上げられる？"]},{type:"nana",mood:"proud",text:"第1章では、矢印に「だから」が入るかだけを見たわね。いまは、その矢印の**根拠が、外と内の分析**になっている。ここが、第1章より一段深いところよ。五つの文が言えたら、3分で人に話せるわ。"}]},{kind:"explain",id:"s6-review",eyebrow:"実行して、見直す",title:"物語は、書いて終わりではない",blocks:[{type:"p",text:"旅は、出発してからが本番です。天気は変わるし、道が通れなくなることもあります。戦略も同じで、実行を始めてから、前提が動きます。新しいライバルが来る。仕入先が値上げする。お客さんの好みが変わる。"},{type:"callout",tone:"why",title:"見直しには、「ものさし」が要る",text:"「なんとなく調子が悪い」では、どこを直せばいいか分かりません。物語の矢印ごとに、**数字や事実で確かめられる目印**を、先に決めておきます。それが、見直しの「ものさし」です。"},{type:"list",style:"bullet",title:"ひだまり亭のものさし（例）",items:["**昼12時台の来店数** … 昼の会社員に、ちゃんと届いているか","**注文から提供までの時間** … 「15分で」という約束を、守れているか","**常連さんの再来店** … 「いつもの店」になれているか","**仕入先ごとの割合** … 一か所頼みを、減らせているか"]},{type:"p",text:"目印が外れたとき、慌てて物語を全部捨てる必要はありません。直す順番があります。"},{type:"compare",left:{label:"見直しの合図",emoji:"\uD83D\uDEA8",items:["目印の数字が、続けて外れた","五つの力の誰かが、変わった（新しいライバル、値上げ）","お客さんの声が、変わった"],note:"合図は、先に決めておくほど気づけます"},right:{label:"直す順番",emoji:"\uD83D\uDD27",items:["① まず、外の前提が変わったかを確かめる","② 次に、強みが今も効いているかを確かめる","③ 最後に、やること・やらないことを入れ替える"],note:"外 → 内 → 打ち手、の順に戻ります"},caption:"変わった所から順に直せば、物語の全部を書き直さずに済みます。"},{type:"callout",tone:"warn",title:"見直しで、ものさしを甘くしない",text:"目印を外したときに、「まあ、誤差だろう」と基準を下げてしまうと、見直しの意味がなくなります。**基準は、実行する前に決めておく**のが鉄則です。"},{type:"nana",mood:"smile",text:"「やってみて、ずれたら直す」を前提にしていいの。完璧な計画をつくろうとして動けなくなるより、**まず一周まわして、二周目で磨く**ほうがずっといいわ。見直しが終わったら、また「ありたい姿」に戻るのよ。"}]},{kind:"terms",id:"s6-terms",title:"ここまでの話に、名前をつけよう",intro:[{who:"nana",mood:"smile",text:"旅の計画のたとえで話してきたことにも、ちゃんと名前があるの。今日は、新しく四つ。そして、第1章の言葉に、もう一度会ってもらうわ。"},{who:"nana",text:"「環境分析」と「SWOT」は、第4章・第5章の結果を一枚にまとめる道具。「ビジョン」は旅の行き先。そして「戦略策定プロセス」は、旅の順番そのものよ。"},{who:"you",mood:"smile",text:"最後の「戦略ストーリー」は、第1章で出会った言葉ですよね。ここで、もう一度会えるんですね。"}],terms:["strategy-process","environment-analysis","swot","vision","strategy-story"]},{kind:"choice",id:"s6-practice",title:"ひだまり亭の戦略ストーリーを、一本に束ねよう",intro:"六日目の夕方。ホワイトボードには、ここまでの分析が並んでいます。大将が言いました。「まんぷく弁当の開店まで、あと少しだ。うちの戦略を、決めよう」。ここからは{san}の番です。",notes:["強み：大将の煮物と焼き魚の腕、常連さんの記憶、源さんとの付き合い（第5章で武器と判定）","弱み：大将ひとりに頼りすぎ。仕入先は源さん一か所。席は12席で、厨房は大将とパート1名","機会：平日の昼12時台に、店の前を歩く会社員が多い。近所の定食屋は、昼をほとんど閉めている","脅威：来月、まんぷく弁当が開店。駅前のコンビニの惣菜・弁当。源さんからの値上げ","夜と週末は、商店街の人通りが少ない","第3章のおさらい：何かを足すときは、何をやめるかも一緒に決める"],nanaIntro:"分析は、もう済んでいるわ。今日の問いは、**その分析から、一本の物語を組み立てられるか**。ありたい姿 → 勝ち筋 → 備えと見直し。前の一手と「だから」でつながるほど、矢印が光るわよ。",steps:[{id:"vision",nodeLabel:"ありたい姿",title:"ステップ1 ── どんな店でありたい？",question:"物語の出発点（行き先）です。分析の結果と重ね合わせて、三年後のひだまり亭の姿を決めましょう。",options:[{id:"daily",emoji:"\uD83C\uDF72",label:"昼に急ぐ会社員が、15分でほっとできる、ひだまり通りの「いつもの店」",short:"昼の会社員の いつもの店",start:"good",reaction:"いい行き先ね。強み（煮物の腕・常連さん）と、機会（昼の会社員）が、ちゃんと重なっているわ。しかも、第1章からぶれていない。ここから、「だから」でつなげていけるかが勝負よ。"},{id:"giant",emoji:"\uD83C\uDFE2",label:"まんぷく弁当に負けない、店舗数と規模を持つ、地域一番の店",short:"規模で地域一番",start:"ok",reaction:"大きな夢ね。ただ、**分析と重なっているか**を見てみて。規模は、資金も仕入れ力も桁違いの相手が得意な土俵よ。12席・大将ひとりの店には、遠い行き先かもしれないわ。このまま組み立てて、結果を見てみましょう。"},{id:"allday",emoji:"\uD83C\uDF19",label:"昼も夜も週末も、誰でも、いつでも来られる、商店街の万能食堂",short:"いつでも誰でもの万能食堂",start:"weak",reaction:"「みんなに」は聞こえがいいけれど、**誰にも刺さらない**に近づくわ。夜と週末は人通りが少ないし、手も足りない。壁のチラシと、同じ匂いがするわね。このまま進めてみましょう。"}]},{id:"bet",nodeLabel:"勝ち筋",title:"ステップ2 ── どこに力を集める？ 何をやらない？",question:"SWOTを掛け合わせて出た候補から、一本に絞ります。ステップ1の「ありたい姿」と、「だから」でつながる勝ち筋はどれでしょう？ 選ぶことは、**やらないことを決める**ことでもあります。",options:[{id:"core",emoji:"\uD83C\uDFAF",label:"煮物の腕 \xd7 昼の需要に集中。品数は絞って、15分で出来立てを出す。夜営業と値下げは、やらない",short:"15分の煮物定食に集中",detail:"強み\xd7機会（攻め）＋やらないことを決める",requires:["daily"],reaction:"つながったわ！ 「いつもの店」という行き先を、強み（煮物の腕）と機会（昼の会社員）の**掛け合わせ**が支えている。しかも、「やらないこと」まで決めてあるから、物語の輪郭がくっきりしたわね。",mismatchReaction:"この一手そのものは、いい勘をしているの。でも、ステップ1の行き先と「だから」でつながらないわ。「なぜ、それをやるの？」と聞かれて、行き先から説明できるかしら。"},{id:"scale",emoji:"\uD83C\uDFD7️",label:"テイクアウト専門の2号店を出し、同じ味を量で広げる",short:"2号店で量を広げる",detail:"規模を取りに行く",requires:["giant"],reaction:"「規模で地域一番」という行き先には、筋が通っているわ。ただし、煮物の腕は大将ひとり。味を薄めずに量を広げる手立ては、あるかしら。",mismatchReaction:"2号店という打ち手が、行き先と噛み合わないわ。大将ひとりの腕と、12席の店は、そのまま広がるわけではないの。"},{id:"wide",emoji:"\uD83C\uDF7D️",label:"夜営業と週末ランチを足し、メニューも増やして、幅広く受け止める",short:"夜も週末も、品数も増やす",detail:"足せるだけ足す",requires:["allday"],reaction:"「いつでも誰でも」という行き先と、きれいに一致したわ。ただし、**足すほど、手が回らなくなる**。そのツケは、次のステップで出るかもしれないわね。",mismatchReaction:"足す一方の打ち手は、行き先が「昼の会社員」や「規模」だと、むしろ邪魔になるわ。仕込みも接客も、分散してしまうの。"}]},{id:"watch",nodeLabel:"見直し",title:"ステップ3 ── 弱みへの手当てと、見直しの仕組み",question:"最後に、弱みと脅威への備えと、見直しの目印を決めます。ここまでの二つの選択と、「だから」でつながる仕上げはどれでしょう？",options:[{id:"gauge",emoji:"\uD83D\uDCCF",label:"手順書でひとり頼りを減らし、仕入先は二か所に。ものさしは「昼12時台の来店数」「提供時間」「常連さんの再来店」で、毎月確認する",short:"手順書・二か所仕入れ・毎月の点検",detail:"弱み\xd7脅威への備えと、ものさし",requires:["daily","core"],reaction:"来たわね！ 行き先、勝ち筋、備えと見直し。矢印の全部に「だから」が入ったわ。弱み（ひとり頼り・仕入先）への手当てと、**ずれに気づくためのものさし**まで入っているのが、いい物語の条件よ。",mismatchReaction:"備えと見直しの考え方は、立派よ。でも、行き先と勝ち筋に、うまくつながっていないわ。「何を確かめるための目印？」と聞かれたら、答えに困るでしょう？"},{id:"count",emoji:"\uD83D\uDCC8",label:"店舗数と売上の総額を、毎月確認する。規模が伸びていれば、順調とみなす",short:"店舗数と売上を毎月確認",detail:"規模を測るものさし",requires:["giant","scale"],reaction:"「規模」という行き先に、ものさしも合っているわ。ただ、**大将ひとりの腕**という弱みへの手当ては、物語に入っていないわね。",mismatchReaction:"店舗数や売上の総額は、いまの行き先や勝ち筋を確かめるものさしには、なりにくいわ。測っている数字が、物語とずれているの。"},{id:"mood",emoji:"\uD83D\uDC42",label:"お客さんの声を聞いて、反応が薄いものは、別のメニューを足して試す",short:"声を聞いて、足して試す",detail:"目印は決めず、その場で調整",requires:["allday","wide"],reaction:"「いつでも誰でも」には、その場の調整が自然ね。ただ、目印がないと、**足す一方で、引く判断**ができなくなるの。",mismatchReaction:"その場の調整だけでは、行き先と勝ち筋が出す「ずれ」には、気づけないわ。何を見直すのか、物語から決められないのよ。"}]}],endings:[{id:"great",emoji:"\uD83C\uDF1F",title:"分析が、一本の物語になった",quality:1,when:{firstPick:["daily"],matches:[2]},narration:"まんぷく弁当が開いた月。ひだまり亭の昼は、一時、少し落ち着きました。でも、大将は慌てません。「15分で、出来立て」を守り、手順書のおかげでパートさんが仕込みを支え、二か所目の仕入先も動き出しています。毎月の点検で、来店数と提供時間を確かめるのが、大将の新しい習慣になりました。「やることが決まってると、不安が減るな。ずれたら直せばいい、って思えるんだ」。",nana:"完璧な一周ね。**ありたい姿 → 勝ち筋（掛け合わせ＋やらないこと）→ 備えと見直し**。第1章のバラバラなチラシが、外（第4章）と内（第5章）の分析に支えられた、一本の物語になったわ。六つの視点が、ひとつにまとまったのよ。"},{id:"linked-giant",emoji:"\uD83C\uDFD7️",title:"筋は通ったけれど、相手の土俵で戦った",quality:.5,when:{firstPick:["giant"],matches:[2]},narration:"2号店を出し、店舗数は増えました。ところが、味にばらつきが出て、大将の目が届かない店では、常連さんが離れました。まんぷく弁当の仕入れ力と価格の前に、規模の勝負は、思ったより苦しいものでした。",nana:"矢印は、「だから」でつながっていたわ。そこは立派よ。でもね、**行き先が、分析と重なっていなかった**の。12席・大将ひとりの店が、資金も仕入れ力も桁違いの相手の土俵に、上がってしまったのよ。強みと機会から出発すれば、結果は違ったはずよ。"},{id:"linked-allday",emoji:"\uD83C\uDF19",title:"筋は通ったけれど、壁のチラシが戻ってきた",quality:.4,when:{firstPick:["allday"],matches:[2]},narration:"夜営業も、週末ランチも、品数も増やしました。ところが、夜の客足は伸びず、仕込みは膨らみ、昼の提供は遅くなりました。気づけば、壁には、また新しいチラシが並んでいました。",nana:"「いつでも誰でも」から「足す一方」へ。一貫してはいたけれど、**やらないことが、一つも決まっていない**のが原因よ。選ぶことは、捨てることでもあるの。第3章を、思い出してみて。"},{id:"half",emoji:"\uD83E\uDEA2",title:"途中で、筋が途切れた",quality:.4,when:{matches:[1]},narration:"最初のうちは、手応えがありました。でも、途中で選んだ打ち手と仕上げが噛み合わなくなり、現場は、何を目指しているのか分からなくなっていきました。",nana:"どこかで、「だから」が切れてしまったわね。**ありたい姿・勝ち筋・見直しは、三つで一組**。一つでも別の方向を向くと、全体が弱くなるの。もう一度、前の一手とのつながりを確かめてみて。"},{id:"scattered",emoji:"\uD83C\uDF00",title:"分析は立派なのに、使われなかった",quality:.1,narration:"ホワイトボードのSWOTは、とても立派でした。でも、行き先も、打ち手も、見直しも、それぞれ別の方向を向いていました。気づけば、分析は壁に貼られたまま、誰も見なくなっていました。",nana:"これが、第6章の最大の落とし穴よ。**分析をして、満足して、使わない**。もう一度、違う道を試してみましょう。やり直してもペナルティはないから、安心して。"}]},{kind:"quiz",id:"s6-quiz",title:"確認クイズ",intro:"戦略の組み立て方を確かめましょう。「なぜ？」の解説まで読むのが、いちばんの復習よ。",questions:[{id:"q1",scenario:"大将が、ひらめいた顔で言いました。「よし、新メニューを三つ思いついた。明日から出そう！」",question:"[[strategy-process|戦略の組み立て方]]として、**最初に**確かめたいことは、何でしょう？",options:[{text:"三つのメニューの原価と、仕込みの時間",feedback:"大事な確認だけれど、それは「実行」に近い段階の話よ。その前に、そもそも、やる意味があるかを確かめたいわ。"},{text:"まんぷく弁当の新メニューと値段を調べて、合わせる",feedback:"相手を見ることは大切よ。でも、相手に合わせるだけでは、自分の行き先が決まらないの。"},{text:"そのメニューが、ありたい姿とつながり、分析（外と内）から「だから」と言えるか",feedback:"その通り！ 打ち手から入る「思いつき型」を、順番の中に戻す問いよ。行き先と分析に「だから」でつながるなら、やる価値のある候補になるわ。"},{text:"ほかの店で人気のメニューを真似て、三つに絞る",feedback:"「隣がやっているから」は、第1章の壁のチラシと同じ思いつき型よ。理由が、あとづけになってしまうの。"}],answer:2,explanation:"戦略づくりは、**ありたい姿 → 分析 → 選択肢 → 選ぶ → 実行 → 見直し**の順。ひらめきは歓迎ですが、その打ち手を、行き先と分析に「だから」でつなげられるかを、最初に確かめます。つながらなければ、「保留箱」に入れておきます。"},{id:"q2",scenario:"付箋を貼る途中、大将が二枚を手にしました。「仕入先が、源さん一か所に偏っている」と、「源さんが、来月から魚を一割値上げすると言ってきた」。",question:"[[swot|SWOT]]では、この二枚を、どこに貼るのが適切でしょう？",options:[{text:"どちらも外のことなので、「脅威」に貼る",feedback:"値上げは外の出来事だから、脅威でいいわ。でも、「仕入先が一か所に偏っている」は、自分たちで直せることよ。"},{text:"前者は自分たちで直せるので「弱み」、後者は自分たちでは決められないので「脅威」",feedback:"その通り！ 迷ったら「自分たちで変えられる？」と聞く。同じ源さんの話でも、内と外で、貼る場所が分かれるわ。"},{text:"前者は「強み」（源さんと付き合いが深いから）、後者は「機会」",feedback:"付き合いの深さは強みでも、「一か所に偏っている」ことは弱みの顔を持つわ。値上げは向かい風だから、機会ではなく脅威よ。"}],answer:1,explanation:"分け方の目安は「**自分たちで変えられるか**」。変えられれば内（強み・弱み）、変えられなければ外（機会・脅威）です。仕入先の偏りは内の弱み、値上げは外の脅威。どちらに貼るかより、**それぞれに手を打つ**（二か所目の仕入先を探す、など）ことが大切です。"},{id:"q3",scenario:"戦略を実行して二か月。まんぷく弁当が開店し、事前に決めておいた目印「昼12時台の来店数」が、三週続けて下限を割りました。",question:"見直しとして、いちばん筋のいい動き方は、どれでしょう？",options:[{text:"「誤差の範囲」として、下限を引き下げ、割っていないことにする",feedback:"それをしてしまうと、ものさしの意味がなくなるわ。基準は、実行する前に決めておくものよ。"},{text:"物語が間違いだったと考えて、ありたい姿から全部やり直す",feedback:"全部を捨てる必要はないわ。変わった所から順に直すほうが、早くて確実よ。"},{text:"落ち込みを埋めるために、夜営業と値下げを始める",feedback:"「やらない」と決めたことを、ずれが出たとたんに破るのは、物語を壊す動きよ。"},{text:"まず外の前提（五つの力）が変わったかを確かめ、次に強みが効いているかを見て、必要な所だけ直す",feedback:"その通り！ 外 → 内 → 打ち手、の順に戻るのが、見直しの基本よ。まんぷく弁当という外の変化から、確かめていくの。"}],answer:3,explanation:"見直しの順番は、**外 → 内 → 打ち手**。まず、まんぷく弁当の影響など、外の前提を確かめ、次に強み（煮物の腕・常連さんの記憶）が今も効いているかを見て、最後に、やること・やらないことを入れ替えます。ものさしの基準は、事前に決めたまま動かさないのが鉄則です。"}]},{kind:"summary",id:"s6-summary",title:"今日の学びを、一枚に",points:[{title:"戦略は、旅の計画のように、順番に組み立てる",text:"ありたい姿 → 分析 → 選択肢 → 選ぶ → 実行 → 見直し。この[[strategy-process]]を、行きつ戻りつ回します。順番を飛ばすと、思いつきか、動けない分析になります。"},{title:"まず、行き先（ビジョン）を決める",text:"[[vision]]は、分析で「何を見るか」を決める羅針盤。強みや機会と無理なく重なる、手が届く姿にします。"},{title:"外と内を、一枚にまとめる",text:"[[environment-analysis]]は、外（第4章）と内（第5章）の両方を見ること。それを四つの枠に置いたのが[[swot]]です。迷ったら「自分たちで変えられる？」と聞きます。"},{title:"並べたら、掛け合わせて、選ぶ",text:"強み\xd7機会は攻め、強み\xd7脅威は差別化、弱み\xd7機会は補強、弱み\xd7脅威は守り。出た候補から、ありたい姿と「だから」でつながるものだけを選び、やらないことも決めます。"},{title:"「だから」で束ねて、ものさしで見直す",text:"選んだことを[[strategy-story]]に束ね、見直しの目印を先に決めます。ずれたら、外 → 内 → 打ち手の順に直します。"}],why:{title:"なぜ、これが大事なのか",text:"分析をたくさんやっても、使われなければ意味がありません。**分析を、行動に変える橋が、物語**です。一本の筋があれば、迷ったときに戻る場所ができ、新しい情報が入っても、どこを直せばいいかが分かります。「**いま、どの段階か**」を言えることが、判断の迷子を防ぎます。"},nana:[{who:"nana",mood:"proud",text:"お疲れさま。今日は、これまでの道具を一本の筋に束ねる、組み立ての旅だったわね。"},{who:"you",mood:"smile",text:"はい。バラバラだった道具が、順番に並べると、ちゃんと一本の物語になるのが、不思議でした。"},{who:"nana",mood:"smile",text:"第1章のチラシの壁と、今日の物語。違いは、「だから」と、「やらないこと」と、「ものさし」よ。そこに気づけたなら、もう十分に使えるわ。"}]}],clear:{perspective:{icon:"\uD83E\uDDE9",name:"物語に束ねる目",tagline:"分析を、筋のある一本にする",description:"バラバラな分析結果を、「だから」でつながる一本の物語にまとめられるようになりました。会議で「分析は出た。で、結局どうする？」と聞こえたら、ありたい姿・勝ち筋・見直しの三つが、つながっているかを、そっと確かめてみてください。",checks:["分析の結果は、一本の筋になっている？","やることと、やらないことは決まった？","見直すタイミングと、ものさしは決めてある？"]},nana:[{who:"nana",mood:"smile",text:"おめでとう、{san}。第6の視点「物語に束ねる目」を手に入れたわね。分析を見たときは、「で、どんな筋になる？」と問いかけてみて。"},{who:"you",mood:"smile",text:"はい！ 「いま、どの段階か」を、まず言えるようにしてみます。"},{who:"nana",mood:"proud",text:"これで、六つの視点が、すべてそろったわ。物語、地図、立ち位置、戦場、武器、そして束ねる目。最後は、ひだまり亭にもう一度向き合う、最終試験よ。"}],teaser:"最終ステージ：灯台の町の最終試験 ─ 六つの視点で、ひだまり亭にもう一度向き合います。"}}],n=a.map(e=>e.id),l=i,s=[...a,l];function r(e){return s.find(t=>t.id===e)}}}]);